import { NextRequest, NextResponse } from 'next/server'
import { revalidateTag, revalidatePath } from 'next/cache'

// Chave de segurança para acesso administrativo
const ADMIN_SECRET = process.env.ADMIN_SECRET || 'admin-secret-key'

export async function POST(request: NextRequest) {
  try {
    const { secret, type, target } = await request.json()

    // Verificar autorização
    if (secret !== ADMIN_SECRET) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const buildId = process.env.BUILD_ID || 'development'
    const timestamp = new Date().toISOString()

    switch (type) {
      case 'tag':
        if (!target) {
          return NextResponse.json(
            { error: 'Tag target is required' },
            { status: 400 }
          )
        }
        revalidateTag(target)
        // Cache flush by tag - operation completed
        return NextResponse.json({
          success: true,
          message: `Cache flushed successfully`,
          type,
          target,
          buildId,
          timestamp,
        })
        break

      case 'path':
        if (!target) {
          return NextResponse.json(
            { error: 'Path target is required' },
            { status: 400 }
          )
        }
        revalidatePath(target)
        // Cache flush by path - operation completed
        return NextResponse.json({
          success: true,
          message: `Cache flushed successfully`,
          type,
          target,
          buildId,
          timestamp,
        })
        break

      case 'all':
        // Flush de todas as tags comuns
        const commonTags = [
          'nutritionists',
          'specialties',
          'appointments',
          'profiles',
          'dashboard',
          'blog',
          'forum',
        ]

        commonTags.forEach(tag => revalidateTag(tag))

        // Flush de paths comuns
        const commonPaths = [
          '/',
          '/dashboard',
          '/nutricionistas',
          '/blog',
          '/api/specialties',
        ]

        commonPaths.forEach(path => revalidatePath(path))

        // Full cache flush - operation completed
        return NextResponse.json({
          success: true,
          message: `Cache flushed successfully`,
          type,
          target,
          buildId,
          timestamp,
        })
        break

      default:
        return NextResponse.json(
          { error: 'Invalid flush type. Use: tag, path, or all' },
          { status: 400 }
        )
    }

    return NextResponse.json({
      success: true,
      message: `Cache flushed successfully`,
      type,
      target,
      buildId,
      timestamp,
    })
  } catch (error) {
    // Cache flush error - handled silently
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    )
  }
}

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url)
  const secret = searchParams.get('secret')

  if (secret !== ADMIN_SECRET) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const buildId = process.env.BUILD_ID || 'development'
  const nodeEnv = process.env.NODE_ENV || 'development'

  return NextResponse.json({
    status: 'Cache management endpoint active',
    buildId,
    environment: nodeEnv,
    timestamp: new Date().toISOString(),
    availableActions: [
      'POST /api/admin/cache-flush - Flush cache by tag, path, or all',
      'GET /api/admin/cache-flush - Get cache status',
    ],
  })
}

import { GoogleGenerativeAI } from '@google/generative-ai'

export async function POST(req: Request) {
  try {
    const { messages } = await req.json()

    // Inicializar o cliente do Gemini
    const genAI = new GoogleGenerativeAI(process.env.GEMINI_API_KEY!)
    const model = genAI.getGenerativeModel({ model: 'gemini-1.5-flash' })

    // Configurar o prompt do sistema
    const systemPrompt = `🤖 IDENTIDADE DA ASSISTENTE
Você é a IrisBot, a assistente virtual inteligente e ética da plataforma BuscaNutri.

Seu papel é oferecer:
- Informações educativas e técnicas sobre Nutrição
- Apoio à navegação e uso das funcionalidades do dashboard BuscaNutri
- Recomendações de especialidades nutricionais com base nas dúvidas ou sintomas relatados, sem realizar diagnósticos ou prescrição nutricional individualizada
- Indicações de profissionais disponíveis na plataforma, sempre que necessário

Você possui autoaprendizado com base nas interações realizadas e em todo o conteúdo público, educativo e funcional presente na BuscaNutri.

📝 FORMATAÇÃO DE TEXTO
IMPORTANTE: Você pode usar formatação de texto para melhorar a legibilidade das suas respostas:
- Use **negrito** para destacar informações importantes
- Use *itálico* para enfatizar conceitos
- Use espaçamento adequado entre parágrafos
- Organize informações em listas quando apropriado
- NUNCA use asteriscos (*) no início de frases ou textos
- Evite formatação excessiva que possa prejudicar a leitura

🎯 FUNÇÕES PRINCIPAIS DA IRISBOT

1. **Compreensão de contexto**: Entende a intenção do usuário, se está buscando ajuda para um sintoma, funcionalidade, estudo de caso ou orientação profissional.

2. **Sugestão de especialidade nutricional**:
   Quando o usuário relata sintomas ou condições, a IrisBot sugere a especialidade nutricional mais adequada (ex: materno-infantil, esportiva, funcional, renal, comportamental, etc.).

   **Exemplo**:
   Usuário: "Tenho muito inchaço nas pernas e pressão alta."
   IrisBot: "Esses sintomas podem estar relacionados a questões clínicas que envolvem o sistema cardiovascular e retenção de líquidos. Um(a) nutricionista especializado(a) em **Nutrição Clínica** com foco em doenças crônicas pode ser a melhor opção. Posso te mostrar profissionais com esse perfil aqui na BuscaNutri?"

3. **Integração com o dashboard da plataforma BuscaNutri**:
   A IrisBot conhece e acessa (ou orienta a acessar) seções como:
   - Diretório de nutricionistas
   - Agendamento de consultas
   - Biblioteca de artigos, cursos e ebooks
   - Área de acompanhamento de pacientes
   - Relatórios e métricas (para nutricionistas)
   - Mensagens e notificações
   - Fórum ou espaço de perguntas

4. **Limitação ética rigorosa**:
   - Nunca prescreve dietas, quantidades, cardápios, suplementos ou medicamentos
   - Sempre orienta a busca por um nutricionista da plataforma quando a dúvida envolve saúde individual

🌟 CAPACIDADES COMPORTAMENTAIS
- Respostas humanizadas, com empatia e linguagem acessível
- Tom técnico, mas claro — adaptável ao perfil do usuário (paciente, estudante ou nutricionista)
- Sabe quando recuar e indicar apoio humano
- Aprende com os dados públicos e feedbacks das interações anteriores

📋 EXEMPLOS DE FLUXOS COM INDICAÇÃO DE ESPECIALIDADE

🟢 **Usuário (Paciente)**: "Meu filho de 3 anos não quer comer frutas de jeito nenhum."
🔵 **IrisBot**: "Isso pode estar relacionado a uma fase comum de seletividade alimentar infantil. O ideal é buscar um(a) nutricionista com especialização em **Nutrição Materno-Infantil**. Posso te mostrar quem está disponível aqui na BuscaNutri?"

🟢 **Usuário (Paciente)**: "Tenho SOP e dificuldade para emagrecer. Qual dieta devo seguir?"
🔵 **IrisBot**: "Casos de Síndrome dos Ovários Policísticos exigem acompanhamento nutricional personalizado. Um(a) nutricionista especializado(a) em **Nutrição Funcional** ou **Nutrição Hormonal** pode ajudar. Deseja que eu mostre os profissionais com esse foco?"

🟢 **Usuário (Profissional)**: "Como acesso os relatórios de evolução dos meus pacientes?"
🔵 **IrisBot**: "No seu dashboard, vá até a aba **"Pacientes"** e selecione o nome desejado. Depois clique em **"Evolução"**. Lá você encontrará os registros alimentares, gráficos e histórico. Posso abrir essa seção para você agora?"

💬 **MENSAGEM PADRÃO PARA LIMITES ÉTICOS**:
"Essa questão envolve avaliação individualizada. Por isso, é importante que você agende uma consulta com um(a) nutricionista qualificado(a). Posso te ajudar a encontrar um agora mesmo aqui na plataforma BuscaNutri!"

🧩 **ESPECIALIDADES QUE A IRISBOT PODE INDICAR**:

| Situação Relatada | Especialidade Indicada |
|-------------------|------------------------|
| Dificuldade para emagrecer, resistência à insulina | Nutrição funcional / metabólica |
| Problemas gastrointestinais (inchaço, constipação) | Nutrição clínica / digestiva |
| Alimentação na infância | Nutrição materno-infantil |
| Atividade física, performance esportiva | Nutrição esportiva |
| Pré-natal, gestação, amamentação | Nutrição obstétrica / materno-infantil |
| Doenças renais | Nutrição nefrológica |
| Comportamento alimentar, compulsão, transtornos | Nutrição comportamental / TCA |
| Alimentação vegetariana ou vegana | Nutrição vegetariana / sustentável |
| Pós-bariátrica, suplementação específica | Nutrição clínica especializada em bariátrica |

*Obs: A lista pode crescer conforme novas especializações forem cadastradas no sistema.*`

    // Converter mensagens para o formato do Gemini
    const lastMessage = messages[messages.length - 1]
    const conversationHistory = messages
      .slice(0, -1)
      .map(
        (msg: any) =>
          `${msg.role === 'user' ? 'Usuário' : 'Iris'}: ${msg.content}`
      )
      .join('\n')

    const fullPrompt = `${systemPrompt}

Histórico da conversa:
${conversationHistory}

Usuário: ${lastMessage.content}

Iris:`

    // Gerar resposta com streaming
    const result = await model.generateContentStream(fullPrompt)

    // Criar um ReadableStream para streaming da resposta
    const encoder = new TextEncoder()
    const stream = new ReadableStream({
      async start(controller) {
        try {
          for await (const chunk of result.stream) {
            const chunkText = chunk.text()
            if (chunkText) {
              controller.enqueue(
                encoder.encode(
                  `data: ${JSON.stringify({ content: chunkText })}\n\n`
                )
              )
            }
          }
          controller.enqueue(encoder.encode('data: [DONE]\n\n'))
          controller.close()
        } catch (error) {
          // Streaming error - silent error handling
          controller.error(error)
        }
      },
    })

    return new Response(stream, {
      headers: {
        'Content-Type': 'text/plain; charset=utf-8',
        'Cache-Control': 'no-cache',
        Connection: 'keep-alive',
      },
    })
  } catch (error) {
    // Chat API error - silent error handling
    return NextResponse.json(
      { error: 'Erro interno do servidor' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@supabase/supabase-js'

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!
const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY!

export async function DELETE(request: NextRequest) {
  try {
    // Verificar variáveis de ambiente
    if (!supabaseUrl || !supabaseServiceKey) {
      // Supabase environment variables not configured - silent error handling
      return NextResponse.json(
        { error: 'Configuração do servidor incompleta' },
        { status: 500 }
      )
    }

    // Criar cliente Supabase com service role
    const supabase = createClient(supabaseUrl, supabaseServiceKey, {
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
    })

    // Parse do body
    const { documentId, userId, accessToken } = await request.json()

    // Deleting document - silent operation

    // Validações básicas
    if (!documentId || !userId || !accessToken) {
      return NextResponse.json(
        { error: 'documentId, userId e accessToken são obrigatórios' },
        { status: 400 }
      )
    }

    // Validar access token
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken)
    if (authError || !user || user.id !== userId) {
      // Authentication error - silent error handling
      return NextResponse.json(
        { error: 'Token de acesso inválido' },
        { status: 401 }
      )
    }

    // Verificar se o usuário é nutricionista
    const { data: userData, error: userError } = await supabase
      .from('users')
      .select('user_type')
      .eq('id', userId)
      .single()

    if (userError || userData?.user_type !== 'nutricionista') {
      // User is not a nutritionist - silent error handling
      return NextResponse.json(
        { error: 'Apenas nutricionistas podem deletar documentos' },
        { status: 403 }
      )
    }

    // Buscar o documento
    const { data: document, error: docError } = await supabase
      .from('nutritionist_documents')
      .select('*')
      .eq('id', documentId)
      .eq('nutritionist_id', userId)
      .single()

    if (docError || !document) {
      // Document not found - silent error handling
      return NextResponse.json(
        { error: 'Documento não encontrado' },
        { status: 404 }
      )
    }

    // Verificar se é comprovante de CRN (não pode ser deletado)
    if (document.document_type === 'crn_proof') {
      return NextResponse.json(
        {
          error:
            'Comprovante de CRN não pode ser removido. Apenas substituído.',
        },
        { status: 403 }
      )
    }

    // Deletar arquivo do storage
    const { error: storageError } = await supabase.storage
      .from('documentos-nutricionistas')
      .remove([document.storage_path])

    if (storageError) {
      // Error deleting file from storage - silent error handling
      // Continua mesmo com erro no storage para não deixar registro órfão
    }

    // Deletar registro do banco
    const { error: deleteError } = await supabase
      .from('nutritionist_documents')
      .delete()
      .eq('id', documentId)
      .eq('nutritionist_id', userId)

    if (deleteError) {
      // Error deleting document from database - silent error handling
      return NextResponse.json(
        { error: 'Erro ao deletar documento' },
        { status: 500 }
      )
    }

    // Document deleted successfully - silent operation

    return NextResponse.json({
      success: true,
      message: 'Certificado removido com sucesso',
    })
  } catch (error) {
    // Error deleting document - silent error handling
    return NextResponse.json(
      { error: 'Erro interno do servidor' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@supabase/supabase-js'

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!
const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY!

export async function GET(request: NextRequest) {
  try {
    // Verificar variáveis de ambiente
    if (!supabaseUrl || !supabaseServiceKey) {
      // Supabase environment variables not configured - silent error handling
      return NextResponse.json(
        { error: 'Configuração do servidor incompleta' },
        { status: 500 }
      )
    }

    // Criar cliente Supabase com service role
    const supabase = createClient(supabaseUrl, supabaseServiceKey, {
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
    })

    // Extrair parâmetros da URL
    const { searchParams } = new URL(request.url)
    const userId = searchParams.get('userId')
    const accessToken = searchParams.get('accessToken')
    const documentType = searchParams.get('documentType') // 'crn_proof', 'certificate', ou null para todos

    // Searching documents - silent operation

    // Validações básicas
    if (!userId || !accessToken) {
      return NextResponse.json(
        { error: 'userId e accessToken são obrigatórios' },
        { status: 400 }
      )
    }

    // Validar access token
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken)
    if (authError || !user || user.id !== userId) {
      // Authentication error - silent error handling
      return NextResponse.json(
        { error: 'Token de acesso inválido' },
        { status: 401 }
      )
    }

    // Verificar se o usuário é nutricionista
    const { data: userData, error: userError } = await supabase
      .from('users')
      .select('user_type')
      .eq('id', userId)
      .single()

    if (userError || userData?.user_type !== 'nutricionista') {
      // User is not a nutritionist - silent error handling
      return NextResponse.json(
        { error: 'Apenas nutricionistas podem acessar documentos' },
        { status: 403 }
      )
    }

    // Construir query
    let query = supabase
      .from('nutritionist_documents')
      .select('*')
      .eq('nutritionist_id', userId)
      .order('created_at', { ascending: false })

    // Filtrar por tipo se especificado
    if (documentType) {
      query = query.eq('document_type', documentType)
    }

    // Executar query
    const { data: documents, error: docsError } = await query

    if (docsError) {
      // Error fetching documents - silent error handling
      return NextResponse.json(
        { error: 'Erro ao buscar documentos' },
        { status: 500 }
      )
    }

    // Found documents - silent operation
    return NextResponse.json({
      success: true,
      documents: documents || [],
    })
  } catch (error) {
    // Error fetching documents - silent error handling
    return NextResponse.json(
      { error: 'Erro interno do servidor' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'

export async function POST(request: NextRequest) {
  try {
    const supabase = createClient()
    const { nutritionist_id, specialty_ids } = await request.json()

    if (!nutritionist_id || !Array.isArray(specialty_ids)) {
      return NextResponse.json(
        { error: 'nutritionist_id e specialty_ids são obrigatórios' },
        { status: 400 }
      )
    }

    // Verificar se o usuário está autenticado e é o próprio nutricionista
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser()

    if (authError || !user) {
      return NextResponse.json(
        { error: 'Usuário não autenticado' },
        { status: 401 }
      )
    }

    if (user.id !== nutritionist_id) {
      return NextResponse.json({ error: 'Não autorizado' }, { status: 403 })
    }

    // Remover especialidades existentes
    const { error: deleteError } = await supabase
      .from('nutritionist_specialties')
      .delete()
      .eq('nutritionist_id', nutritionist_id)

    if (deleteError) {
      // Error removing existing specialties - silent error handling
      return NextResponse.json(
        { error: 'Erro ao remover especialidades existentes' },
        { status: 500 }
      )
    }

    // Inserir novas especialidades
    if (specialty_ids.length > 0) {
      const specialtiesToInsert = specialty_ids.map((specialty_id: string) => ({
        nutritionist_id,
        specialty_id,
      }))

      const { error: insertError } = await supabase
        .from('nutritionist_specialties')
        .insert(specialtiesToInsert)

      if (insertError) {
        // Error inserting specialties - silent error handling
        return NextResponse.json(
          { error: 'Erro ao inserir especialidades' },
          { status: 500 }
        )
      }
    }

    return NextResponse.json({
      message: 'Especialidades salvas com sucesso',
      count: specialty_ids.length,
    })
  } catch (error) {
    // Internal error saving specialties - silent error handling
    return NextResponse.json(
      { error: 'Erro interno do servidor' },
      { status: 500 }
    )
  }
}

export async function GET(request: NextRequest) {
  try {
    const supabase = createClient()
    const { searchParams } = new URL(request.url)
    const nutritionist_id = searchParams.get('nutritionist_id')

    if (!nutritionist_id) {
      return NextResponse.json(
        { error: 'nutritionist_id é obrigatório' },
        { status: 400 }
      )
    }

    // Buscar especialidades do nutricionista
    const { data: nutritionistSpecialties, error } = await supabase
      .from('nutritionist_specialties')
      .select(
        `
        specialty_id,
        specialties (
          id,
          name,
          description
        )
      `
      )
      .eq('nutritionist_id', nutritionist_id)

    if (error) {
      // Error fetching nutritionist specialties - silent error handling
      return NextResponse.json(
        { error: 'Erro ao buscar especialidades' },
        { status: 500 }
      )
    }

    const specialties =
      nutritionistSpecialties?.map(ns => ns.specialties).filter(Boolean) || []

    return NextResponse.json({
      specialties,
      specialty_ids: nutritionistSpecialties?.map(ns => ns.specialty_id) || [],
      total: specialties.length,
    })
  } catch (error) {
    // Error in specialties endpoint - silent error handling
    return NextResponse.json(
      { error: 'Erro interno do servidor' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'

export async function GET(request: NextRequest) {
  try {
    const supabase = createClient()

    // Buscar todas as especialidades ordenadas alfabeticamente
    const { data: specialties, error } = await supabase
      .from('specialties')
      .select('id, name, description')
      .order('name', { ascending: true })

    if (error) {
      // Error loading specialties - handled silently
      return NextResponse.json(
        { error: 'Erro ao buscar especialidades' },
        { status: 500 }
      )
    }

    return NextResponse.json({
      specialties: specialties || [],
      total: specialties?.length || 0,
    })
  } catch (error) {
    // Internal error loading specialties - handled silently
    return NextResponse.json(
      { error: 'Erro interno do servidor' },
      { status: 500 }
    )
  }
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'

export async function POST(request: NextRequest) {
  try {
    // Verificar se as variáveis de ambiente estão disponíveis
    if (
      !process.env.NEXT_PUBLIC_SUPABASE_URL ||
      !process.env.SUPABASE_SERVICE_ROLE_KEY
    ) {
      // Environment variables not found - silent error handling
      return NextResponse.json(
        { error: 'Configuração do servidor incompleta' },
        { status: 500 }
      )
    }

    // Criar cliente Supabase com service role
    const supabase = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL,
      process.env.SUPABASE_SERVICE_ROLE_KEY,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    )

    // Obter dados do FormData
    const formData = await request.formData()
    const file = formData.get('file') as File
    const userId = formData.get('userId') as string
    const accessToken = formData.get('accessToken') as string

    if (!file || !userId || !accessToken) {
      return NextResponse.json(
        { success: false, error: 'Dados obrigatórios não fornecidos' },
        { status: 400 }
      )
    }

    // Verificar se o token de acesso é válido
    const { data: user, error: userError } =
      await supabase.auth.getUser(accessToken)

    if (userError || !user) {
      // Invalid token or unauthorized user - silent error handling
      return NextResponse.json(
        { error: 'Token inválido ou usuário não autorizado' },
        { status: 401 }
      )
    }

    // Validar tipo de arquivo (incluindo mais formatos WebP)
    const allowedTypes = [
      'image/jpeg',
      'image/jpg',
      'image/png',
      'image/webp',
      'image/gif',
      'image/avif',
    ]
    if (!allowedTypes.includes(file.type)) {
      return NextResponse.json(
        {
          success: false,
          error:
            'Tipo de arquivo não permitido. Use JPEG, PNG, WebP, AVIF ou GIF.',
        },
        { status: 400 }
      )
    }

    // Validar tamanho do arquivo (10MB máximo para melhor qualidade)
    const maxSize = 10 * 1024 * 1024 // 10MB
    if (file.size > maxSize) {
      return NextResponse.json(
        {
          success: false,
          error: 'Arquivo muito grande. Tamanho máximo: 10MB.',
        },
        { status: 400 }
      )
    }

    // Gerar nome único para o arquivo
    const fileExtension = file.name.split('.').pop()
    const fileName = `${userId}/${Date.now()}-${Math.random().toString(36).substring(2)}.${fileExtension}`

    // Silent upload process

    // Converter File para ArrayBuffer
    const arrayBuffer = await file.arrayBuffer()
    const buffer = new Uint8Array(arrayBuffer)

    // Fazer upload do arquivo
    const { data, error } = await supabase.storage
      .from('blog-images')
      .upload(fileName, buffer, {
        contentType: file.type,
        cacheControl: '3600',
        upsert: false,
      })

    if (error) {
      // Upload error - silent error handling
      return NextResponse.json(
        { error: 'Erro no upload da imagem' },
        { status: 500 }
      )
    }

    // Upload successful - silent operation
    const { data: urlData } = supabase.storage
      .from('blog-images')
