              sobre nutrição e saúde para transformar sua vida
            </p>

            {/* Search Bar */}
            <div className="relative max-w-2xl mx-auto mb-6">
              <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 h-5 w-5" />
              <Input
                type="text"
                placeholder="Buscar artigos, temas ou palavras-chave..."
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
                className="pl-12 pr-4 py-4 text-lg rounded-full border-2 border-gray-200 focus:border-[#4AB0D9] focus:ring-0"
              />
            </div>

            {/* Stats */}
            <div className="flex justify-center gap-8 text-sm text-gray-500">
              <span>{allBlogPosts.length} artigos publicados</span>
              <span>{blogCategories.length} categorias</span>
              <span>Atualizado semanalmente</span>
            </div>
          </div>
        </div>
      </div>

      <div className="container mx-auto px-4 py-12">
        {/* Enhanced Filters */}
        <div className="bg-white rounded-2xl shadow-lg p-6 mb-12 border">
          <div className="flex flex-col lg:flex-row gap-6 items-center justify-between">
            {/* Categories */}
            <div className="flex flex-wrap gap-2">
              {['Todos', ...blogCategories].map(category => (
                <Button
                  key={category}
                  variant={
                    category === selectedCategory ? 'default' : 'outline'
                  }
                  size="sm"
                  onClick={() => setSelectedCategory(category)}
                  className={`transition-all duration-200 ${
                    category === selectedCategory
                      ? 'bg-[#4AB0D9] hover:bg-[#4AB0D9]/90 shadow-md'
                      : 'hover:bg-gray-50 border-gray-200'
                  }`}
                >
                  {category}
                  {category !== 'Todos' && (
                    <Badge variant="secondary" className="ml-2 text-xs">
                      {
                        allBlogPosts.filter(post => post.category === category)
                          .length
                      }
                    </Badge>
                  )}
                </Button>
              ))}
            </div>

            {/* Controls */}
            <div className="flex items-center gap-4">
              <Select value={sortBy} onValueChange={setSortBy}>
                <SelectTrigger className="w-48">
                  <Filter className="h-4 w-4 mr-2" />
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {sortOptions.map(option => (
                    <SelectItem key={option.value} value={option.value}>
                      {option.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>

              <div className="flex border rounded-lg">
                <Button
                  variant={viewMode === 'grid' ? 'default' : 'ghost'}
                  size="sm"
                  onClick={() => setViewMode('grid')}
                  className="rounded-r-none"
                >
                  <Grid className="h-4 w-4" />
                </Button>
                <Button
                  variant={viewMode === 'list' ? 'default' : 'ghost'}
                  size="sm"
                  onClick={() => setViewMode('list')}
                  className="rounded-l-none"
                >
                  <List className="h-4 w-4" />
                </Button>
              </div>
            </div>
          </div>

          {/* Results Info */}
          <div className="mt-4 pt-4 border-t text-sm text-gray-600">
            Mostrando {Math.min(regularPosts.length, visiblePosts)} de{' '}
            {filteredAndSortedPosts.length} artigos
            {searchTerm && (
              <span className="ml-2">
                para "<strong>{searchTerm}</strong>"
              </span>
            )}
          </div>
        </div>

        {/* Featured Post */}
        {featuredPost && selectedCategory === 'Todos' && !searchTerm && (
          <div className="mb-16">
            <div className="flex items-center gap-3 mb-8">
              <div className="h-1 w-12 bg-[#4AB0D9] rounded"></div>
              <h2 className="text-3xl font-bold text-[#1E1D40]">
                Artigo em Destaque
              </h2>
            </div>

            <Card className="overflow-hidden hover:shadow-2xl transition-all duration-300 border-0 shadow-lg">
              <div className="lg:flex">
                <div className="lg:w-1/2 relative">
                  <Image
                    src={featuredPost.image || '/placeholder.svg'}
                    alt={featuredPost.title}
                    width={500}
                    height={300}
                    className="w-full h-80 lg:h-full object-cover"
                  />
                  <div className="absolute top-4 left-4">
                    <Badge className="bg-red-500 text-white">⭐ Destaque</Badge>
                  </div>
                </div>
                <div className="lg:w-1/2 p-8 lg:p-12">
                  <div className="flex items-center gap-3 mb-6">
                    <Badge
                      variant="secondary"
                      className="bg-[#4AB0D9]/10 text-[#4AB0D9] px-3 py-1"
                    >
                      {featuredPost.category}
                    </Badge>
                    <Badge variant="outline" className="text-gray-600">
                      {getUpdatedViews(featuredPost).toLocaleString()}{' '}
                      visualizações
                    </Badge>
                  </div>

                  <h3 className="text-3xl font-bold text-[#1E1D40] mb-4 leading-tight">
                    {featuredPost.title}
                  </h3>

                  <p className="text-gray-600 mb-6 text-lg leading-relaxed">
                    {featuredPost.excerpt}
                  </p>

                  <div className="flex items-center gap-6 text-sm text-gray-500 mb-8">
                    <div className="flex items-center gap-2">
                      <User className="h-4 w-4" />
                      {featuredPost.author}
                    </div>
                    <div className="flex items-center gap-2">
                      <Calendar className="h-4 w-4" />
                      {new Date(featuredPost.date).toLocaleDateString('pt-BR')}
                    </div>
                    <div className="flex items-center gap-2">
                      <Clock className="h-4 w-4" />
                      {featuredPost.readTime}
                    </div>
                  </div>

                  <Link href={`/blog/${featuredPost.id}`}>
                    <Button className="bg-[#4AB0D9] hover:bg-[#4AB0D9]/90 text-white px-8 py-3 rounded-full text-lg font-medium transition-all duration-200 hover:shadow-lg">
                      Ler Artigo Completo
                      <ArrowRight className="ml-2 h-5 w-5" />
                    </Button>
                  </Link>
                </div>
              </div>
            </Card>
          </div>
        )}

        {/* Regular Posts Grid */}
        <div className="mb-16">
          <div className="flex items-center gap-3 mb-8">
            <div className="h-1 w-12 bg-[#4AB0D9] rounded"></div>
            <h2 className="text-3xl font-bold text-[#1E1D40]">
              {selectedCategory === 'Todos'
                ? 'Todos os Artigos'
                : `Categoria: ${selectedCategory}`}
            </h2>
          </div>

          {regularPosts.length === 0 ? (
            <div className="text-center py-16">
              <div className="text-gray-400 mb-4">
                <Search className="h-16 w-16 mx-auto" />
              </div>
              <h3 className="text-xl font-semibold text-gray-600 mb-2">
                Nenhum artigo encontrado
              </h3>
              <p className="text-gray-500">
                {searchTerm
                  ? `Não encontramos artigos para "${searchTerm}"`
                  : 'Não há artigos nesta categoria no momento'}
              </p>
            </div>
          ) : (
            <div
              className={
                viewMode === 'grid'
                  ? 'grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8'
                  : 'space-y-6'
              }
            >
              {regularPosts.map(post => (
                <Card
                  key={post.id}
                  className={`overflow-hidden hover:shadow-xl transition-all duration-300 border-0 shadow-md group ${
                    viewMode === 'list' ? 'flex' : ''
                  }`}
                >
                  <div className={viewMode === 'list' ? 'w-1/3' : ''}>
                    <div className="relative">
                      <Image
                        src={post.image || '/placeholder.svg'}
                        alt={post.title}
                        width={400}
                        height={250}
                        className={`object-cover group-hover:scale-105 transition-transform duration-300 ${
                          viewMode === 'list' ? 'h-full w-full' : 'w-full h-48'
                        }`}
                      />
                      <div className="absolute top-3 left-3">
                        <Badge
                          variant="secondary"
                          className="bg-white/90 text-gray-700"
                        >
                          {post.category}
                        </Badge>
                      </div>
                    </div>
                  </div>

                  <CardContent
                    className={`p-6 ${viewMode === 'list' ? 'flex-1' : ''}`}
                  >
                    <div className="flex items-center gap-2 mb-3">
                      <Badge
                        variant="outline"
                        className="text-xs text-gray-600"
                      >
                        {getUpdatedViews(post).toLocaleString()} visualizações
                      </Badge>
                      <div className="flex items-center gap-4 text-xs text-gray-500">
                        <div className="flex items-center gap-1">
                          <Calendar className="h-3 w-3" />
                          {new Date(post.date).toLocaleDateString('pt-BR')}
                        </div>
                        <div className="flex items-center gap-1">
                          <Clock className="h-3 w-3" />
                          {post.readTime}
                        </div>
                      </div>
                    </div>

                    <h3 className="text-xl font-bold text-[#1E1D40] mb-3 line-clamp-2 group-hover:text-[#4AB0D9] transition-colors">
                      {post.title}
                    </h3>

                    <p className="text-gray-600 mb-4 line-clamp-3">
                      {post.excerpt}
                    </p>

                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2 text-sm text-gray-500">
                        <User className="h-4 w-4" />
                        {post.author}
                      </div>

                      <Link href={`/blog/${post.id}`}>
                        <Button
                          variant="ghost"
                          size="sm"
                          className="text-[#4AB0D9] hover:text-[#4AB0D9]/80 hover:bg-[#4AB0D9]/10 p-2"
                        >
                          <ArrowRight className="h-4 w-4" />
                        </Button>
                      </Link>
                    </div>

                    {/* Tags */}
                    <div className="flex flex-wrap gap-1 mt-4">
                      {post.tags.slice(0, 3).map(tag => (
                        <Badge key={tag} variant="outline" className="text-xs">
                          {tag}
                        </Badge>
                      ))}
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </div>

        {/* Load More Button */}
        {regularPosts.length > 0 &&
          visiblePosts < filteredAndSortedPosts.length && (
            <div className="text-center">
              <Button
                onClick={loadMorePosts}
                variant="outline"
                size="lg"
                className="px-8 py-3 text-[#4AB0D9] border-[#4AB0D9] hover:bg-[#4AB0D9] hover:text-white transition-all duration-200"
              >
                Carregar Mais Artigos (
                {filteredAndSortedPosts.length - visiblePosts} restantes)
              </Button>
            </div>
          )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Checkbox } from '@/components/ui/checkbox'
import { Badge } from '@/components/ui/badge'
import { Trash2, Plus, MapPin, Home } from 'lucide-react'
import { toast } from '@/components/ui/use-toast'
import { nutritionistAddressService } from '@/lib/nutritionist-address-service'
import { useUser } from '@/hooks/use-user'

export interface AddressData {
  id?: string
  nutritionist_id?: string
  type: 'in_person' | 'teleconsultation'
  status: 'active' | 'inactive'
  is_main: boolean
  country: string
  state: string
  city: string
  neighborhood?: string
  zip_code?: string
  street?: string
  number?: string
  complement?: string
  latitude?: number
  longitude?: number
  service_radius_km?: number
}

interface AddressManagementProps {
  className?: string
  nutritionistId?: string // Para usar durante o cadastro
  onAddressesChange?: (addresses: AddressData[]) => void // Callback para notificar mudanças
}

const BRAZILIAN_STATES = [
  'AC',
  'AL',
  'AP',
  'AM',
  'BA',
  'CE',
  'DF',
  'ES',
  'GO',
  'MA',
  'MT',
  'MS',
  'MG',
  'PA',
  'PB',
  'PR',
  'PE',
  'PI',
  'RJ',
  'RN',
  'RS',
  'RO',
  'RR',
  'SC',
  'SP',
  'SE',
  'TO',
]

export default function AddressManagement({
  className,
  nutritionistId,
  onAddressesChange,
}: AddressManagementProps) {
  const { user } = useUser()
  const [addresses, setAddresses] = useState<AddressData[]>([])
  const [editingIndex, setEditingIndex] = useState<number | null>(null)
  const [loading, setLoading] = useState(false)
  const [formData, setFormData] = useState<AddressData>({
    type: 'in_person',
    status: 'active',
    is_main: false,
    country: 'Brasil',
    state: '',
    city: '',
    neighborhood: '',
    zip_code: '',
    street: '',
    number: '',
    complement: '',
    service_radius_km: 30,
  })

  // Load addresses from Supabase
  const loadAddresses = async () => {
    const currentNutritionistId = nutritionistId || user?.id
    if (!currentNutritionistId) return

    try {
      setLoading(true)
      const addressesData =
        await nutritionistAddressService.getAddressesByNutritionist(
          currentNutritionistId
        )
      setAddresses(addressesData)
    } catch (error) {
      // Error loading addresses - handled silently
      toast({
        title: 'Erro',
        description: 'Erro ao carregar endereços',
        variant: 'destructive',
      })
    } finally {
      setLoading(false)
    }
  }

  // Load addresses on component mount
  useEffect(() => {
    loadAddresses()
  }, [nutritionistId, user?.id])

  // Notify parent component of address changes
  useEffect(() => {
    if (onAddressesChange) {
      onAddressesChange(addresses)
    }
  }, [addresses, onAddressesChange])

  // Auto-set first address as main
  useEffect(() => {
    if (addresses.length === 0) {
      return
    }

    const hasMainAddress = addresses.some(addr => addr.is_main)
    if (!hasMainAddress) {
      const updatedAddresses = addresses.map((addr, index) => ({
        ...addr,
        is_main: index === 0,
      }))
      setAddresses(updatedAddresses)
    }
  }, [addresses])

  const handleAddAddress = () => {
    setFormData({
      type: 'in_person',
      status: 'active',
      is_main: addresses.length === 0, // First address is automatically main
      country: 'Brasil',
      state: '',
      city: '',
      neighborhood: '',
      zip_code: '',
      street: '',
      number: '',
      complement: '',
      service_radius_km: 30,
    })
    setEditingIndex(-1) // -1 indicates new address
  }

  const handleEditAddress = (index: number) => {
    setFormData({ ...addresses[index] })
    setEditingIndex(index)
  }

  const handleSaveAddress = async () => {
    const currentNutritionistId = nutritionistId || user?.id
    if (!currentNutritionistId) {
      toast({
        title: 'Erro',
        description: 'ID do nutricionista não encontrado',
        variant: 'destructive',
      })
      return
    }

    // Validation
    if (!formData.state.trim()) {
      toast({
        title: 'Erro de validação',
        description: 'Estado é obrigatório',
        variant: 'destructive',
      })
      return
    }

    if (!formData.city.trim()) {
      toast({
        title: 'Erro de validação',
        description: 'Cidade é obrigatória',
        variant: 'destructive',
      })
      return
    }

    if (formData.zip_code && !/^\d{5}-?\d{3}$/.test(formData.zip_code)) {
      toast({
        title: 'Erro de validação',
        description: 'CEP deve estar no formato 00000-000',
        variant: 'destructive',
      })
      return
    }

    try {
      setLoading(true)

      if (editingIndex === -1) {
        // Adding new address
        const addressData = {
          ...formData,
          nutritionist_id: currentNutritionistId,
        }
        await nutritionistAddressService.createAddress(addressData)
        toast({
          title: 'Sucesso',
          description: 'Endereço adicionado com sucesso',
        })
      } else {
        // Editing existing address
        const addressId = addresses[editingIndex].id
        if (addressId) {
          await nutritionistAddressService.updateAddress(addressId, formData)
          toast({
            title: 'Sucesso',
            description: 'Endereço atualizado com sucesso',
          })
        }
      }

      // Reload addresses from database
      await loadAddresses()
      setEditingIndex(null)
    } catch (error) {
      // Error saving address - handled silently
      toast({
        title: 'Erro',
        description: 'Erro ao salvar endereço',
        variant: 'destructive',
      })
    } finally {
      setLoading(false)
    }
  }

  const handleDeleteAddress = async (index: number) => {
    const addressId = addresses[index].id
    if (!addressId) return

    try {
      setLoading(true)
      await nutritionistAddressService.deleteAddress(addressId)

      // Reload addresses from database
      await loadAddresses()

      toast({
        title: 'Sucesso',
        description: 'Endereço removido com sucesso',
      })
    } catch (error) {
      // Error deleting address - handled silently
      toast({
        title: 'Erro',
        description: 'Erro ao remover endereço',
        variant: 'destructive',
      })
    } finally {
      setLoading(false)
    }
  }

  const handleSetMainAddress = async (index: number) => {
    const addressId = addresses[index].id
    if (!addressId) return

    try {
      setLoading(true)
      await nutritionistAddressService.setMainAddress(addressId)

      // Reload addresses from database
      await loadAddresses()

      toast({
        title: 'Sucesso',
        description: 'Endereço principal definido com sucesso',
      })
    } catch (error) {
      // Error setting main address
      toast({
        title: 'Erro',
        description: 'Erro ao definir endereço principal',
        variant: 'destructive',
      })
    } finally {
      setLoading(false)
    }
  }

  const handleCancelEdit = () => {
    setEditingIndex(null)
  }

  const handleZipCodeChange = async (zipCode: string) => {
    setFormData(prev => ({ ...prev, zip_code: zipCode }))

    // Auto-fill address from CEP (Brazilian postal code)
    if (/^\d{5}-?\d{3}$/.test(zipCode)) {
      try {
        const cleanZip = zipCode.replace('-', '')
        const response = await fetch(
          `https://viacep.com.br/ws/${cleanZip}/json/`
        )
        const data = await response.json()

        if (!data.erro) {
          setFormData(prev => ({
            ...prev,
            street: data.logradouro || prev.street,
            neighborhood: data.bairro || prev.neighborhood,
            city: data.localidade || prev.city,
            state: data.uf || prev.state,
          }))
        }
      } catch (error) {
        // Error fetching address from CEP
      }
    }
  }

  return (
    <div className={className}>
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <h3 className="text-lg font-semibold">Endereços de Atendimento</h3>
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={handleAddAddress}
            className="flex items-center gap-2"
          >
            <Plus className="h-4 w-4" />
            Adicionar Endereço
          </Button>
        </div>

        {/* Address List */}
        <div className="space-y-3">
          {addresses.map((address, index) => (
            <Card key={index} className="relative">
              <CardContent className="pt-4">
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-2">
                      <Badge
                        variant={
                          address.type === 'in_person' ? 'default' : 'secondary'
                        }
                      >
                        {address.type === 'in_person' ? (
                          <>
                            <MapPin className="h-3 w-3 mr-1" />
                            Presencial
                          </>
                        ) : (
                          <>
                            <Home className="h-3 w-3 mr-1" />
                            Teleconsulta
                          </>
                        )}
                      </Badge>
                      {address.is_main && (
                        <Badge variant="outline">Principal</Badge>
                      )}
                      <Badge
                        variant={
                          address.status === 'active' ? 'default' : 'secondary'
                        }
                      >
                        {address.status === 'active' ? 'Ativo' : 'Inativo'}
                      </Badge>
                    </div>

                    <div className="text-sm text-gray-600">
                      <p className="font-medium">
                        {address.city}/{address.state}
                      </p>
                      {address.street && (
                        <p>
                          {address.street}
                          {address.number ? `, ${address.number}` : ''}
                        </p>
                      )}
                      {address.neighborhood && <p>{address.neighborhood}</p>}
                      {address.zip_code && <p>CEP: {address.zip_code}</p>}
                      {address.service_radius_km &&
                        address.type === 'in_person' && (
                          <p>
                            Raio de atendimento: {address.service_radius_km} km
                          </p>
                        )}
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    {!address.is_main && (
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        onClick={() => handleSetMainAddress(index)}
                        disabled={loading}
                      >
                        Definir como principal
                      </Button>
                    )}
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={() => handleEditAddress(index)}
                      disabled={loading}
                    >
                      Editar
                    </Button>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={() => handleDeleteAddress(index)}
                      className="text-red-600 hover:text-red-700"
                      disabled={loading}
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>

        {/* Address Form */}
        {editingIndex !== null && (
          <Card>
            <CardHeader>
              <CardTitle>
                {editingIndex === -1 ? 'Adicionar Endereço' : 'Editar Endereço'}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="type">Tipo de Atendimento</Label>
                  <Select
                    value={formData.type}
                    onValueChange={(value: 'in_person' | 'teleconsultation') =>
                      setFormData(prev => ({ ...prev, type: value }))
                    }
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="in_person">Presencial</SelectItem>
                      <SelectItem value="teleconsultation">
                        Teleconsulta
                      </SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div>
                  <Label htmlFor="status">Status</Label>
                  <Select
                    value={formData.status}
                    onValueChange={(value: 'active' | 'inactive') =>
                      setFormData(prev => ({ ...prev, status: value }))
                    }
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="active">Ativo</SelectItem>
                      <SelectItem value="inactive">Inativo</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="flex items-center space-x-2">
                <Checkbox
                  id="is_main"
                  checked={formData.is_main}
                  onCheckedChange={checked =>
                    setFormData(prev => ({ ...prev, is_main: !!checked }))
                  }
                />
                <Label htmlFor="is_main">Endereço principal</Label>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div>
                  <Label htmlFor="zip_code">CEP</Label>
                  <Input
                    id="zip_code"
                    value={formData.zip_code || ''}
                    onChange={e => handleZipCodeChange(e.target.value)}
                    placeholder="00000-000"
