                      </Badge>
                    ))}
                  </div>

                  {/* Resumo */}
                  <p className="text-lg text-gray-700 leading-relaxed font-medium">
                    {post.excerpt}
                  </p>

                  {/* Conteúdo */}
                  <div className="prose prose-lg max-w-none">
                    <div className="whitespace-pre-wrap text-gray-800 leading-relaxed">
