}

'use client'

import { useState, useEffect, useRef } from 'react'
import { useParams, useRouter } from 'next/navigation'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Badge } from '@/components/ui/badge'
import {
  ArrowLeft,
  Send,
  Paperclip,
  ImageIcon,
  Phone,
  Video,
  MoreVertical,
} from 'lucide-react'
import { getUserProfile } from '@/lib/auth'
import { useAuth } from '@/contexts/auth-context'
import {
  getChatMessages,
  sendChatMessage,
  type ChatMessage,
  type ChatConversation,
} from '@/lib/chat-forum-service'
import { supabase } from '@/lib/supabase'
import { toast } from '@/components/ui/use-toast'
import { format } from 'date-fns'
import { ptBR } from 'date-fns/locale'
import Link from 'next/link'
import { DashboardSidebar, getMenuItems } from '@/components/dashboard-sidebar'
import { useDashboardStats } from '@/hooks/use-dashboard-stats'

export default function NutritionistChatPage() {
  const { user, loading: authLoading, signOut } = useAuth()
  const [userProfile, setUserProfile] = useState<any>(null)
  const [conversation, setConversation] = useState<ChatConversation | null>(
    null
  )
  const [messages, setMessages] = useState<ChatMessage[]>([])
  const [newMessage, setNewMessage] = useState('')
  const [loading, setLoading] = useState(true)
  const [sending, setSending] = useState(false)
  const scrollAreaRef = useRef<HTMLDivElement>(null)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const router = useRouter()
  const params = useParams()
  const conversationId = params.id as string

  // Dashboard stats
  const { stats, loading: statsLoading } = useDashboardStats({
    userType: 'nutricionista',
    userId: user?.id || '',
    enabled: !!user?.id,
  })
  const menuItems = getMenuItems('nutricionista', stats)

  useEffect(() => {
    if (!authLoading && user) {
      loadChatData()
    }
  }, [conversationId, user, authLoading])

  useEffect(() => {
    scrollToBottom()
  }, [messages])

  useEffect(() => {
    if (conversation) {
      setupRealtimeSubscription()
    }
  }, [conversation])

  const loadChatData = async () => {
    try {
      setLoading(true)
      if (!user) {
        router.push('/login')
        return
      }

      const profile = await getUserProfile(user.id)
      setUserProfile(profile)

      // Get conversation details
      const { data: conversationData, error: conversationError } =
        await supabase
          .from('chat_conversations')
          .select('*')
          .eq('id', conversationId)
          .eq('nutritionist_id', user.id)
          .single()

      if (conversationError) {
        // Error fetching conversation
        toast({
          title: 'Erro',
          description: 'Conversa não encontrada ou acesso negado.',
          variant: 'destructive',
        })
        router.push('/dashboard/nutricionistas')
        return
      }

      // Get patient profile
      const { data: patientProfile } = await supabase
        .from('patient_profiles')
        .select('full_name, profile_image_url')
        .eq('id', conversationData.patient_id)
        .single()

      // Enrich conversation data with patient profile
      const enrichedConversation = {
        ...conversationData,
        patient_profiles: patientProfile,
      }

      setConversation(enrichedConversation)

      // Load messages
      const chatMessages = await getChatMessages(
        conversationId,
        user.id,
        'nutritionist'
      )
      setMessages(chatMessages)
    } catch (error) {
      // Error loading chat data
      toast({
        title: 'Erro',
        description: 'Erro ao carregar dados do chat.',
        variant: 'destructive',
      })
    } finally {
      setLoading(false)
    }
  }

  const setupRealtimeSubscription = () => {
    const channel = supabase
      .channel(`chat_messages:${conversationId}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'chat_messages',
          filter: `conversation_id=eq.${conversationId}`,
        },
        payload => {
          const newMessage = payload.new as ChatMessage
          setMessages(prev => [...prev, newMessage])
        }
      )
      .subscribe()

    return () => {
      supabase.removeChannel(channel)
    }
  }

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  const handleSendMessage = async () => {
    if (!newMessage.trim() || !user || !conversation || sending) return

    try {
      setSending(true)
      const message = await sendChatMessage(
        conversationId,
        user.id,
        'nutritionist',
        newMessage.trim()
      )
      setMessages(prev => [...prev, message])
      setNewMessage('')
    } catch (error) {
      // Error sending message
      toast({
        title: 'Erro',
        description: 'Erro ao enviar mensagem.',
        variant: 'destructive',
      })
    } finally {
      setSending(false)
    }
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSendMessage()
    }
  }

  const handleSignOut = async () => {
    try {
      await signOut()
      router.push('/')
    } catch (error) {
      // Error signing out
    }
  }

  if (authLoading || loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-green-50 to-blue-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-600 mx-auto mb-4"></div>
          <p className="text-gray-600">Carregando chat...</p>
        </div>
      </div>
    )
  }

  if (!conversation) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-green-50 to-blue-50 flex items-center justify-center">
        <div className="text-center">
          <p className="text-gray-600 mb-4">Conversa não encontrada.</p>
          <Link href="/dashboard/nutricionistas">
            <Button>Voltar ao Dashboard</Button>
          </Link>
        </div>
      </div>
    )
  }

  const patient = conversation.patient_profiles

  return (
    <DashboardSidebar
      userType="nutricionista"
      userName={userProfile?.full_name || 'Nutricionista'}
      userAvatar={userProfile?.profile_image_url || '/placeholder.svg'}
      menuItems={menuItems}
      activeItem="chat"
      onItemClick={() => {}}
      onSignOut={handleSignOut}
    >
      <div className="space-y-6">
        {/* Header */}
        <div className="bg-white border-b border-gray-200 rounded-lg shadow-sm">
          <div className="px-6 py-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <Link href="/dashboard/nutricionistas">
                  <Button variant="ghost" size="sm">
                    <ArrowLeft className="h-4 w-4 mr-2" />
                    Voltar
                  </Button>
                </Link>

                <div className="flex items-center gap-3">
                  <Avatar className="h-10 w-10">
                    <AvatarImage src={patient?.profile_image_url || ''} />
                    <AvatarFallback>
                      {patient?.full_name?.charAt(0) || 'P'}
                    </AvatarFallback>
                  </Avatar>
                  <div>
                    <h1 className="font-semibold text-gray-900">
                      {patient?.full_name || 'Paciente'}
                    </h1>
                    <span className="text-sm text-gray-500">Paciente</span>
                  </div>
                </div>
              </div>

              <div className="flex items-center gap-2">
                <Button variant="outline" size="sm">
                  <Phone className="h-4 w-4" />
                </Button>
                <Button variant="outline" size="sm">
                  <Video className="h-4 w-4" />
                </Button>
                <Button variant="ghost" size="sm">
                  <MoreVertical className="h-4 w-4" />
                </Button>
              </div>
            </div>
          </div>
        </div>

        {/* Chat Content */}
        <Card className="h-[calc(100vh-200px)] flex flex-col">
          {/* Messages Area */}
          <CardContent className="flex-1 p-0">
            <ScrollArea className="h-full p-4" ref={scrollAreaRef}>
              <div className="space-y-4">
                {messages.map(message => {
                  const isFromNutritionist =
                    message.sender_type === 'nutritionist'
                  const senderName = isFromNutritionist
                    ? userProfile?.full_name || 'Você'
                    : patient?.full_name || 'Paciente'

                  return (
                    <div
                      key={message.id}
                      className={`flex gap-3 ${isFromNutritionist ? 'justify-end' : 'justify-start'}`}
                    >
                      {!isFromNutritionist && (
                        <Avatar className="h-8 w-8 mt-1">
                          <AvatarImage src={patient?.profile_image_url || ''} />
                          <AvatarFallback className="text-xs">
                            {patient?.full_name?.charAt(0) || 'P'}
                          </AvatarFallback>
                        </Avatar>
                      )}

                      <div
                        className={`max-w-[70%] ${isFromNutritionist ? 'order-first' : ''}`}
                      >
                        <div
                          className={`rounded-lg px-4 py-2 ${
                            isFromNutritionist
                              ? 'bg-green-600 text-white'
                              : 'bg-gray-100 text-gray-900'
                          }`}
                        >
                          <p className="text-sm whitespace-pre-wrap">
                            {message.message_text}
                          </p>
                        </div>
                        <p
                          className={`text-xs text-gray-500 mt-1 ${
                            isFromNutritionist ? 'text-right' : 'text-left'
                          }`}
                        >
                          {format(new Date(message.created_at), 'HH:mm', {
                            locale: ptBR,
                          })}
                        </p>
                      </div>

                      {isFromNutritionist && (
                        <Avatar className="h-8 w-8 mt-1">
                          <AvatarImage
                            src={userProfile?.profile_image_url || ''}
                          />
                          <AvatarFallback className="text-xs">
                            {userProfile?.full_name?.charAt(0) || 'N'}
                          </AvatarFallback>
                        </Avatar>
                      )}
                    </div>
                  )
                })}
                <div ref={messagesEndRef} />
              </div>
            </ScrollArea>
          </CardContent>

          {/* Message Input */}
          <div className="border-t border-gray-200 p-4">
            <div className="flex items-end gap-2">
              <Button variant="outline" size="sm" className="mb-2">
                <Paperclip className="h-4 w-4" />
              </Button>
              <Button variant="outline" size="sm" className="mb-2">
                <ImageIcon className="h-4 w-4" />
              </Button>
              <div className="flex-1">
                <Input
                  value={newMessage}
                  onChange={e => setNewMessage(e.target.value)}
                  onKeyPress={handleKeyPress}
                  placeholder="Digite sua mensagem..."
                  disabled={sending}
                  className="resize-none"
                />
              </div>
              <Button
                onClick={handleSendMessage}
                disabled={!newMessage.trim() || sending}
                className="mb-2"
              >
                <Send className="h-4 w-4" />
              </Button>
            </div>
          </div>
        </Card>
      </div>
    </DashboardSidebar>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useParams, useRouter } from 'next/navigation'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { Badge } from '@/components/ui/badge'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import {
  ThumbsUp,
  MessageCircle,
  Search,
  Heart,
  Send,
  ArrowLeft,
  Shield,
  CheckCircle,
  Eye,
  Edit,
  Trash2,
  MoreVertical,
} from 'lucide-react'
import { EditForumModal } from '@/components/edit-forum-modal'
import { DeleteForumModal } from '@/components/delete-forum-modal'
import { ForumCleanupModal } from '@/components/forum-cleanup-modal'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { getCurrentUser } from '@/lib/auth'
import { supabase } from '@/lib/supabase'

interface Author {
  id: string
  name: string
  avatar?: string
  userType: 'nutricionista' | 'paciente'
  crn?: string
}

interface ForumQuestion {
  id: string
  title: string
  content: string
  category?: string
  author: Author
  timestamp: string
  likes: number
  views: number
  hasLiked: boolean
  replies: number
}

interface ForumReply {
  id: string
  content: string
  author: Author
  timestamp: string
  likes: number
  hasLiked: boolean
  isBestAnswer: boolean
}

export default function NutritionistForumQuestionPage() {
  const params = useParams()
  const router = useRouter()
  const questionId = params.id as string

  // User and auth states
  const [currentUser, setCurrentUser] = useState<any>(null)

  // Filter and search states for replies
  const [searchTerm, setSearchTerm] = useState('')
  const [sortBy, setSortBy] = useState<'recent' | 'likes' | 'best'>('recent')

  // Data states
  const [question, setQuestion] = useState<ForumQuestion | null>(null)
  const [replies, setReplies] = useState<ForumReply[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Reply form states
  const [replyContent, setReplyContent] = useState('')
  const [isSubmittingReply, setIsSubmittingReply] = useState(false)

  // Modal states
  const [editModalOpen, setEditModalOpen] = useState(false)
  const [deleteModalOpen, setDeleteModalOpen] = useState(false)
  const [cleanupModalOpen, setCleanupModalOpen] = useState(false)
  const [editingItem, setEditingItem] = useState<{
    type: 'question' | 'answer'
    id: string
    data: any
  } | null>(null)

  // Load user and question data
  useEffect(() => {
    const loadData = async () => {
      try {
        setLoading(true)

        const user = await getCurrentUser()
        setCurrentUser(user)

        // Fetch question from Supabase
        const { data: questionData, error: questionError } = await supabase
          .from('forum_questions')
          .select('*')
          .eq('id', questionId)
          .single()

        if (questionError) {
          throw questionError
        }

        if (questionData) {
          // Buscar perfil do autor separadamente
          let profile = null
          let isPatient = false

          if (questionData.patient_id) {
            const { data: patientProfile } = await supabase
              .from('patient_profiles')
              .select('id, full_name, profile_image_url, user_id')
              .eq('user_id', questionData.patient_id)
              .single()
            profile = patientProfile
            isPatient = true
          } else if (questionData.nutritionist_id) {
            const { data: nutritionistProfile } = await supabase
              .from('nutritionist_profiles')
              .select('id, full_name, profile_image_url, crn, user_id')
              .eq('user_id', questionData.nutritionist_id)
              .single()
            profile = nutritionistProfile
            isPatient = false
          }

          // Check if current user has liked this question
          let hasLikedQuestion = false
          if (user) {
            const { data: questionLike } = await supabase
              .from('forum_question_likes')
              .select('id')
              .eq('question_id', questionData.id)
              .eq('user_id', user.id)
              .single()
            hasLikedQuestion = !!questionLike
          }

          // Transform data to match interface
          const transformedQuestion: ForumQuestion = {
            id: questionData.id,
            title: questionData.title,
            content: questionData.content,
            category: questionData.category,
            author: {
              id: profile?.user_id || '',
              name: profile?.full_name || 'Usuário',
              avatar: profile?.profile_image_url || '/placeholder.svg',
              userType: isPatient ? 'paciente' : 'nutricionista',
              crn: !isPatient ? profile?.crn : undefined,
            },
            timestamp: questionData.created_at,
            likes: questionData.likes_count || 0,
            views: questionData.views_count || 0,
            hasLiked: hasLikedQuestion,
            replies: questionData.answers_count || 0,
          }

          setQuestion(transformedQuestion)

          // Increment view count
          const newViewCount = (questionData.views_count || 0) + 1
          await supabase
            .from('forum_questions')
            .update({ views_count: newViewCount })
            .eq('id', questionId)

          // Update local state with new view count
          setQuestion(prev =>
            prev
              ? {
                  ...prev,
                  views: newViewCount,
                }
              : null
          )

          // Load replies
          await loadReplies(user)
        }
      } catch (err) {
        // Silent error handling for data loading
        setError('Erro ao carregar a pergunta')
      } finally {
        setLoading(false)
      }
    }

    if (questionId) {
      loadData()
    }
  }, [questionId])

  // Function to load replies
  const loadReplies = async (user: any = currentUser) => {
    try {
      const { data: repliesData, error: repliesError } = await supabase
        .from('forum_answers')
        .select(
          `
          *
        `
        )
        .eq('question_id', questionId)
        .order('created_at', { ascending: false })

      if (!repliesError && repliesData) {
        // Fetch nutritionist profiles and likes separately for each reply
        const repliesWithProfiles = await Promise.all(
          repliesData.map(async reply => {
            const { data: nutritionistProfile } = await supabase
              .from('nutritionist_profiles')
              .select('id, full_name, profile_image_url, crn, user_id')
              .eq('user_id', reply.author_id)
              .single()

            // Check if current user has liked this reply
            let hasLikedReply = false
            if (user) {
              const { data: replyLike } = await supabase
                .from('forum_answer_likes')
                .select('id')
                .eq('answer_id', reply.id)
                .eq('user_id', user.id)
                .single()
              hasLikedReply = !!replyLike
            }

            return {
              ...reply,
              nutritionist_profile: nutritionistProfile,
              hasLiked: hasLikedReply,
            }
          })
        )

        const transformedReplies: ForumReply[] = repliesWithProfiles.map(
          reply => {
            return {
              id: reply.id,
              content: reply.content,
              author: {
                id: reply.nutritionist_profile?.user_id || '',
                name: reply.nutritionist_profile?.full_name || 'Nutricionista',
                avatar:
                  reply.nutritionist_profile?.profile_image_url ||
                  '/placeholder.svg',
                userType: 'nutricionista',
                crn: reply.nutritionist_profile?.crn,
              },
              timestamp: reply.created_at,
              likes: reply.likes_count || 0,
              hasLiked: reply.hasLiked,
              isBestAnswer: reply.is_best_answer || false,
            }
          }
        )

        setReplies(transformedReplies)
      }
    } catch (error) {
      // Silent error handling for replies loading
    }
  }

  // Real-time subscriptions
  useEffect(() => {
    if (!questionId) return

    // Silent realtime subscription setup

    // Subscribe to forum_questions changes (likes and views)
    const questionSubscription = supabase
      .channel(`forum_question_${questionId}`)
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'forum_questions',
          filter: `id=eq.${questionId}`,
        },
        payload => {
          // Silent realtime question update
          setQuestion(prev =>
            prev
              ? {
                  ...prev,
                  likes: payload.new.likes_count || 0,
                  views: payload.new.views_count || 0,
                  replies: payload.new.answers_count || 0,
                }
              : null
          )
        }
      )
      .subscribe(status => {
        // Silent subscription status
      })

    // Subscribe to forum_answers changes (new replies)
    const answersSubscription = supabase
      .channel(`forum_answers_${questionId}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'forum_answers',
          filter: `question_id=eq.${questionId}`,
        },
        payload => {
          // Silent realtime new answer
          loadReplies() // Reload replies when new answer is added
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'forum_answers',
          filter: `question_id=eq.${questionId}`,
        },
        payload => {
          // Silent realtime answer update
          setReplies(prev =>
            prev.map(reply =>
              reply.id === payload.new.id
                ? {
                    ...reply,
                    likes: payload.new.likes_count || 0,
                    isBestAnswer: payload.new.is_best_answer || false,
                  }
                : reply
            )
          )
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'DELETE',
          schema: 'public',
          table: 'forum_answers',
          filter: `question_id=eq.${questionId}`,
        },
        payload => {
          // Silent realtime answer deletion
          setReplies(prev => prev.filter(reply => reply.id !== payload.old.id))
        }
      )
      .subscribe(status => {
        // Realtime answers subscription status
      })

    // Subscribe to forum_question_likes changes
    const questionLikesSubscription = supabase
      .channel(`forum_question_likes_${questionId}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'forum_question_likes',
          filter: `question_id=eq.${questionId}`,
        },
        payload => {
          // Question liked in real-time
          // Check if current user liked it
          if (currentUser && payload.new.user_id === currentUser.id) {
            setQuestion(prev =>
              prev
                ? {
                    ...prev,
                    hasLiked: true,
                  }
                : null
            )
          }
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'DELETE',
          schema: 'public',
          table: 'forum_question_likes',
          filter: `question_id=eq.${questionId}`,
        },
        payload => {
          // Question like removed in real-time
          // Check if current user unliked it
          if (currentUser && payload.old.user_id === currentUser.id) {
            setQuestion(prev =>
              prev
                ? {
                    ...prev,
                    hasLiked: false,
                  }
                : null
            )
          }
        }
      )
      .subscribe(status => {
        // Question likes subscription status
      })

    // Subscribe to forum_answer_likes changes
    const answerLikesSubscription = supabase
      .channel(`forum_answer_likes_${questionId}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'forum_answer_likes',
        },
        payload => {
          // Answer liked in real-time
          // Check if current user liked it
          if (currentUser && payload.new.user_id === currentUser.id) {
            setReplies(prev =>
              prev.map(reply =>
                reply.id === payload.new.answer_id
                  ? { ...reply, hasLiked: true }
                  : reply
              )
            )
          }
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'DELETE',
          schema: 'public',
          table: 'forum_answer_likes',
        },
        payload => {
          // Answer like removed in real-time
          // Check if current user unliked it
          if (currentUser && payload.old.user_id === currentUser.id) {
            setReplies(prev =>
              prev.map(reply =>
                reply.id === payload.old.answer_id
                  ? { ...reply, hasLiked: false }
                  : reply
              )
            )
          }
        }
      )
      .subscribe(status => {
        // Answer likes subscription status
      })

    // Cleanup subscriptions
    return () => {
      // Cleaning up realtime subscriptions
      questionSubscription.unsubscribe()
      answersSubscription.unsubscribe()
      questionLikesSubscription.unsubscribe()
      answerLikesSubscription.unsubscribe()
    }
  }, [questionId, currentUser])

  // Filter and sort replies
  const filteredAndSortedReplies = replies
    .filter(
      reply =>
        reply.content.toLowerCase().includes(searchTerm.toLowerCase()) ||
        reply.author.name.toLowerCase().includes(searchTerm.toLowerCase())
    )
    .sort((a, b) => {
      switch (sortBy) {
        case 'likes':
          return b.likes - a.likes
        case 'best':
          if (a.isBestAnswer && !b.isBestAnswer) return -1
          if (!a.isBestAnswer && b.isBestAnswer) return 1
          return b.likes - a.likes
        case 'recent':
        default:
          return (
            new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
          )
      }
    })

  // Handle like question
  const handleLikeQuestion = async () => {
    if (!currentUser || !question) return

    try {
      // Check if user already liked this question
      const { data: existingLike } = await supabase
        .from('forum_question_likes')
        .select('id')
        .eq('question_id', question.id)
        .eq('user_id', currentUser.id)
        .single()

      if (existingLike) {
        // Unlike: remove the like
        await supabase
          .from('forum_question_likes')
          .delete()
          .eq('id', existingLike.id)

        // Update question likes count
        const newLikesCount = Math.max(0, question.likes - 1)
        await supabase
          .from('forum_questions')
          .update({ likes_count: newLikesCount })
          .eq('id', question.id)
      } else {
        // Like: add the like
        await supabase.from('forum_question_likes').insert({
          question_id: question.id,
          user_id: currentUser.id,
        })

        // Update question likes count
        const newLikesCount = question.likes + 1
        await supabase
          .from('forum_questions')
          .update({ likes_count: newLikesCount })
          .eq('id', question.id)
      }
    } catch (error) {
      // Error liking question
    }
  }

  // Handle like reply
  const handleLikeReply = async (replyId: string) => {
    if (!currentUser) return

    try {
      // Check if user already liked this reply
      const { data: existingLike } = await supabase
        .from('forum_answer_likes')
        .select('id')
        .eq('answer_id', replyId)
        .eq('user_id', currentUser.id)
        .single()

      if (existingLike) {
        // Unlike: remove the like
        await supabase
          .from('forum_answer_likes')
          .delete()
          .eq('id', existingLike.id)

        // Update likes count in reply
        const currentReply = replies.find(r => r.id === replyId)
        if (currentReply) {
          const newLikesCount = Math.max(0, currentReply.likes - 1)
          await supabase
            .from('forum_answers')
            .update({ likes_count: newLikesCount })
            .eq('id', replyId)
        }

        // Update local state immediately for better UX
        setReplies(prev =>
          prev.map(reply =>
            reply.id === replyId ? { ...reply, hasLiked: false } : reply
          )
        )
      } else {
        // Like: add the like
        await supabase.from('forum_answer_likes').insert({
          answer_id: replyId,
          user_id: currentUser.id,
        })

        // Update likes count in reply
        const currentReply = replies.find(r => r.id === replyId)
        if (currentReply) {
          const newLikesCount = currentReply.likes + 1
          await supabase
            .from('forum_answers')
            .update({ likes_count: newLikesCount })
            .eq('id', replyId)
        }

        // Update local state immediately for better UX
        setReplies(prev =>
          prev.map(reply =>
            reply.id === replyId ? { ...reply, hasLiked: true } : reply
          )
        )
      }
    } catch (error) {
      // Silent error handling - error liking reply
    }
  }

  // Handle mark as best answer
  const handleMarkAsBest = async (replyId: string) => {
    if (!currentUser || !question || currentUser.id !== question.author.id)
      return

    try {
      // Remove best answer from all replies
      await supabase
        .from('forum_answers')
        .update({ is_best_answer: false })
        .eq('question_id', question.id)

      // Mark selected reply as best
      const { error } = await supabase
        .from('forum_answers')
        .update({ is_best_answer: true })
        .eq('id', replyId)

      if (!error) {
        setReplies(prev =>
          prev.map(reply => ({
            ...reply,
            isBestAnswer: reply.id === replyId,
          }))
        )
      }
    } catch (error) {
      // Silent error handling - error marking as best answer
    }
  }

  // Handle edit question
  const handleEditQuestion = () => {
    if (!question || !currentUser) return

    setEditingItem({
      type: 'question',
      id: question.id,
      data: {
        title: question.title,
        content: question.content,
        category: question.category,
        tags: [], // Add tags if available in your data structure
      },
    })
    setEditModalOpen(true)
  }

  // Handle edit answer
  const handleEditAnswer = (reply: ForumReply) => {
    if (!currentUser) return

    setEditingItem({
      type: 'answer',
      id: reply.id,
      data: {
        content: reply.content,
      },
    })
    setEditModalOpen(true)
  }

  // Handle delete question
  const handleDeleteQuestion = () => {
    if (!question || !currentUser) return

    setEditingItem({
      type: 'question',
      id: question.id,
      data: { title: question.title },
    })
    setDeleteModalOpen(true)
  }

  // Handle delete answer
  const handleDeleteAnswer = (reply: ForumReply) => {
    if (!currentUser) return

    setEditingItem({
      type: 'answer',
      id: reply.id,
      data: { title: reply.content.substring(0, 100) + '...' },
    })
    setDeleteModalOpen(true)
  }

  // Handle modal success
  const handleModalSuccess = () => {
    // Reload data
    window.location.reload()
  }

  // Handle submit reply
  const handleSubmitReply = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!currentUser || !question || !replyContent.trim()) {
      alert('Por favor, preencha o conteúdo da resposta.')
      return
    }

    if (currentUser.user_type !== 'nutricionista') {
      alert('Apenas nutricionistas podem responder no fórum.')
      return
    }

    try {
      setIsSubmittingReply(true)

      // Get current user's nutritionist profile
      const { data: nutritionistProfile, error: profileError } = await supabase
        .from('nutritionist_profiles')
        .select('id, user_id, full_name, profile_image_url, crn')
        .eq('user_id', currentUser.id)
        .single()

      if (profileError || !nutritionistProfile) {
        throw new Error(
          'Perfil de nutricionista não encontrado. Verifique se seu perfil está completo.'
        )
      }

      const { data: newReply, error } = await supabase
        .from('forum_answers')
        .insert({
          question_id: question.id,
          content: replyContent.trim(),
          author_id: currentUser.id,
          nutritionist_id: nutritionistProfile.id,
        })
        .select('*')
        .single()

      if (error) {
        throw new Error(`Erro ao salvar resposta: ${error.message}`)
      }

      if (newReply) {
        setReplyContent('')
        alert('Resposta enviada com sucesso!')

        // The real-time subscription will handle updating the UI
        // No need to manually update state here
      }
    } catch (error) {
      // Silent error handling - error sending reply
      alert('Erro ao enviar resposta: ' + (error as Error).message)
    } finally {
      setIsSubmittingReply(false)
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50">
        <div className="flex items-center justify-center min-h-screen">
          <div className="text-center">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
            <p className="text-gray-600">Carregando pergunta...</p>
          </div>
        </div>
      </div>
    )
  }

  if (error || !question) {
    return (
      <div className="min-h-screen bg-gray-50">
        <div className="flex items-center justify-center min-h-screen">
          <div className="text-center">
            <p className="text-red-600 mb-4">
              {error || 'Pergunta não encontrada'}
            </p>
            <Button onClick={() => router.back()}>
              <ArrowLeft className="h-4 w-4 mr-2" />
              Voltar
            </Button>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50">
