                    </Button>
                  </div>
                </form>
              </CardContent>
            </Card>
          )}

          {/* Access restriction message for non-nutritionists */}
          {currentUser?.user_type !== 'nutricionista' && (
            <div className="flex items-center gap-2 text-sm text-blue-600 bg-blue-50 px-3 py-2 rounded-md border border-blue-200">
              <Shield className="h-4 w-4" />
              <span className="font-medium">
                Apenas nutricionistas podem responder no fórum
              </span>
            </div>
          )}

          {/* Replies Section */}
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-xl font-semibold">
                Respostas ({replies.length})
              </h2>

              <div className="flex items-center gap-4">
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4" />
                  <Input
                    placeholder="Buscar respostas..."
                    value={searchTerm}
                    onChange={e => setSearchTerm(e.target.value)}
                    className="pl-10 w-64"
                  />
                </div>

                <select
                  value={sortBy}
                  onChange={e => setSortBy(e.target.value as any)}
                  className="px-3 py-2 border border-gray-300 rounded-md text-sm"
                >
                  <option value="recent">Mais recentes</option>
                  <option value="likes">Mais curtidas</option>
                  <option value="best">Melhor resposta</option>
                </select>
              </div>
            </div>

            {filteredAndSortedReplies.length === 0 ? (
              <Card>
                <CardContent className="text-center py-8">
                  <MessageCircle className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                  <p className="text-gray-500">
                    {searchTerm
                      ? 'Nenhuma resposta encontrada'
                      : 'Ainda não há respostas para esta pergunta'}
                  </p>
                </CardContent>
              </Card>
            ) : (
              <div className="space-y-4">
                {filteredAndSortedReplies.map(reply => (
                  <Card
                    key={reply.id}
                    className={
                      reply.isBestAnswer ? 'border-green-200 bg-green-50' : ''
                    }
                  >
                    <CardContent className="pt-6">
                      <div className="space-y-4">
                        <div className="flex items-start justify-between">
                          <div className="flex items-center gap-3">
                            <Avatar>
                              <AvatarImage src={reply.author.avatar} />
                              <AvatarFallback>
                                {reply.author.name
                                  .split(' ')
                                  .map(n => n[0])
                                  .join('')
                                  .toUpperCase()}
                              </AvatarFallback>
                            </Avatar>
                            <div>
                              <div className="flex items-center gap-2">
                                <h4 className="font-semibold">
                                  {reply.author.name}
                                </h4>
                                <Badge
                                  variant={
                                    reply.author.userType === 'nutricionista'
                                      ? 'default'
                                      : 'secondary'
                                  }
                                >
                                  {reply.author.userType === 'nutricionista'
                                    ? 'Nutricionista'
                                    : 'Paciente'}
                                </Badge>
                                {reply.author.userType === 'nutricionista' &&
                                  reply.author.crn && (
                                    <Badge
                                      variant="outline"
                                      className="text-xs"
                                    >
                                      CRN: {reply.author.crn}
                                    </Badge>
                                  )}
                                {reply.isBestAnswer && (
                                  <Badge
                                    variant="default"
                                    className="bg-green-600"
                                  >
                                    <CheckCircle className="h-3 w-3 mr-1" />
                                    Melhor Resposta
                                  </Badge>
                                )}
                              </div>
                              <p className="text-sm text-gray-500">
                                {new Date(reply.timestamp).toLocaleDateString(
                                  'pt-BR'
                                )}
                              </p>
                            </div>
                          </div>

                          <div className="flex items-center gap-2">
                            {currentUser?.id === question.author.id &&
                              !reply.isBestAnswer && (
                                <Button
                                  variant="outline"
                                  size="sm"
                                  onClick={() => handleMarkAsBest(reply.id)}
                                >
                                  <CheckCircle className="h-4 w-4 mr-2" />
                                  Marcar como melhor
                                </Button>
                              )}

                            {currentUser?.id === reply.author.id && (
                              <DropdownMenu>
                                <DropdownMenuTrigger asChild>
                                  <Button variant="ghost" size="sm">
                                    <MoreVertical className="h-4 w-4" />
                                  </Button>
                                </DropdownMenuTrigger>
                                <DropdownMenuContent align="end">
                                  <DropdownMenuItem
                                    onClick={() => handleEditAnswer(reply)}
                                  >
                                    <Edit className="h-4 w-4 mr-2" />
                                    Editar Resposta
                                  </DropdownMenuItem>
                                  <DropdownMenuItem
                                    onClick={() => handleDeleteAnswer(reply)}
                                    className="text-red-600"
                                  >
                                    <Trash2 className="h-4 w-4 mr-2" />
                                    Excluir Resposta
                                  </DropdownMenuItem>
                                </DropdownMenuContent>
                              </DropdownMenu>
                            )}
                          </div>
                        </div>

                        <p className="text-gray-700 whitespace-pre-wrap">
                          {reply.content}
                        </p>

                        <div className="flex items-center gap-4 pt-2">
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleLikeReply(reply.id)}
                            disabled={reply.hasLiked}
                            className={reply.hasLiked ? 'text-blue-600' : ''}
                          >
                            <ThumbsUp className="h-4 w-4 mr-2" />
                            {reply.likes}
                          </Button>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Modals */}
      {editingItem && (
        <EditForumModal
          isOpen={editModalOpen}
          onClose={() => {
            setEditModalOpen(false)
            setEditingItem(null)
          }}
          onSuccess={handleModalSuccess}
          type={editingItem.type}
          itemId={editingItem.id}
          userId={currentUser?.id || ''}
          initialData={editingItem.data}
        />
      )}

      {editingItem && (
        <DeleteForumModal
          isOpen={deleteModalOpen}
          onClose={() => {
            setDeleteModalOpen(false)
            setEditingItem(null)
          }}
          onSuccess={handleModalSuccess}
          type={editingItem.type}
          itemId={editingItem.id}
          userId={currentUser?.id || ''}
          itemTitle={editingItem.data.title}
        />
      )}

      <ForumCleanupModal
        isOpen={cleanupModalOpen}
        onClose={() => setCleanupModalOpen(false)}
        onSuccess={handleModalSuccess}
      />
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import {
  ThumbsUp,
  MessageCircle,
  Search,
  Filter,
  Plus,
  Eye,
  Clock,
  TrendingUp,
  Users,
  Stethoscope,
  User,
  ArrowLeft,
} from 'lucide-react'
import { useAuth } from '@/contexts/auth-context'
import { QuestionModal } from '@/components/question-modal'
import {
  getNutritionistForumQuestions,
  getAllForumQuestions,
  likeForumItem,
  type ForumQuestion,
} from '@/lib/forum-data'

export default function NutritionistForumPage() {
  const { user: currentUser, loading: authLoading } = useAuth()
  const router = useRouter()

  // Filter states
  const [searchTerm, setSearchTerm] = useState('')
  const [selectedCategory, setSelectedCategory] = useState<string>('all')
  const [sortBy, setSortBy] = useState<
    'recent' | 'likes' | 'replies' | 'views'
  >('recent')

  // Data states
  const [patientQuestions, setPatientQuestions] = useState<ForumQuestion[]>([])
  const [nutritionistQuestions, setNutritionistQuestions] = useState<
    ForumQuestion[]
  >([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Modal state
  const [isQuestionModalOpen, setIsQuestionModalOpen] = useState(false)
  const [activeTab, setActiveTab] = useState('patients')

  // Load data
  useEffect(() => {
    const loadData = async () => {
      try {
        setLoading(true)

        const [allQuestions, nutritionistQuestionsData] = await Promise.all([
          getAllForumQuestions(),
          getNutritionistForumQuestions(),
        ])

        setPatientQuestions(
          allQuestions.filter(q => q.author.userType === 'paciente')
        )
        setNutritionistQuestions(nutritionistQuestionsData)
      } catch (err) {
        // Silent error handling for data loading
        setError('Erro ao carregar perguntas do fórum')
      } finally {
        setLoading(false)
      }
    }

    if (!authLoading && currentUser) {
      loadData()
    }
  }, [currentUser, authLoading])

  // Categories
  const categories = [
    { value: 'all', label: 'Todas as categorias' },
    { value: 'nutricao-geral', label: 'Nutrição Geral' },
    { value: 'emagrecimento', label: 'Emagrecimento' },
    { value: 'ganho-massa', label: 'Ganho de Massa' },
    { value: 'nutricao-esportiva', label: 'Nutrição Esportiva' },
    { value: 'alimentacao-infantil', label: 'Alimentação Infantil' },
    { value: 'nutricao-clinica', label: 'Nutrição Clínica' },
    { value: 'vegetarianismo', label: 'Vegetarianismo' },
    { value: 'suplementacao', label: 'Suplementação' },
  ]

  // Get current questions based on active tab
  const currentQuestions =
    activeTab === 'patients' ? patientQuestions : nutritionistQuestions

  // Filter and sort questions
  const filteredAndSortedQuestions = currentQuestions
    .filter(question => {
      const matchesSearch =
        question.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        question.content.toLowerCase().includes(searchTerm.toLowerCase()) ||
        question.author.name.toLowerCase().includes(searchTerm.toLowerCase())

      const matchesCategory =
        selectedCategory === 'all' || question.category === selectedCategory

      return matchesSearch && matchesCategory
    })
    .sort((a, b) => {
      switch (sortBy) {
        case 'likes':
          return b.likes - a.likes
        case 'replies':
          return b.repliesCount - a.repliesCount
        case 'views':
          return b.views - a.views
        case 'recent':
        default:
          return (
            new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
          )
      }
    })

  // Handle like question
  const handleLikeQuestion = async (questionId: string) => {
    if (!currentUser) return

    try {
      await likeForumItem(questionId, currentUser.id, 'question')

      // Update the appropriate questions array
      if (activeTab === 'patients') {
        setPatientQuestions(prev =>
          prev.map(question =>
            question.id === questionId
              ? { ...question, likes: question.likes + 1, hasLiked: true }
              : question
          )
        )
      } else {
        setNutritionistQuestions(prev =>
          prev.map(question =>
            question.id === questionId
              ? { ...question, likes: question.likes + 1, hasLiked: true }
              : question
          )
        )
      }
    } catch (error) {
      // Silent error handling for question liking
    }
  }

  // Handle question click
  const handleQuestionClick = (questionId: string) => {
    router.push(`/dashboard/nutricionistas/forum/${questionId}`)
  }

  // Handle new question success
  const handleQuestionSuccess = (newQuestion: ForumQuestion) => {
    if (newQuestion.author.userType === 'paciente') {
      setPatientQuestions(prev => [newQuestion, ...prev])
    } else {
      setNutritionistQuestions(prev => [newQuestion, ...prev])
    }
    setIsQuestionModalOpen(false)
  }

  if (authLoading || loading) {
    return (
      <div className="min-h-screen bg-gray-50">
        <div className="flex items-center justify-center min-h-screen">
          <div className="text-center">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
            <p className="text-gray-600">Carregando fórum...</p>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="space-y-6">
          {/* Header */}
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <Button
                variant="ghost"
                size="sm"
                onClick={() => router.push('/dashboard/nutricionistas')}
                className="flex items-center gap-2"
              >
                <ArrowLeft className="h-4 w-4" />
                Voltar ao Dashboard
              </Button>
              <div>
                <h1 className="text-2xl font-bold text-gray-900">
                  Fórum de Nutrição
                </h1>
                <p className="text-gray-600">
                  Compartilhe conhecimento e ajude pacientes
                </p>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <Button onClick={() => setIsQuestionModalOpen(true)}>
                <Plus className="h-4 w-4 mr-2" />
                Nova Pergunta
              </Button>
            </div>
          </div>

          {/* Stats Cards */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <Card>
              <CardContent className="p-4">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-blue-100 rounded-lg">
                    <MessageCircle className="h-5 w-5 text-blue-600" />
                  </div>
                  <div>
                    <p className="text-sm text-gray-600">Total de Perguntas</p>
                    <p className="text-xl font-semibold">
                      {patientQuestions.length + nutritionistQuestions.length}
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardContent className="p-4">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-green-100 rounded-lg">
                    <Users className="h-5 w-5 text-green-600" />
                  </div>
                  <div>
                    <p className="text-sm text-gray-600">Suas Respostas</p>
                    <p className="text-xl font-semibold">
                      {[...patientQuestions, ...nutritionistQuestions].reduce(
                        (acc, q) =>
                          acc +
                          (q.author.id === currentUser?.id
                            ? q.repliesCount
                            : 0),
                        0
                      )}
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardContent className="p-4">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-purple-100 rounded-lg">
                    <ThumbsUp className="h-5 w-5 text-purple-600" />
                  </div>
                  <div>
                    <p className="text-sm text-gray-600">Total de Curtidas</p>
                    <p className="text-xl font-semibold">
                      {[...patientQuestions, ...nutritionistQuestions].reduce(
                        (acc, q) => acc + q.likes,
                        0
                      )}
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardContent className="p-4">
                <div className="flex items-center gap-3">
