'use client'

import { useState, useEffect } from 'react'
import { useRouter, useParams } from 'next/navigation'
import { signOut } from '@/lib/auth'
import { DashboardSidebar } from '@/components/dashboard-sidebar'
import { getMenuItems } from '@/components/dashboard-sidebar'
import { useDashboardStats } from '@/hooks/use-dashboard-stats'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { ArrowLeft, MapPin, Star, AlertCircle, Shield } from 'lucide-react'
import { useAuth } from '@/contexts/auth-context'
import { supabase } from '@/lib/supabase'
import { toast } from '@/components/ui/use-toast'

interface NutritionistService {
  id: string
  name: string
  description: string
  price: number
  duration: number
  online_available: boolean
  in_person_available: boolean
}

interface NutritionistProfile {
  id: string
  user_id: string
  full_name: string
  bio: string
  location: string
  profile_image_url: string | null
  crn: string
  rating: number
  total_reviews: number
  specialties: string[] | string
  nutritionist_services: NutritionistService[]
}

export default function ScheduleConsultationPage() {
  const { user, loading: authLoading, signOut } = useAuth()
  const router = useRouter()
  const params = useParams()
  const nutritionistId = params.nutritionistId as string

  const [nutritionist, setNutritionist] = useState<NutritionistProfile | null>(
    null
  )
  const [loading, setLoading] = useState(true)
  const [sidebarOpen, setSidebarOpen] = useState(false)

  const { stats, loading: statsLoading } = useDashboardStats({
    userType: 'paciente',
    userId: user?.id || '',
    enabled: !!user?.id,
  })

  useEffect(() => {
    if (!authLoading && !user) {
      router.push('/login')
      return
    }

    if (
      nutritionistId &&
      nutritionistId !== 'null' &&
      nutritionistId !== 'undefined'
    ) {
      loadNutritionistData()
    } else {
      // Invalid nutritionist ID - handled silently
      toast({
        title: 'Erro',
        description: 'ID do nutricionista inválido',
        variant: 'destructive',
      })
      router.push('/dashboard/paciente')
    }
  }, [nutritionistId, user, authLoading])

  const loadNutritionistData = async () => {
    try {
      setLoading(true)

      const { data, error } = await supabase
        .from('nutritionist_profiles')
        .select(
          `
          id,
          user_id,
          full_name,
          bio,
          location,
          profile_image_url,
          crn,
          rating,
          total_reviews,
          specialties,
          nutritionist_services (*)
        `
        )
        .eq('id', nutritionistId)
        .single()

      if (error) {
        // Error loading nutritionist - handled silently
        throw error
      }

      // Normalizar specialties para sempre ser um array
      let normalizedSpecialties: string[] = []
      if (Array.isArray(data.specialties)) {
        normalizedSpecialties = data.specialties
      } else if (typeof data.specialties === 'string') {
        normalizedSpecialties = data.specialties
          .split(',')
          .map(s => s.trim())
          .filter(Boolean)
      }

      setNutritionist({
        ...data,
        specialties: normalizedSpecialties,
      })
    } catch (error) {
      // Error loading nutritionist data - handled silently
      toast({
        title: 'Erro',
        description: 'Não foi possível carregar os dados do nutricionista',
        variant: 'destructive',
      })
      router.push('/dashboard/paciente')
    } finally {
      setLoading(false)
    }
  }

  const getSpecialtiesText = () => {
    if (!nutritionist?.specialties) return 'Nutrição Geral'

    const specialtiesArray = Array.isArray(nutritionist.specialties)
      ? nutritionist.specialties
      : []

    return specialtiesArray.length > 0
      ? specialtiesArray.join(', ')
      : 'Nutrição Geral'
  }

  if (authLoading || loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-red-50/50 via-white to-white flex items-center justify-center">
        <div className="text-center space-y-4">
          <div className="animate-spin rounded-full h-12 w-12 border-4 border-red-200 border-t-red-500 mx-auto"></div>
          <p className="text-[#1E1D40]/70 font-medium">
            Carregando informações...
          </p>
        </div>
      </div>
    )
  }

  if (!nutritionist) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-red-50/50 via-white to-white flex items-center justify-center">
        <div className="text-center space-y-4">
          <AlertCircle className="h-12 w-12 text-red-500 mx-auto" />
          <h2 className="text-xl font-semibold text-[#1E1D40]">
            Nutricionista não encontrado
          </h2>
          <p className="text-gray-600">
            Não foi possível carregar as informações do profissional.
          </p>
          <Button
            onClick={() => router.push('/dashboard/paciente')}
            variant="outline"
          >
            <ArrowLeft className="h-4 w-4 mr-2" />
            Voltar ao Dashboard
          </Button>
        </div>
      </div>
    )
  }

  const menuItems = user ? getMenuItems('patient', stats) : []

  const handleSignOut = async () => {
    try {
      await signOut()
      router.push('/login')
    } catch (error) {
      // Error signing out - handled silently
      toast({
        title: 'Erro',
        description: 'Erro ao fazer logout',
        variant: 'destructive',
      })
    }
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-red-50/50 via-white to-white flex">
      <DashboardSidebar
        user={user}
        userType="patient"
        menuItems={menuItems}
        onSignOut={handleSignOut}
        isOpen={sidebarOpen}
        onToggle={() => setSidebarOpen(!sidebarOpen)}
      />

      <div className="flex-1 lg:ml-64">
        <div className="container mx-auto px-4 py-8 max-w-6xl">
          {/* Header */}
          <div className="flex items-center gap-4 mb-8">
            <Button
              variant="ghost"
              onClick={() => router.push('/dashboard/paciente')}
              className="hover:bg-red-50"
            >
              <ArrowLeft className="h-4 w-4 mr-2" />
              Voltar
            </Button>
            <div>
              <h1 className="text-3xl font-bold text-[#1E1D40]">
                Perfil do Nutricionista
              </h1>
              <p className="text-gray-600">Informações do profissional</p>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            {/* Informações do Nutricionista */}
            <div className="lg:col-span-3">
              <Card className="border-0 shadow-lg">
                <CardContent className="p-6">
                  <div className="text-center space-y-4">
                    <Avatar className="h-24 w-24 mx-auto ring-4 ring-red-100 shadow-lg">
                      <AvatarImage
                        src={nutritionist?.profile_image_url || undefined}
                      />
                      <AvatarFallback className="bg-gradient-to-br from-red-500 to-red-600 text-white text-2xl font-bold">
                        {nutritionist.full_name?.charAt(0) || 'N'}
                      </AvatarFallback>
                    </Avatar>

                    <div>
                      <h2 className="text-xl font-bold text-[#1E1D40] mb-1">
                        {nutritionist.full_name}
                      </h2>
                      <p className="text-sm text-gray-600 mb-2">
                        CRN: {nutritionist.crn}
                      </p>

                      <div className="flex items-center justify-center gap-2 mb-3">
                        <div className="flex items-center gap-1">
                          <Star className="h-4 w-4 text-yellow-500 fill-current" />
                          <span className="text-sm font-semibold">
                            {nutritionist.rating?.toFixed(1) || '5.0'}
                          </span>
                        </div>
                        <span className="text-sm text-gray-600">
                          ({nutritionist.total_reviews || 0} avaliações)
                        </span>
                      </div>

                      <Badge className="bg-gradient-to-r from-green-500 to-green-600 text-white border-0 mb-3">
                        <Shield className="h-3 w-3 mr-1" />
                        Verificado
                      </Badge>
                    </div>

                    {nutritionist.location && (
                      <div className="flex items-center justify-center gap-2 text-sm text-gray-600">
                        <MapPin className="h-4 w-4" />
                        <span>{nutritionist.location}</span>
                      </div>
                    )}

                    <div className="space-y-2">
                      <p className="text-sm font-medium text-gray-700">
                        Especialidades:
                      </p>
                      <div className="flex flex-wrap gap-1 justify-center">
                        {(typeof getSpecialtiesText() === 'string'
                          ? getSpecialtiesText().split(', ')
                          : [getSpecialtiesText()]
                        ).map((specialty, index) => (
                          <Badge
                            key={index}
                            variant="outline"
                            className="text-xs bg-blue-50 text-blue-700 border-blue-200"
                          >
                            {specialty}
                          </Badge>
                        ))}
                      </div>
                    </div>

                    {nutritionist.bio && (
                      <div className="pt-4 border-t">
                        <p className="text-sm text-gray-600 text-left">
                          {nutritionist.bio}
                        </p>
                      </div>
                    )}

                    <div className="pt-4 border-t">
                      <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
                        <h3 className="text-lg font-semibold text-yellow-800 mb-2">
                          Funcionalidade Temporariamente Indisponível
                        </h3>
                        <p className="text-yellow-700">
                          O agendamento de consultas está temporariamente
                          indisponível. Entre em contato diretamente com o
                          nutricionista para agendar sua consulta.
                        </p>
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useRef } from 'react'
import { useParams, useRouter } from 'next/navigation'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Badge } from '@/components/ui/badge'
import {
  ArrowLeft,
  Send,
  Paperclip,
  ImageIcon,
  Phone,
  Video,
  MoreVertical,
} from 'lucide-react'
import { getUserProfile } from '@/lib/auth'
import { useAuth } from '@/contexts/auth-context'
import {
  getChatMessages,
  sendChatMessage,
  type ChatMessage,
  type ChatConversation,
} from '@/lib/chat-forum-service'
import { supabase } from '@/lib/supabase'
import { toast } from '@/components/ui/use-toast'
import { format } from 'date-fns'
import { ptBR } from 'date-fns/locale'
import Link from 'next/link'
import { DashboardSidebar, getMenuItems } from '@/components/dashboard-sidebar'
import { useDashboardStats } from '@/hooks/use-dashboard-stats'

export default function PatientChatPage() {
  const { user, loading: authLoading, signOut } = useAuth()
  const [userProfile, setUserProfile] = useState<any>(null)
  const [conversation, setConversation] = useState<ChatConversation | null>(
    null
  )
  const [messages, setMessages] = useState<ChatMessage[]>([])
  const [newMessage, setNewMessage] = useState('')
  const [loading, setLoading] = useState(true)
  const [sending, setSending] = useState(false)
  const scrollAreaRef = useRef<HTMLDivElement>(null)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const router = useRouter()
  const params = useParams()
  const conversationId = params.id as string

  // Dashboard stats
  const { stats, loading: statsLoading } = useDashboardStats({
    userType: 'paciente',
    userId: user?.id || '',
    enabled: !!user?.id,
  })
  const menuItems = getMenuItems('paciente', stats)

  const handleSignOut = async () => {
    try {
      await signOut()
      router.push('/')
    } catch (error) {
      // Silent error handling for sign out
    }
  }

  useEffect(() => {
    if (!authLoading && user) {
      loadChatData()
    }
  }, [conversationId, user, authLoading])

  useEffect(() => {
    scrollToBottom()
  }, [messages])

  useEffect(() => {
    if (conversation) {
      setupRealtimeSubscription()
    }
  }, [conversation])

  const loadChatData = async () => {
    try {
      setLoading(true)
      if (!user) {
        router.push('/login')
        return
      }

      const profile = await getUserProfile(user.id)
      setUserProfile(profile)

      // Get conversation details
      const { data: conversationData, error: conversationError } =
        await supabase
          .from('chat_conversations')
          .select('*')
          .eq('id', conversationId)
          .eq('patient_id', user.id)
          .single()

      if (conversationError) {
        // Silent error handling for conversation fetching
        toast({
          title: 'Erro',
          description: 'Conversa não encontrada ou acesso negado.',
          variant: 'destructive',
        })
        router.push('/dashboard/paciente')
        return
      }

      // Buscar perfil do nutricionista separadamente
      const { data: nutritionistProfile } = await supabase
        .from('nutritionist_profiles')
        .select('full_name, profile_image_url, crn, is_verified')
        .eq('user_id', conversationData.nutritionist_id)
        .single()

      // Enriquecer dados da conversa com perfil do nutricionista
      const enrichedConversation = {
        ...conversationData,
        nutritionist_profiles: nutritionistProfile,
      }

      setConversation(enrichedConversation)

      // Load messages
      const chatMessages = await getChatMessages(
        conversationId,
        user.id,
        'patient'
      )
      setMessages(chatMessages)
    } catch (error) {
      // Silent error handling for chat data loading
      toast({
        title: 'Erro',
        description: 'Erro ao carregar dados do chat.',
        variant: 'destructive',
      })
    } finally {
      setLoading(false)
    }
  }

  const setupRealtimeSubscription = () => {
    const channel = supabase
      .channel(`chat_messages:${conversationId}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'chat_messages',
          filter: `conversation_id=eq.${conversationId}`,
        },
        payload => {
          const newMessage = payload.new as ChatMessage
          setMessages(prev => [...prev, newMessage])
        }
      )
      .subscribe()

    return () => {
      supabase.removeChannel(channel)
    }
  }

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  const handleSendMessage = async () => {
    if (!newMessage.trim() || !user || !conversation || sending) return

    try {
      setSending(true)
      const message = await sendChatMessage(
        conversationId,
        user.id,
        'patient',
        newMessage.trim()
      )
      setMessages(prev => [...prev, message])
      setNewMessage('')
    } catch (error) {
      // Silent error handling for message sending
      toast({
        title: 'Erro',
        description: 'Erro ao enviar mensagem.',
        variant: 'destructive',
      })
    } finally {
      setSending(false)
    }
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSendMessage()
    }
  }

  if (authLoading || loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-green-50 to-blue-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-600 mx-auto mb-4"></div>
          <p className="text-gray-600">Carregando chat...</p>
        </div>
      </div>
    )
  }

  if (!conversation) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-green-50 to-blue-50 flex items-center justify-center">
        <div className="text-center">
          <p className="text-gray-600 mb-4">Conversa não encontrada.</p>
          <Link href="/dashboard/paciente">
            <Button>Voltar ao Dashboard</Button>
          </Link>
        </div>
      </div>
    )
  }

  const nutritionist = conversation.nutritionist_profiles

