  full_name: string
  bio: string
  location: string
  profile_image_url: string | null
  crn: string
  rating: number
  total_reviews: number
  nutritionist_services: NutritionistService[]
  nutritionist_specialties: {
    specialties: Specialty
  }[]
  is_verified: boolean // Adicionado para o selo de verificação
