    </Dialog>
  )
}

'use client'

import React from 'react'
import * as ReactAll from 'react'
import {
  format,
  addMonths,
  subMonths,
  startOfMonth,
  endOfMonth,
  eachDayOfInterval,
  isSameMonth,
  isSameDay,
  isToday,
  isBefore,
  startOfDay,
} from 'date-fns'
import { ptBR } from 'date-fns/locale'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import { ChevronLeft, ChevronRight } from 'lucide-react'

interface CustomCalendarProps {
  selectedDate: Date | undefined
  onSelectDate: (date: Date | undefined) => void
  initialMonth?: Date
  disablePastDates?: boolean
  disableWeekends?: boolean
  showAvailabilityIndicator?: boolean
}

export function CustomCalendar({
  selectedDate,
  onSelectDate,
  initialMonth = new Date(),
  disablePastDates = true,
  disableWeekends = false,
  showAvailabilityIndicator = true,
}: CustomCalendarProps) {
  const [currentMonth, setCurrentMonth] = React.useState(initialMonth)
  const [calendarDays, setCalendarDays] = React.useState<Date[]>([])

  React.useEffect(() => {
    generateCalendarDays()
  }, [currentMonth])

  const generateCalendarDays = React.useCallback(() => {
    const start = startOfMonth(currentMonth)
    const end = endOfMonth(currentMonth)
    const days = eachDayOfInterval({ start, end })

    // Adicionar dias do mês anterior para completar a primeira semana
    const startWeekDay = start.getDay() // 0 for Sunday, 1 for Monday, etc.
    const previousMonthDays = []
    for (let i = startWeekDay - 1; i >= 0; i--) {
      const day = new Date(start)
      day.setDate(day.getDate() - (i + 1))
      previousMonthDays.push(day)
    }

    // Adicionar dias do próximo mês para completar a última semana
    const endWeekDay = end.getDay()
    const nextMonthDays = []
    for (let i = 1; i <= 6 - endWeekDay; i++) {
      const day = new Date(end)
      day.setDate(day.getDate() + i)
      nextMonthDays.push(day)
    }

    setCalendarDays([...previousMonthDays, ...days, ...nextMonthDays])
  }, [currentMonth])

  const isDateDisabled = (date: Date) => {
    const today = startOfDay(new Date())
    if (disablePastDates && isBefore(date, today) && !isSameDay(date, today))
      return true
    if (disableWeekends && (date.getDay() === 0 || date.getDay() === 6))
      return true // Domingo (0) e Sábado (6)
    return false
  }

  const isDateAvailable = (date: Date) => {
    // Esta é uma simulação. Em uma aplicação real, você buscaria a disponibilidade do backend.
    // Por exemplo, se o dia da semana for de segunda a sexta.
    const dayOfWeek = date.getDay()
    return dayOfWeek >= 1 && dayOfWeek <= 5 // Segunda a Sexta
  }

  const getDateStatus = (date: Date) => {
    if (isDateDisabled(date)) return 'disabled'
    if (!isSameMonth(date, currentMonth)) return 'outside'
    if (selectedDate && isSameDay(date, selectedDate)) return 'selected'
    if (isToday(date)) return 'today'
    if (showAvailabilityIndicator && isDateAvailable(date)) return 'available'
    return 'unavailable'
  }

  const previousMonth = () => {
    setCurrentMonth(subMonths(currentMonth, 1))
  }

  const nextMonth = () => {
    setCurrentMonth(addMonths(currentMonth, 1))
  }

  const handleDayClick = (date: Date) => {
    if (getDateStatus(date) === 'disabled' || getDateStatus(date) === 'outside')
      return
    onSelectDate(date)
  }

  return (
    <div className="space-y-4">
      {/* Header do Calendário */}
      <div className="bg-gradient-to-r from-green-500 to-green-600 rounded-lg p-4 text-white">
        <div className="flex items-center justify-between">
          <Button
            variant="ghost"
            size="sm"
            onClick={previousMonth}
            className="text-white hover:bg-white/20 p-2"
          >
            <ChevronLeft className="h-4 w-4" />
          </Button>

          <h3 className="text-lg font-semibold">
            {format(currentMonth, 'MMMM yyyy', { locale: ptBR })}
          </h3>

          <Button
            variant="ghost"
            size="sm"
            onClick={nextMonth}
            className="text-white hover:bg-white/20 p-2"
          >
            <ChevronRight className="h-4 w-4" />
          </Button>
        </div>
      </div>

      {/* Dias da Semana */}
      <div className="grid grid-cols-7 gap-1 text-center text-sm font-medium text-gray-600">
        {['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'].map(day => (
          <div key={day} className="p-2">
            {day}
          </div>
        ))}
      </div>

      {/* Dias do Calendário */}
      <div className="grid grid-cols-7 gap-1">
        {calendarDays.map((date, index) => {
          const status = getDateStatus(date)
          return (
            <button
              key={index}
              onClick={() => handleDayClick(date)}
              disabled={status === 'disabled' || status === 'outside'}
              className={cn(
                'p-2 text-sm rounded-lg transition-all duration-200 hover:scale-105 relative',
                {
                  // Data selecionada
                  'bg-gradient-to-r from-green-500 to-green-600 text-white font-bold shadow-lg':
                    status === 'selected',

                  // Data de hoje
                  'bg-blue-100 text-blue-700 font-semibold ring-2 ring-blue-300':
                    status === 'today' && status !== 'selected',

                  // Datas disponíveis
                  'hover:bg-green-50 hover:text-green-700 text-gray-700':
                    status === 'available',

                  // Datas indisponíveis
                  'text-gray-400 cursor-not-allowed': status === 'unavailable',

                  // Datas desabilitadas
                  'text-gray-300 cursor-not-allowed': status === 'disabled',

                  // Datas fora do mês
                  'text-gray-300 cursor-not-allowed': status === 'outside',
                }
              )}
            >
              {format(date, 'd')}

              {/* Indicador de disponibilidade */}
              {showAvailabilityIndicator && status === 'available' && (
                <div className="absolute bottom-0 left-1/2 transform -translate-x-1/2 w-1 h-1 bg-green-400 rounded-full"></div>
              )}

              {/* Indicador de hoje */}
              {status === 'today' && status !== 'selected' && (
                <div className="absolute top-0 right-0 w-2 h-2 bg-blue-500 rounded-full"></div>
              )}
            </button>
          )
        })}
      </div>

      {/* Legenda */}
      {showAvailabilityIndicator && (
        <div className="flex flex-wrap gap-4 text-xs text-gray-600 pt-2 border-t">
          <div className="flex items-center gap-1">
            <div className="w-3 h-3 bg-gradient-to-r from-green-500 to-green-600 rounded"></div>
            <span>Selecionado</span>
          </div>
          <div className="flex items-center gap-1">
            <div className="w-3 h-3 bg-blue-100 rounded"></div>
            <span>Hoje</span>
          </div>
          <div className="flex items-center gap-1">
            <div className="w-3 h-3 bg-green-50 border border-green-200 rounded"></div>
            <span>Disponível</span>
          </div>
          <div className="flex items-center gap-1">
            <div className="w-3 h-3 bg-gray-200 rounded"></div>
            <span>Indisponível</span>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Calendar } from '@/components/ui/calendar'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import { CalendarIcon, Loader2 } from 'lucide-react'
import { format } from 'date-fns'
import { ptBR } from 'date-fns/locale'
import { cn } from '@/lib/utils'
import { createSupabaseClient } from '@/lib/supabase'
import { useUser } from '@/hooks/use-user'

interface JobOption {
  id: string
  title: string
}

interface CandidateOption {
  id: string
  name: string
  email: string
}

interface NewProcessModalProps {
  isOpen: boolean
  onClose: () => void
  onSuccess: () => void
}

export function NewProcessModal({
  isOpen,
  onClose,
  onSuccess,
}: NewProcessModalProps) {
  const { user } = useUser()
  const [loading, setLoading] = useState(false)
  const [jobs, setJobs] = useState<JobOption[]>([])
  const [candidates, setCandidates] = useState<CandidateOption[]>([])
  const [loadingJobs, setLoadingJobs] = useState(false)
  const [loadingCandidates, setLoadingCandidates] = useState(false)

  const [formData, setFormData] = useState({
    jobId: '',
    candidateId: '',
    currentStage: 'triagem',
    nextStep: '',
    deadline: undefined as Date | undefined,
    notes: '',
  })

  const loadJobs = useCallback(async () => {
    if (!user?.companyProfile?.id) return

    setLoadingJobs(true)
    try {
      const supabase = createSupabaseClient()
      const { data, error } = await supabase
        .from('job_postings')
        .select('id, title')
        .eq('company_id', user.companyProfile.id)
        .eq('status', 'ativa')
        .order('created_at', { ascending: false })

      if (error) throw error
      setJobs(data || [])
    } catch (error) {
      // Silent error handling: Error loading jobs
    } finally {
      setLoadingJobs(false)
    }
  }, [user?.companyProfile?.id])

  // Carregar vagas da empresa
  useEffect(() => {
    if (isOpen && user?.companyProfile?.id) {
      loadJobs()
    }
  }, [isOpen, user?.companyProfile?.id, loadJobs])

  const loadCandidates = useCallback(async (jobId: string) => {
    setLoadingCandidates(true)
    try {
      const supabase = createSupabaseClient()
      // Usar função RPC para evitar problemas de RLS
      const { data, error } = await supabase.rpc('get_job_candidates', {
        job_id_param: jobId,
      })

      if (error) throw error

      const candidateOptions =
        data?.map(candidate => ({
          id: candidate.candidate_id,
          applicationId: candidate.application_id,
          name: candidate.candidate_name,
          email: candidate.candidate_email,
        })) || []

      setCandidates(candidateOptions)
    } catch (error) {
      // Silent error handling: Error loading candidates
      setCandidates([])
    } finally {
      setLoadingCandidates(false)
    }
  }, [])

  // Carregar candidatos quando uma vaga for selecionada
  useEffect(() => {
    if (formData.jobId) {
      loadCandidates(formData.jobId)
    } else {
      setCandidates([])
      setFormData(prev => ({ ...prev, candidateId: '' }))
    }
  }, [formData.jobId, loadCandidates])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!formData.jobId || !formData.candidateId || !formData.nextStep) {
      alert('Por favor, preencha todos os campos obrigatórios.')
      return
    }

    setLoading(true)
    try {
      const supabase = createSupabaseClient()
      // Primeiro, buscar o application_id
      const { data: application, error: appError } = await supabase
        .from('job_applications')
        .select('id')
        .eq('job_id', formData.jobId)
        .eq('candidate_id', formData.candidateId)
        .single()

      if (appError || !application) {
        throw new Error('Candidatura não encontrada')
      }

      // Criar o processo seletivo
      const { error: processError } = await supabase
        .from('selection_processes')
        .insert({
          application_id: application.id,
          current_stage: formData.currentStage,
          next_step: formData.nextStep,
          deadline: formData.deadline?.toISOString().split('T')[0] || null,
          notes: formData.notes || null,
          status: 'em_andamento',
        })

      if (processError) throw processError

      // Atualizar status da candidatura para "em_analise"
      const { error: updateError } = await supabase
        .from('job_applications')
        .update({ status: 'em_analise' })
        .eq('id', application.id)

      if (updateError) throw updateError

      onSuccess()
      onClose()
      resetForm()
    } catch (error) {
      // Silent error handling: Error creating process
      alert('Erro ao criar processo seletivo. Tente novamente.')
    } finally {
      setLoading(false)
    }
  }

  const resetForm = () => {
    setFormData({
      jobId: '',
      candidateId: '',
      currentStage: 'triagem',
      nextStep: '',
      deadline: undefined,
      notes: '',
    })
    setJobs([])
    setCandidates([])
  }

  const handleClose = () => {
    onClose()
    resetForm()
  }

  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-[600px] max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="text-xl font-bold text-[#1E1D40]">
            Novo Processo Seletivo
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Seleção de Vaga */}
          <div className="space-y-2">
            <Label htmlFor="job">Vaga *</Label>
            <Select
              value={formData.jobId}
              onValueChange={value =>
                setFormData(prev => ({ ...prev, jobId: value }))
              }
              disabled={loadingJobs}
            >
              <SelectTrigger>
                <SelectValue
                  placeholder={
                    loadingJobs ? 'Carregando vagas...' : 'Selecione uma vaga'
                  }
                />
              </SelectTrigger>
              <SelectContent>
                {jobs.map(job => (
                  <SelectItem key={job.id} value={job.id}>
                    {job.title}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Seleção de Candidato */}
          <div className="space-y-2">
            <Label htmlFor="candidate">Candidato *</Label>
            <Select
              value={formData.candidateId}
              onValueChange={value =>
                setFormData(prev => ({ ...prev, candidateId: value }))
              }
              disabled={!formData.jobId || loadingCandidates}
            >
              <SelectTrigger>
                <SelectValue
                  placeholder={
                    !formData.jobId
                      ? 'Selecione uma vaga primeiro'
                      : loadingCandidates
                        ? 'Carregando candidatos...'
                        : 'Selecione um candidato'
                  }
                />
              </SelectTrigger>
              <SelectContent>
                {candidates.map(candidate => (
                  <SelectItem key={candidate.id} value={candidate.id}>
                    <div className="flex flex-col">
                      <span className="font-medium">{candidate.name}</span>
                      <span className="text-sm text-gray-500">
                        {candidate.email}
                      </span>
                    </div>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Estágio Atual */}
          <div className="space-y-2">
            <Label htmlFor="stage">Estágio Atual *</Label>
            <Select
              value={formData.currentStage}
              onValueChange={value =>
                setFormData(prev => ({ ...prev, currentStage: value }))
              }
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="triagem">Triagem</SelectItem>
                <SelectItem value="entrevista">Entrevista</SelectItem>
                <SelectItem value="teste_tecnico">Teste Técnico</SelectItem>
                <SelectItem value="aprovado">Aprovado</SelectItem>
                <SelectItem value="rejeitado">Rejeitado</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {/* Próximo Passo */}
          <div className="space-y-2">
            <Label htmlFor="nextStep">Próximo Passo *</Label>
            <Input
              id="nextStep"
              value={formData.nextStep}
              onChange={e =>
                setFormData(prev => ({ ...prev, nextStep: e.target.value }))
              }
              placeholder="Ex: Agendar entrevista, Enviar teste técnico..."
              required
            />
          </div>

          {/* Prazo */}
          <div className="space-y-2">
            <Label>Prazo</Label>
            <Popover>
              <PopoverTrigger asChild>
                <Button
                  variant="outline"
                  className={cn(
                    'w-full justify-start text-left font-normal',
                    !formData.deadline && 'text-muted-foreground'
                  )}
                >
                  <CalendarIcon className="mr-2 h-4 w-4" />
                  {formData.deadline ? (
                    format(formData.deadline, 'PPP', { locale: ptBR })
                  ) : (
                    <span>Selecione uma data</span>
                  )}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0">
                <Calendar
                  mode="single"
                  selected={formData.deadline}
                  onSelect={date =>
                    setFormData(prev => ({ ...prev, deadline: date }))
                  }
                  disabled={date => date < new Date()}
                  initialFocus
                />
              </PopoverContent>
            </Popover>
          </div>

          {/* Observações */}
          <div className="space-y-2">
            <Label htmlFor="notes">Observações</Label>
            <Textarea
              id="notes"
              value={formData.notes}
              onChange={e =>
                setFormData(prev => ({ ...prev, notes: e.target.value }))
              }
              placeholder="Observações sobre o processo..."
              rows={3}
            />
          </div>

          <DialogFooter className="gap-2">
            <Button
              type="button"
              variant="outline"
              onClick={handleClose}
              disabled={loading}
            >
              Cancelar
            </Button>
            <Button
              type="submit"
              disabled={loading}
              className="bg-blue-600 hover:bg-blue-700"
            >
              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Criar Processo
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

