  // State para o modal de bloqueio/edição
  const [isBlockModalOpen, setIsBlockModalOpen] = useState(false)
  const [blockReason, setBlockReason] = useState('')
  const [blockStartTime, setBlockStartTime] = useState<string>('')
  const [blockEndTime, setBlockEndTime] = useState<string>('')
  const [editingConsultation, setEditingConsultation] =
    useState<Consultation | null>(null)
  const [isRescheduleModalOpen, setIsRescheduleModalOpen] = useState(false)
  const [newRescheduleDate, setNewRescheduleDate] = useState<Date | undefined>(
    undefined
  )
  const [newRescheduleTime, setNewRescheduleTime] = useState<string>('')
  const [isCancelModalOpen, setIsCancelModalOpen] = useState(false)
  const [cancelReason, setCancelReason] = useState('')

  // Filtros
  const [filterStatus, setFilterStatus] = useState<string>('all')
  const [filterType, setFilterType] = useState<string>('all')
  const [filterPatientName, setFilterPatientName] = useState<string>('')

  const fetchConsultations = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      let startDate: Date | undefined
      let endDate: Date | undefined

      if (viewMode === 'month') {
        startDate = new Date(
          selectedDate.getFullYear(),
          selectedDate.getMonth(),
          1
        )
        endDate = new Date(
          selectedDate.getFullYear(),
          selectedDate.getMonth() + 1,
          0
        )
      } else if (viewMode === 'week') {
        startDate = startOfWeek(selectedDate, { locale: ptBR })
        endDate = endOfWeek(selectedDate, { locale: ptBR })
      } else {
        // Day view
        startDate = selectedDate
        endDate = selectedDate
      }

      const fetchedConsultations = await getConsultationsForNutritionist(
        userId,
        startDate,
        endDate,
        filterStatus,
        filterType,
        filterPatientName
      )
      setConsultations(fetchedConsultations)
    } catch (err: any) {
      setError(err.message || 'Erro ao carregar consultas.')
      toast({
        title: 'Erro',
        description: 'Não foi possível carregar as consultas.',
        variant: 'destructive',
      })
    } finally {
      setLoading(false)
    }
  }, [
    userId,
    selectedDate,
    viewMode,
    filterStatus,
    filterType,
    filterPatientName,
  ])

  useEffect(() => {
    if (userId) {
      fetchConsultations()
    }
  }, [userId, fetchConsultations])

  const handleDateChange = (date: Date | undefined) => {
    if (date) {
      setSelectedDate(date)
    }
  }

  const handlePrevNext = (direction: 'prev' | 'next') => {
    const newDate = new Date(selectedDate)
    if (viewMode === 'month') {
      newDate.setMonth(newDate.getMonth() + (direction === 'next' ? 1 : -1))
    } else if (viewMode === 'week') {
      newDate.setDate(newDate.getDate() + (direction === 'next' ? 7 : -7))
    } else {
      newDate.setDate(newDate.getDate() + (direction === 'next' ? 1 : -1))
    }
    setSelectedDate(newDate)
  }

  const getVisibleDays = useMemo(() => {
    if (viewMode === 'month') {
      const startOfMonth = new Date(
        selectedDate.getFullYear(),
        selectedDate.getMonth(),
        1
      )
      const endOfMonth = new Date(
        selectedDate.getFullYear(),
        selectedDate.getMonth() + 1,
        0
      )
      const start = startOfWeek(startOfMonth, { locale: ptBR })
      const end = endOfWeek(endOfMonth, { locale: ptBR })
      const days = []
      let day = start
      while (day <= end) {
        days.push(day)
        day = addDays(day, 1)
      }
      return days
    } else if (viewMode === 'week') {
      const start = startOfWeek(selectedDate, { locale: ptBR })
      const days = []
      for (let i = 0; i < 7; i++) {
        days.push(addDays(start, i))
      }
      return days
    } else {
      return [selectedDate]
    }
  }, [selectedDate, viewMode])

  const getConsultationsForDay = (day: Date) => {
    return consultations
      .filter(c => isSameDay(parseISO(c.start_time), day))
      .sort((a, b) => {
        const timeA = new Date(a.start_time).getTime()
        const timeB = new Date(b.start_time).getTime()
        return timeA - timeB
      })
  }

  const handleBlockTime = async () => {
    if (!blockStartTime || !blockEndTime || !blockReason) {
      toast({
        title: 'Campos obrigatórios',
        description: 'Preencha todos os campos para bloquear o horário.',
        variant: 'destructive',
      })
      return
    }

    setLoading(true)
    try {
      const startDateTime = new Date(selectedDate)
      const startTimeParts = blockStartTime?.split(':') || ['0', '0']
      startDateTime.setHours(
        Number.parseInt(startTimeParts[0]),
        Number.parseInt(startTimeParts[1]),
        0,
        0
      )
      const endDateTime = new Date(selectedDate)
      const endTimeParts = blockEndTime?.split(':') || ['0', '0']
      endDateTime.setHours(
        Number.parseInt(endTimeParts[0]),
        Number.parseInt(endTimeParts[1]),
        0,
        0
      )

      if (startDateTime >= endDateTime) {
        toast({
          title: 'Erro de horário',
          description: 'A hora de início deve ser anterior à hora de término.',
          variant: 'destructive',
        })
        setLoading(false)
        return
      }

      await blockTimeSlot(userId, startDateTime, endDateTime, blockReason)
      toast({
        title: 'Horário bloqueado!',
        description: 'O horário foi bloqueado com sucesso.',
      })
      setIsBlockModalOpen(false)
      setBlockReason('')
      setBlockStartTime('')
      setBlockEndTime('')
      fetchConsultations()
    } catch (err: any) {
      toast({
        title: 'Erro ao bloquear horário',
        description: err.message || 'Ocorreu um erro ao bloquear o horário.',
        variant: 'destructive',
      })
    } finally {
      setLoading(false)
    }
  }

  const handleUnblockTime = async (consultationId: string) => {
    if (!confirm('Tem certeza que deseja desbloquear este horário?')) return
    setLoading(true)
    try {
      await unblockTimeSlot(consultationId)
      toast({
        title: 'Horário desbloqueado!',
        description: 'O horário foi desbloqueado com sucesso.',
      })
      fetchConsultations()
    } catch (err: any) {
      toast({
        title: 'Erro ao desbloquear horário',
        description: err.message || 'Ocorreu um erro ao desbloquear o horário.',
        variant: 'destructive',
      })
    } finally {
      setLoading(false)
    }
  }

  const openRescheduleModal = (consultation: Consultation) => {
    setEditingConsultation(consultation)
    setNewRescheduleDate(parseISO(consultation.start_time))
    setNewRescheduleTime(format(parseISO(consultation.start_time), 'HH:mm'))
    setIsRescheduleModalOpen(true)
  }

  const handleReschedule = async () => {
    if (!editingConsultation || !newRescheduleDate || !newRescheduleTime) {
      toast({
        title: 'Campos obrigatórios',
        description: 'Preencha todos os campos para reagendar.',
        variant: 'destructive',
      })
      return
    }

    setLoading(true)
    try {
      const newStart = new Date(newRescheduleDate)
      const rescheduleTimeParts = newRescheduleTime?.split(':') || ['0', '0']
      newStart.setHours(
        Number.parseInt(rescheduleTimeParts[0]),
        Number.parseInt(rescheduleTimeParts[1]),
        0,
        0
      )
      const newEnd = new Date(
        newStart.getTime() +
          (parseISO(editingConsultation.end_time).getTime() -
            parseISO(editingConsultation.start_time).getTime())
      )

      await rescheduleConsultation(editingConsultation.id, newStart, newEnd)
      toast({
        title: 'Consulta reagendada!',
        description: 'A consulta foi reagendada com sucesso.',
      })
      setIsRescheduleModalOpen(false)
      setEditingConsultation(null)
      fetchConsultations()
    } catch (err: any) {
      toast({
        title: 'Erro ao reagendar',
        description: err.message || 'Ocorreu um erro ao reagendar a consulta.',
        variant: 'destructive',
      })
    } finally {
      setLoading(false)
    }
  }

  const openCancelModal = (consultation: Consultation) => {
    setEditingConsultation(consultation)
    setIsCancelModalOpen(true)
  }

  const handleCancel = async () => {
    if (!editingConsultation) return

    setLoading(true)
    try {
      await cancelConsultation(editingConsultation.id, cancelReason)
      toast({
        title: 'Consulta cancelada!',
        description: 'A consulta foi cancelada com sucesso.',
      })
      setIsCancelModalOpen(false)
      setEditingConsultation(null)
      setCancelReason('')
      fetchConsultations()
    } catch (err: any) {
      toast({
        title: 'Erro ao cancelar',
        description: err.message || 'Ocorreu um erro ao cancelar a consulta.',
        variant: 'destructive',
      })
    } finally {
      setLoading(false)
    }
  }

  const getStatusBadge = (status: Consultation['status']) => {
    switch (status) {
      case 'scheduled':
        return (
          <Badge
            variant="default"
            className="bg-blue-100 text-blue-700 border-blue-200"
          >
            Agendada
          </Badge>
        )
      case 'completed':
        return (
          <Badge
            variant="default"
            className="bg-green-100 text-green-700 border-green-200"
          >
            Concluída
          </Badge>
        )
      case 'cancelled':
        return (
          <Badge
            variant="destructive"
            className="bg-red-100 text-red-700 border-red-200"
          >
            Cancelada
          </Badge>
        )
      case 'pending':
        return (
          <Badge
            variant="secondary"
            className="bg-yellow-100 text-yellow-700 border-yellow-200"
          >
            Pendente
          </Badge>
        )
      case 'rescheduled':
        return (
          <Badge
            variant="outline"
            className="bg-purple-100 text-purple-700 border-purple-200"
          >
            Reagendada
          </Badge>
        )
      default:
        return <Badge variant="secondary">Desconhecido</Badge>
    }
  }

  const getConsultationTypeBadge = (
    type: Consultation['consultation_type']
  ) => {
    switch (type) {
      case 'online':
        return (
          <Badge
            variant="outline"
            className="bg-purple-50 text-purple-700 border-purple-200"
          >
            Online
          </Badge>
        )
      case 'presential':
        return (
          <Badge
            variant="outline"
            className="bg-orange-50 text-orange-700 border-orange-200"
          >
            Presencial
          </Badge>
        )
      default:
        return null
    }
  }

  return (
    <div className="space-y-8">
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl lg:text-4xl font-bold text-[#1E1D40] mb-2">
            Minha Agenda Profissional
          </h1>
          <p className="text-gray-600">
            Gerencie seus horários, consultas e bloqueios.
          </p>
        </div>
        <div className="flex gap-2">
          <Button
            variant="outline"
            className="hover-lift bg-white/80 backdrop-blur-sm border-gray-200"
            onClick={() => setIsBlockModalOpen(true)}
          >
            <Plus className="h-4 w-4 mr-2" />
            Bloquear Horário
          </Button>
        </div>
      </div>

      {error && (
        <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-lg flex items-center gap-2 text-red-700">
          <AlertCircle className="h-4 w-4" />
          <span className="text-sm">{error}</span>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        {/* Calendário e Filtros */}
        <Card className="lg:col-span-1 border-0 shadow-lg backdrop-blur-sm">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <CalendarIcon className="h-5 w-5 text-blue-600" />
              Navegar no Calendário
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <CustomCalendar
              selectedDate={selectedDate}
              onSelectDate={handleDateChange}
              initialMonth={selectedDate} // Garante que o calendário inicie no mês da data selecionada
              disableWeekends={false} // Permite fins de semana para nutricionistas
              showAvailabilityIndicator={false} // Não mostra indicador de disponibilidade genérico aqui
            />
            <div className="flex justify-between gap-2">
              <Button
                variant="outline"
                onClick={() => handlePrevNext('prev')}
                className="flex-1"
              >
                <ChevronLeft className="h-4 w-4" /> Anterior
              </Button>
              <Button
                variant="outline"
                onClick={() => handlePrevNext('next')}
                className="flex-1"
              >
                Próximo <ChevronRight className="h-4 w-4" />
              </Button>
            </div>
            <div className="flex flex-col gap-2">
              <Label htmlFor="view-mode">Visualização</Label>
              <Select
                value={viewMode}
                onValueChange={value => setViewMode(value as ViewMode)}
              >
                <SelectTrigger id="view-mode">
                  <SelectValue placeholder="Selecionar visualização" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="day">Dia</SelectItem>
                  <SelectItem value="week">Semana</SelectItem>
                  <SelectItem value="month">Mês</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="flex flex-col gap-2">
              <Label htmlFor="filter-status">Status</Label>
              <Select value={filterStatus} onValueChange={setFilterStatus}>
                <SelectTrigger id="filter-status">
                  <SelectValue placeholder="Filtrar por status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todos</SelectItem>
                  <SelectItem value="scheduled">Agendada</SelectItem>
                  <SelectItem value="completed">Concluída</SelectItem>
                  <SelectItem value="cancelled">Cancelada</SelectItem>
                  <SelectItem value="pending">Pendente</SelectItem>
                  <SelectItem value="rescheduled">Reagendada</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="flex flex-col gap-2">
              <Label htmlFor="filter-type">Tipo de Atendimento</Label>
              <Select value={filterType} onValueChange={setFilterType}>
                <SelectTrigger id="filter-type">
                  <SelectValue placeholder="Filtrar por tipo" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todos</SelectItem>
                  <SelectItem value="online">Online</SelectItem>
                  <SelectItem value="presential">Presencial</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="flex flex-col gap-2">
              <Label htmlFor="filter-patient">Nome do Paciente</Label>
              <Input
                id="filter-patient"
                placeholder="Buscar paciente..."
                value={filterPatientName}
                onChange={e => setFilterPatientName(e.target.value)}
              />
            </div>
          </CardContent>
        </Card>

        {/* Visualização de Consultas */}
        <Card className="lg:col-span-3 border-0 shadow-lg backdrop-blur-sm">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <ClipboardList className="h-5 w-5 text-green-600" />
              {viewMode === 'day'
                ? `Consultas em ${format(selectedDate, "dd 'de' MMMM, yyyy", { locale: ptBR })}`
                : viewMode === 'week'
                  ? `Consultas da Semana (${format(startOfWeek(selectedDate, { locale: ptBR }), 'dd/MM')} - ${format(endOfWeek(selectedDate, { locale: ptBR }), 'dd/MM')})`
                  : `Consultas de ${format(selectedDate, "MMMM 'de' yyyy", { locale: ptBR })}`}
            </CardTitle>
          </CardHeader>
          <CardContent>
            {loading ? (
              <div className="flex items-center justify-center p-8">
                <Loader2 className="h-8 w-8 animate-spin text-blue-500" />
                <span className="ml-3 text-gray-600">Carregando agenda...</span>
              </div>
            ) : consultations.length === 0 ? (
              <div className="text-center p-8 text-gray-500">
                Nenhuma consulta ou horário bloqueado encontrado para o período
                e filtros selecionados.
              </div>
            ) : (
              <div className="space-y-6">
                {viewMode === 'day' ? (
                  <DayView
                    consultations={getConsultationsForDay(selectedDate)}
                    onReschedule={openRescheduleModal}
                    onCancel={openCancelModal}
                    onUnblock={handleUnblockTime}
                  />
                ) : (
                  getVisibleDays.map(day => {
                    const dailyConsultations = getConsultationsForDay(day)
                    if (dailyConsultations.length === 0) return null
                    return (
                      <div
                        key={day.toISOString()}
                        className="border-b pb-4 mb-4 last:border-b-0 last:pb-0 last:mb-0"
                      >
                        <h3 className="text-lg font-semibold text-[#1E1D40] mb-3 flex items-center gap-2">
                          <CalendarIcon className="h-4 w-4 text-gray-500" />
                          {format(day, "EEEE, dd 'de' MMMM", { locale: ptBR })}
                        </h3>
                        <DayView
                          consultations={dailyConsultations}
                          onReschedule={openRescheduleModal}
                          onCancel={openCancelModal}
                          onUnblock={handleUnblockTime}
                        />
                      </div>
                    )
                  })
                )}
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Modal de Bloqueio de Horário */}
      <Dialog open={isBlockModalOpen} onOpenChange={setIsBlockModalOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Bloquear Horário</DialogTitle>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="block-start-time" className="text-right">
                Início
              </Label>
              <Input
                id="block-start-time"
                type="time"
                value={blockStartTime}
                onChange={e => setBlockStartTime(e.target.value)}
                className="col-span-3"
              />
            </div>
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="block-end-time" className="text-right">
                Fim
              </Label>
              <Input
                id="block-end-time"
                type="time"
                value={blockEndTime}
                onChange={e => setBlockEndTime(e.target.value)}
                className="col-span-3"
              />
            </div>
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="block-reason" className="text-right">
                Motivo
              </Label>
              <Textarea
                id="block-reason"
                value={blockReason}
                onChange={e => setBlockReason(e.target.value)}
                placeholder="Ex: Consulta pessoal, Férias, Evento"
                className="col-span-3"
              />
            </div>
          </div>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setIsBlockModalOpen(false)}
            >
              Cancelar
            </Button>
            <Button onClick={handleBlockTime} disabled={loading}>
              {loading ? (
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              ) : (
                'Bloquear'
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Modal de Reagendamento */}
      <Dialog
        open={isRescheduleModalOpen}
        onOpenChange={setIsRescheduleModalOpen}
      >
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Reagendar Consulta</DialogTitle>
          </DialogHeader>
          {editingConsultation && (
            <div className="grid gap-4 py-4">
              <p className="text-sm text-gray-700">
                Reagendando consulta com{' '}
                <span className="font-semibold">
                  {editingConsultation.patient_name}
                </span>{' '}
                em{' '}
                <span className="font-semibold">
                  {format(
                    parseISO(editingConsultation.start_time),
                    'dd/MM/yyyy HH:mm',
                    { locale: ptBR }
                  )}
                </span>
              </p>
              <div className="grid grid-cols-4 items-center gap-4">
                <Label htmlFor="new-date" className="text-right">
                  Nova Data
                </Label>
                <Popover>
                  <PopoverTrigger asChild>
                    <Button
                      variant={'outline'}
                      className={cn(
                        'col-span-3 justify-start text-left font-normal',
                        !newRescheduleDate && 'text-muted-foreground'
                      )}
                    >
                      <CalendarIcon className="mr-2 h-4 w-4" />
                      {newRescheduleDate ? (
                        format(newRescheduleDate, 'PPP', { locale: ptBR })
                      ) : (
                        <span>Escolha uma data</span>
                      )}
                    </Button>
                  </PopoverTrigger>
                  <PopoverContent className="w-auto p-0">
                    <CustomCalendar
                      selectedDate={newRescheduleDate}
                      onSelectDate={setNewRescheduleDate}
                      disableWeekends={false} // Permite fins de semana para reagendamento
                      showAvailabilityIndicator={false} // Não mostra indicador de disponibilidade genérico aqui
                    />
                  </PopoverContent>
                </Popover>
              </div>
              <div className="grid grid-cols-4 items-center gap-4">
                <Label htmlFor="new-time" className="text-right">
                  Novo Horário
                </Label>
                <Input
                  id="new-time"
                  type="time"
                  value={newRescheduleTime}
                  onChange={e => setNewRescheduleTime(e.target.value)}
                  className="col-span-3"
                />
              </div>
            </div>
          )}
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setIsRescheduleModalOpen(false)}
            >
              Cancelar
            </Button>
            <Button onClick={handleReschedule} disabled={loading}>
              {loading ? (
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              ) : (
                'Reagendar'
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Modal de Cancelamento */}
      <Dialog open={isCancelModalOpen} onOpenChange={setIsCancelModalOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Cancelar Consulta</DialogTitle>
          </DialogHeader>
          {editingConsultation && (
            <div className="grid gap-4 py-4">
              <p className="text-sm text-gray-700">
                Você está prestes a cancelar a consulta com{' '}
                <span className="font-semibold">
                  {editingConsultation.patient_name}
                </span>{' '}
                em{' '}
                <span className="font-semibold">
                  {format(
                    parseISO(editingConsultation.start_time),
                    'dd/MM/yyyy HH:mm',
                    { locale: ptBR }
                  )}
                </span>
                .
              </p>
              <div className="grid grid-cols-4 items-center gap-4">
                <Label htmlFor="cancel-reason" className="text-right">
                  Motivo
                </Label>
                <Textarea
                  id="cancel-reason"
                  value={cancelReason}
                  onChange={e => setCancelReason(e.target.value)}
                  placeholder="Opcional: Informe o motivo do cancelamento."
                  className="col-span-3"
                />
              </div>
            </div>
          )}
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setIsCancelModalOpen(false)}
            >
              Não Cancelar
            </Button>
            <Button
              variant="destructive"
              onClick={handleCancel}
              disabled={loading}
            >
              {loading ? (
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              ) : (
                'Confirmar Cancelamento'
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

interface DayViewProps {
  consultations: Consultation[]
  onReschedule: (consultation: Consultation) => void
  onCancel: (consultation: Consultation) => void
  onUnblock: (consultationId: string) => void
}

function DayView({
  consultations,
  onReschedule,
  onCancel,
  onUnblock,
}: DayViewProps) {
  const getStatusBadge = (status: Consultation['status']) => {
    switch (status) {
      case 'scheduled':
        return (
          <Badge
            variant="default"
            className="bg-blue-100 text-blue-700 border-blue-200"
          >
            Agendada
          </Badge>
        )
      case 'completed':
        return (
          <Badge
            variant="default"
            className="bg-green-100 text-green-700 border-green-200"
          >
            Concluída
          </Badge>
        )
      case 'cancelled':
        return (
          <Badge
            variant="destructive"
            className="bg-red-100 text-red-700 border-red-200"
          >
            Cancelada
          </Badge>
        )
      case 'pending':
        return (
          <Badge
            variant="secondary"
            className="bg-yellow-100 text-yellow-700 border-yellow-200"
          >
            Pendente
          </Badge>
        )
      case 'rescheduled':
        return (
          <Badge
            variant="outline"
            className="bg-purple-100 text-purple-700 border-purple-200"
          >
            Reagendada
          </Badge>
        )
      default:
        return <Badge variant="secondary">Desconhecido</Badge>
    }
  }

  const getConsultationTypeBadge = (
    type: Consultation['consultation_type']
  ) => {
    switch (type) {
      case 'online':
        return (
          <Badge
            variant="outline"
            className="bg-purple-50 text-purple-700 border-purple-200"
          >
            Online
          </Badge>
        )
      case 'presential':
        return (
          <Badge
            variant="outline"
            className="bg-orange-50 text-orange-700 border-orange-200"
          >
            Presencial
          </Badge>
        )
      default:
        return null
    }
  }

  return (
    <div className="space-y-4">
      {consultations.length === 0 ? (
        <p className="text-gray-500 text-sm">Nenhum evento neste dia.</p>
      ) : (
        consultations.map(consultation => (
          <Card
            key={consultation.id}
            className={cn(
              'border-0 shadow-md transition-all duration-200 hover:shadow-lg',
              consultation.is_blocked_slot
                ? 'bg-gray-50 border-gray-200'
                : 'bg-white border-blue-100'
            )}
          >
            <CardContent className="p-4 flex items-center justify-between gap-4">
              <div className="flex items-center gap-4 flex-1 min-w-0">
                <div className="flex flex-col items-center justify-center text-center">
                  <Clock className="h-5 w-5 text-gray-600" />
                  <span className="font-semibold text-lg text-[#1E1D40]">
                    {format(parseISO(consultation.start_time), 'HH:mm')}
                  </span>
                  <span className="text-xs text-gray-500">
                    {format(parseISO(consultation.end_time), 'HH:mm')}
                  </span>
                </div>
                <div className="flex-1 min-w-0">
                  {consultation.is_blocked_slot ? (
                    <>
                      <h3 className="font-bold text-lg text-gray-800">
                        Horário Bloqueado
                      </h3>
                      <p className="text-sm text-gray-600 truncate">
                        Motivo: {consultation.block_reason || 'Não informado'}
                      </p>
                    </>
                  ) : (
                    <>
                      <div className="flex items-center gap-2">
                        <Avatar className="h-8 w-8">
                          <AvatarImage
                            src={
                              consultation.patient_avatar || '/placeholder.svg'
                            }
                          />
                          <AvatarFallback>
                            {consultation.patient_name
                              ?.charAt(0)
                              .toUpperCase() || 'P'}
                          </AvatarFallback>
                        </Avatar>
                        <h3 className="font-bold text-lg text-[#1E1D40] truncate">
                          Consulta com {consultation.patient_name}
                        </h3>
                      </div>
                      <div className="flex flex-wrap gap-2 mt-1">
                        {getStatusBadge(consultation.status)}
                        {getConsultationTypeBadge(
                          consultation.consultation_type
                        )}
                      </div>
                      {consultation.consultation_type === 'presential' &&
                        consultation.nutritionist_profiles?.address && (
                          <p className="text-sm text-gray-600 flex items-center gap-1 mt-1">
                            <MapPin className="h-3 w-3" />
                            {consultation.nutritionist_profiles.address}
                          </p>
                        )}
                    </>
                  )}
                </div>
              </div>
              <div className="flex gap-2">
                {consultation.is_blocked_slot ? (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => onUnblock(consultation.id)}
                  >
                    <XCircle className="h-4 w-4 mr-1" /> Desbloquear
                  </Button>
                ) : (
                  <>
                    {consultation.consultation_type === 'online' && (
                      <Button variant="outline" size="sm">
                        <Video className="h-4 w-4 mr-1" /> Entrar
                      </Button>
                    )}
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => onReschedule(consultation)}
                    >
                      <Edit className="h-4 w-4 mr-1" /> Reagendar
                    </Button>
                    <Button
                      variant="destructive"
                      size="sm"
                      onClick={() => onCancel(consultation)}
                    >
                      <Trash2 className="h-4 w-4 mr-1" /> Cancelar
                    </Button>
                  </>
                )}
              </div>
            </CardContent>
          </Card>
        ))
      )}
    </div>
  )
}

'use client'

import type React from 'react'

import { useState, useEffect } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { Label } from '@/components/ui/label'
import { Badge } from '@/components/ui/badge'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Checkbox } from '@/components/ui/checkbox'
import { RichTextEditor } from '@/components/ui/rich-text-editor'
import {
  Plus,
  Edit,
  Trash,
  Calendar,
  Clock,
  User,
  Search,
  List,
  Grid,
  Award,
} from 'lucide-react'
import Image from 'next/image'
import Link from 'next/link'
import { toast } from '@/components/ui/use-toast'
import { AdvancedImageUpload } from '@/components/ui/advanced-image-upload'
import {
  type BlogPost,
  getBlogPostsByAuthor,
  addBlogPost,
  updateBlogPost,
  deleteBlogPost,
  blogCategories,
} from '@/lib/blog-data' // Importar funções e categorias do blog-data
import { getCurrentUser } from '@/lib/auth' // Para obter o ID do usuário logado
import { createSupabaseClient } from '@/lib/supabase' // Para cliente autenticado

export function BlogTab() {
  const [myPosts, setMyPosts] = useState<BlogPost[]>([])
  const [isEditing, setIsEditing] = useState(false)
  const [currentPost, setCurrentPost] = useState<Partial<BlogPost> | null>(null)
  const [loading, setLoading] = useState(true)
  const [authorId, setAuthorId] = useState<string | null>(null)

  const [searchTerm, setSearchTerm] = useState('')
  const [selectedCategory, setSelectedCategory] = useState('Todos')
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid')

  useEffect(() => {
    const fetchUserAndPosts = async () => {
      setLoading(true)
      const user = await getCurrentUser()
      if (user) {
        setAuthorId(user.id)
        const posts = await getBlogPostsByAuthor(user.id)
        setMyPosts(posts)
      }
      setLoading(false)
    }
    fetchUserAndPosts()
  }, [])

  const filteredPosts = myPosts.filter(post => {
    const matchesCategory =
      selectedCategory === 'Todos' || post.category === selectedCategory
    const matchesSearch =
      post.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      post.excerpt.toLowerCase().includes(searchTerm.toLowerCase()) ||
      post.tags.some(tag =>
        tag.toLowerCase().includes(searchTerm.toLowerCase())
      )
    return matchesCategory && matchesSearch
  })

  const handleNewPost = () => {
    setIsEditing(true)
    setCurrentPost({
      title: '',
      excerpt: '',
      content: '',
      category: '',
      image: '/placeholder.svg?height=400&width=800',
      tags: [],
      featured: false,
      centerImage: false,
    })
  }

  const handleEditPost = (post: BlogPost) => {
    setIsEditing(true)
    setCurrentPost({ ...post })
  }

  const handleDeletePost = async (id: string) => {
    if (
      window.confirm(
        'Tem certeza que deseja excluir este artigo? Esta ação não pode ser desfeita.'
      )
    ) {
      try {
        // Criar cliente Supabase autenticado
        const supabase = createSupabaseClient()
        const success = await deleteBlogPost(id, supabase)
        if (success) {
          // Refresh posts
          const posts = await getBlogPostsByAuthor(authorId || '')
          setMyPosts(posts)
          toast({
            title: 'Artigo excluído',
            description: 'O artigo foi removido com sucesso.',
          })
        } else {
          toast({
            title: 'Erro ao excluir',
            description:
              'Não foi possível excluir o artigo. Verifique se você tem permissão para esta ação.',
            variant: 'destructive',
          })
        }
      } catch (error) {
        // Silent error handling: Error deleting post
        toast({
          title: 'Erro inesperado',
          description:
            'Ocorreu um erro inesperado ao tentar excluir o artigo. Tente novamente.',
          variant: 'destructive',
        })
      }
    }
  }

  // Função para formatar o nome do autor
  const formatAuthorName = (fullName: string) => {
    const names = fullName.trim().split(' ')
    if (names.length === 1) {
      return names[0]
    }
    if (names.length === 2) {
      return `${names[0]} ${names[1][0]}.`
    }
    // Para nomes com mais de 2 partes, pega o primeiro nome e a primeira letra do segundo
    return `${names[0]} ${names[1][0]}.`
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!currentPost || !authorId) return

    if (!currentPost.title || !currentPost.content || !currentPost.category) {
      toast({
        title: 'Campos obrigatórios',
        description: 'Preencha título, conteúdo e categoria.',
        variant: 'destructive',
      })
      return
    }

    const authorName = 'Nutricionista Logado' // Placeholder, replace with actual user name
    const authorBio = 'Nutricionista da Busca Nutri.' // Placeholder, replace with actual user bio
    const authorImage = '/placeholder.svg?height=100&width=100' // Placeholder

    if (currentPost.id) {
      // Update existing post
      const updated = await updateBlogPost({
        ...currentPost,
        author: authorName,
        authorId: authorId,
        authorBio: authorBio,
        authorImage: authorImage,
        readTime: currentPost.readTime || '5 min', // Default if not set
        views: currentPost.views || 0, // Default if not set
        date: currentPost.date || new Date().toISOString().split('T')[0], // Default if not set
      } as BlogPost)
      if (updated) {
        toast({
          title: 'Artigo atualizado',
          description: 'O artigo foi salvo com sucesso.',
        })
      } else {
        toast({
          title: 'Erro',
          description: 'Não foi possível atualizar o artigo.',
          variant: 'destructive',
        })
      }
    } else {
      // Add new post
      const newPost = await addBlogPost({
        ...currentPost,
        author: authorName,
        authorId: authorId,
        authorBio: authorBio,
        authorImage: authorImage,
        readTime: '5 min', // Default read time for new posts
        views: 0, // New posts start with 0 views
      } as Omit<BlogPost, 'id' | 'date' | 'views' | 'badges'>)
      if (newPost) {
        toast({
          title: 'Artigo publicado',
          description: 'Seu novo artigo foi publicado com sucesso!',
        })
      } else {
        toast({
          title: 'Erro',
          description: 'Não foi possível publicar o artigo.',
          variant: 'destructive',
        })
      }
    }
    setIsEditing(false)
    setCurrentPost(null)
    const posts = await getBlogPostsByAuthor(authorId) // Refresh posts
    setMyPosts(posts)
  }

  if (loading) {
    return (
      <div className="min-h-[400px] flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-4 border-blue-200 border-t-blue-500 mx-auto"></div>
        <p className="text-[#1E1D40]/70 font-medium ml-4">
          Carregando seus artigos...
        </p>
      </div>
    )
  }

  return (
    <div className="space-y-8">
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl lg:text-4xl font-bold text-[#1E1D40] mb-2">
            Meu Blog
          </h1>
          <p className="text-gray-600">
            Crie, edite e gerencie seus artigos para a comunidade Busca Nutri.
          </p>
        </div>
        <Button
          onClick={handleNewPost}
          className="bg-gradient-to-r from-blue-500 to-blue-600 hover:from-blue-600 hover:to-blue-700 shadow-lg hover:shadow-xl transition-all duration-300"
        >
          <Plus className="h-4 w-4 mr-2" />
          Novo Artigo
        </Button>
      </div>

      {isEditing && currentPost ? (
        <Card className="border-0 shadow-lg backdrop-blur-sm">
          <CardHeader>
            <CardTitle>
              {currentPost.id ? 'Editar Artigo' : 'Criar Novo Artigo'}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-6">
              <div>
                <Label htmlFor="title">Título</Label>
                <Input
                  id="title"
                  value={currentPost.title || ''}
                  onChange={e =>
                    setCurrentPost({ ...currentPost, title: e.target.value })
                  }
                  required
                />
              </div>
              <div>
                <Label htmlFor="excerpt">Resumo</Label>
                <Textarea
                  id="excerpt"
                  value={currentPost.excerpt || ''}
                  onChange={e =>
                    setCurrentPost({ ...currentPost, excerpt: e.target.value })
                  }
                  rows={3}
                  required
                />
              </div>
              <div>
                <Label htmlFor="content">Conteúdo</Label>
                <RichTextEditor
                  content={currentPost.content || ''}
                  onChange={content =>
                    setCurrentPost({ ...currentPost, content })
                  }
                  placeholder="Escreva o conteúdo do seu artigo aqui... Cole links do YouTube, Instagram ou TikTok para incorporar vídeos automaticamente."
                  imageUrl={currentPost.image}
                  onImageUrlChange={url =>
                    setCurrentPost({ ...currentPost, image: url })
                  }
                  centerImage={currentPost.centerImage || false}
                  onCenterImageChange={centered =>
                    setCurrentPost({ ...currentPost, centerImage: centered })
                  }
                />
              </div>
              <div>
                <Label htmlFor="category">Categoria</Label>
                <Select
                  value={currentPost.category || ''}
                  onValueChange={value =>
                    setCurrentPost({ ...currentPost, category: value })
                  }
                  required
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Selecione uma categoria" />
                  </SelectTrigger>
                  <SelectContent>
                    {blogCategories.map(category => (
                      <SelectItem key={category} value={category}>
                        {category}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label htmlFor="image">Imagem de Capa</Label>
                <AdvancedImageUpload
                  onImageUploaded={url =>
                    setCurrentPost({ ...currentPost, image: url })
                  }
                  onImageRemoved={() =>
                    setCurrentPost({ ...currentPost, image: '' })
                  }
                  currentImageUrl={currentPost.image}
                  userId={authorId || ''}
                  disabled={!authorId}
                />
              </div>
              <div>
                <Label htmlFor="tags">Tags (separadas por vírgula)</Label>
                <Input
                  id="tags"
                  value={currentPost.tags?.join(', ') || ''}
                  onChange={e =>
                    setCurrentPost({
                      ...currentPost,
                      tags: e.target.value.split(',').map(t => t.trim()),
                    })
                  }
                  placeholder="saúde, bem-estar, nutrição"
                />
              </div>
              <div className="flex items-center space-x-2">
                <Checkbox
                  id="featured"
                  checked={currentPost.featured || false}
                  onCheckedChange={checked =>
                    setCurrentPost({ ...currentPost, featured: !!checked })
                  }
                />
                <Label htmlFor="featured">Artigo em Destaque</Label>
              </div>
              <div className="flex gap-4">
                <Button type="submit" className="bg-blue-600 hover:bg-blue-700">
                  {currentPost.id ? 'Salvar Alterações' : 'Publicar Artigo'}
                </Button>
                <Button variant="outline" onClick={() => setIsEditing(false)}>
                  Cancelar
                </Button>
              </div>
            </form>
          </CardContent>
        </Card>
      ) : (
        <>
          {/* Filters and View Mode */}
          <div className="bg-white rounded-2xl shadow-lg p-6 mb-8 border">
            <div className="flex flex-col lg:flex-row gap-6 items-center justify-between">
              {/* Categories */}
              <div className="flex flex-wrap gap-2">
                <Button
                  variant={selectedCategory === 'Todos' ? 'default' : 'outline'}
                  size="sm"
                  onClick={() => setSelectedCategory('Todos')}
                  className={`transition-all duration-200 ${
                    selectedCategory === 'Todos'
                      ? 'bg-[#4AB0D9] hover:bg-[#4AB0D9]/90 shadow-md'
                      : 'hover:bg-gray-50 border-gray-200'
                  }`}
                >
                  Todos
                  <Badge variant="secondary" className="ml-2 text-xs">
                    {myPosts.length}
                  </Badge>
                </Button>
                {blogCategories.map(category => (
                  <Button
                    key={category}
                    variant={
                      category === selectedCategory ? 'default' : 'outline'
                    }
                    size="sm"
                    onClick={() => setSelectedCategory(category)}
                    className={`transition-all duration-200 ${
                      category === selectedCategory
                        ? 'bg-[#4AB0D9] hover:bg-[#4AB0D9]/90 shadow-md'
                        : 'hover:bg-gray-50 border-gray-200'
                    }`}
                  >
                    {category}
                    <Badge variant="secondary" className="ml-2 text-xs">
                      {
                        myPosts.filter(post => post.category === category)
                          .length
                      }
                    </Badge>
                  </Button>
                ))}
              </div>

              {/* Controls */}
              <div className="flex items-center gap-4">
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4" />
                  <Input
                    type="text"
                    placeholder="Buscar artigos..."
                    value={searchTerm}
                    onChange={e => setSearchTerm(e.target.value)}
                    className="pl-9 pr-4 py-2 rounded-full border-2 border-gray-200 focus:border-[#4AB0D9] focus:ring-0"
                  />
                </div>
                <div className="flex border-2 border-gray-200 rounded-lg overflow-hidden shadow-sm">
                  <Button
                    variant={viewMode === 'grid' ? 'default' : 'ghost'}
                    size="sm"
                    onClick={() => setViewMode('grid')}
                    className={`rounded-none px-4 py-2 transition-all duration-200 ${
                      viewMode === 'grid'
                        ? 'bg-[#4AB0D9] text-white shadow-md'
                        : 'hover:bg-gray-50 text-gray-600'
                    }`}
                  >
                    <Grid className="h-4 w-4" />
                  </Button>
                  <Button
                    variant={viewMode === 'list' ? 'default' : 'ghost'}
                    size="sm"
                    onClick={() => setViewMode('list')}
                    className={`rounded-none px-4 py-2 transition-all duration-200 ${
                      viewMode === 'list'
                        ? 'bg-[#4AB0D9] text-white shadow-md'
                        : 'hover:bg-gray-50 text-gray-600'
                    }`}
                  >
                    <List className="h-4 w-4" />
                  </Button>
                </div>
              </div>
            </div>
            <div className="mt-4 pt-4 border-t text-sm text-gray-600">
              Mostrando {filteredPosts.length} de {myPosts.length} artigos
              {searchTerm && (
                <span className="ml-2">
                  para &quot;<strong>{searchTerm}</strong>&quot;
                </span>
              )}
            </div>
          </div>

          {/* Articles List */}
          {filteredPosts.length === 0 ? (
            <div className="text-center py-16">
              <div className="text-6xl mb-4">📝</div>
              <h3 className="text-2xl font-bold text-gray-600 mb-2">
                Nenhum artigo encontrado
              </h3>
              <p className="text-gray-500">
                {searchTerm
                  ? `Não encontramos artigos para "${searchTerm}". Tente outros termos.`
                  : 'Você ainda não publicou nenhum artigo.'}
              </p>
              {!searchTerm && (
                <Button
                  onClick={handleNewPost}
                  className="mt-6 bg-gradient-to-r from-[#4AB0D9] to-[#3A9BC1] hover:from-[#3A9BC1] hover:to-[#2E8AA8] text-white font-medium py-3 px-6 rounded-lg shadow-md hover:shadow-lg transition-all duration-200"
                >
                  <Plus className="h-5 w-5 mr-2" />
                  Publicar seu primeiro artigo
                </Button>
              )}
            </div>
          ) : (
            <div
              className={
                viewMode === 'grid'
                  ? 'grid md:grid-cols-2 lg:grid-cols-3 gap-6'
                  : 'space-y-6'
              }
            >
              {filteredPosts.map(post => (
                <Card
                  key={post.id}
                  className={`overflow-hidden hover:shadow-xl transition-all duration-300 group border-0 shadow-md ${
                    viewMode === 'list' ? 'flex' : 'flex flex-col h-full'
                  }`}
                >
                  <div
                    className={`relative ${viewMode === 'list' ? 'w-80 flex-shrink-0' : 'h-56'} bg-gray-50 rounded-t-lg overflow-hidden`}
                  >
                    <Image
                      src={post.image || '/placeholder.svg'}
                      alt={post.title}
                      width={400}
                      height={200}
                      className={`w-full h-full object-contain group-hover:scale-105 transition-transform duration-300`}
                    />
                    <Badge
                      variant="secondary"
                      className="absolute top-3 left-3 bg-white/95 text-[#4AB0D9] backdrop-blur-sm"
                    >
                      {post.category}
                    </Badge>
                    <Badge
                      variant="outline"
                      className="absolute top-3 right-3 bg-white/95 backdrop-blur-sm text-xs"
                    >
                      {post.views.toLocaleString()} views
                    </Badge>
                  </div>

                  <CardContent
                    className={`p-6 ${viewMode === 'list' ? 'flex-1' : 'flex flex-col flex-1'}`}
                  >
                    <Link href={`/blog/${post.id}`} className="block">
                      <h3
                        className={`font-bold text-[#1E1D40] mb-3 group-hover:text-[#4AB0D9] transition-colors ${
                          viewMode === 'list' ? 'text-xl' : 'text-lg'
                        } line-clamp-2`}
                      >
                        {post.title}
                      </h3>
                    </Link>

                    <p
                      className={`text-gray-600 mb-4 ${viewMode === 'list' ? 'text-base' : 'text-sm'} line-clamp-3 flex-grow`}
                    >
                      {post.excerpt}
                    </p>

                    {/* Tags */}
                    <div className="flex flex-wrap gap-1 mb-3">
                      {post.tags.slice(0, 3).map(tag => (
                        <Badge key={tag} variant="outline" className="text-xs">
                          #{tag}
                        </Badge>
                      ))}
                    </div>

                    <div className="flex items-center gap-4 text-xs text-gray-500 mb-3">
                      <div className="flex items-center gap-1">
                        <User className="h-3 w-3" />
                        <span className="truncate" title={post.author}>
                          {formatAuthorName(post.author)}
                        </span>
                      </div>
                      <div className="flex items-center gap-1">
                        <Calendar className="h-3 w-3" />
                        {new Date(post.date).toLocaleDateString('pt-BR')}
                      </div>
                      <div className="flex items-center gap-1">
                        <Clock className="h-3 w-3" />
                        {post.readTime}
                      </div>
                    </div>

                    {/* Author Badges */}
                    {post.badges && post.badges.length > 0 && (
                      <div className="flex items-center gap-2 mb-3">
                        <span className="text-xs text-gray-500">Badges:</span>
                        <div className="flex items-center gap-1 flex-wrap">
                          {post.badges.slice(0, 2).map((badge, index) => {
                            const IconComponent = badge.icon
                              ? eval(badge.icon)
                              : Award
                            return (
                              <div
