                      />
                    ) : (
                      <Building className="h-5 w-5 text-white" />
                    )}
                  </div>
                  <CardTitle className="text-xl font-bold text-[#1E1D40]">
                    {job.title}
                  </CardTitle>
                </div>
                <Badge
