  salary_max?: number
  location: string
  job_type: 'CLT' | 'PJ' | 'Estágio' | 'Freelancer'
  level: 'Estagiário' | 'Júnior' | 'Pleno' | 'Sênior' | 'Gerente'
  status: 'ativa' | 'pausada' | 'fechada'
