  company_profiles?: {
    company_name: string
    logo_url?: string
  } | null
}

interface JobDetailsModalProps {
  job: JobPosting
  isOpen: boolean
  onClose: () => void
}

export function JobDetailsModal({
  job,
  isOpen,
  onClose,
}: JobDetailsModalProps) {
  const [isApplying, setIsApplying] = useState(false)
  const { user } = useAuth()
  const supabase = createSupabaseClient()

  const formatSalaryRange = (job: JobPosting) => {
    if (job.salary_min && job.salary_max) {
      return `R$ ${job.salary_min.toLocaleString()} - R$ ${job.salary_max.toLocaleString()}`
    } else if (job.salary_min) {
      return `A partir de R$ ${job.salary_min.toLocaleString()}`
    } else if (job.salary_max) {
      return `Até R$ ${job.salary_max.toLocaleString()}`
    }
    return 'Salário a combinar'
  }

  const handleApply = async () => {
    // Silent operation - starting application process
    // Silent operation - current user info

    setIsApplying(true)
    try {
      if (!user) {
        // Silent operation - user not authenticated
        toast.error('Para se candidatar, você precisa estar logado.')
        return
      }

      // Verificar se o usuário é nutricionista
      if (user.user_type !== 'nutricionista') {
        // Silent operation - user is not a nutritionist
        toast.error('Apenas nutricionistas podem se candidatar às vagas.')
        return
      }

      // Silent operation - user authenticated as nutritionist
      // Silent operation - searching for nutritionist profile

      // Buscar o perfil do nutricionista para obter o ID correto
      const { data: nutritionistProfile, error: profileError } = await supabase
        .from('nutritionist_profiles')
        .select('id')
        .eq('user_id', user.id)
        .single()

      if (profileError || !nutritionistProfile) {
        // Silent error handling - nutritionist profile search error
        toast.error(
          'Perfil de nutricionista não encontrado. Complete seu cadastro primeiro.'
        )
        return
      }

      // Silent operation - nutritionist profile found
      // Silent operation - checking existing application

      // Verificar se já se candidatou
      const { data: existingApplication, error: checkError } = await supabase
        .from('job_applications')
        .select('id')
        .eq('job_id', job.id)
        .eq('candidate_id', nutritionistProfile.id)
        .single()

      if (checkError && checkError.code !== 'PGRST116') {
        // Silent error handling - error checking existing application
        throw checkError
      }

      if (existingApplication) {
        // Silent operation - application already exists
        toast.warning('Você já se candidatou a esta vaga!')
        return
      }

      // Silent operation - creating new application

      // Criar candidatura
      const { error } = await supabase.from('job_applications').insert({
        job_id: job.id,
        candidate_id: nutritionistProfile.id,
        status: 'pendente',
        applied_at: new Date().toISOString(),
      })

      if (error) {
        // Silent error handling - application creation error
        throw error
      }

      // Silent operation - application created successfully
      toast.success('Candidatura enviada com sucesso!')
      onClose()
    } catch (error) {
      // Silent error handling - general application error
      toast.error('Erro ao enviar candidatura. Tente novamente.')
    } finally {
      setIsApplying(false)
    }
  }

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Detalhes da Vaga</DialogTitle>
        </DialogHeader>

        <div className="space-y-6">
          {/* Header da Vaga */}
          <div className="flex items-start gap-4">
            <div className="w-16 h-16 bg-[#1E1D40] rounded-lg flex items-center justify-center flex-shrink-0">
              {job.company_profiles?.logo_url ? (
                <Image
                  src={job.company_profiles.logo_url || '/placeholder.svg'}
                  alt={job.company_profiles.company_name ?? 'Logo da empresa'}
                  width={64}
                  height={64}
                  className="rounded-lg object-cover"
                  unoptimized
                />
              ) : (
                <Building className="h-8 w-8 text-white" />
              )}
            </div>
            <div className="flex-1">
              <div className="flex items-start justify-between">
                <div>
                  <h1 className="text-2xl font-bold text-[#1E1D40] mb-2">
                    {job.title}
                  </h1>
                  <p className="text-lg text-orange-600 font-medium mb-2">
                    🏢{' '}
                    {job.company_profiles?.company_name ??
                      'Empresa confidencial'}
                  </p>
                  <div className="flex items-center gap-4 text-sm text-[#1E1D40]/70">
                    <div className="flex items-center gap-1">
                      <MapPin className="h-4 w-4" />
                      <span>{job.location}</span>
                    </div>
                    <div className="flex items-center gap-1">
                      <Briefcase className="h-4 w-4" />
                      <span>{job.job_type}</span>
                    </div>
                    <div className="flex items-center gap-1">
                      <Clock className="h-4 w-4" />
                      <span>
                        Publicada em{' '}
                        {new Date(job.created_at).toLocaleDateString('pt-BR')}
                      </span>
                    </div>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <Badge variant="outline" className="font-medium">
                    {job.level}
                  </Badge>
                  <Button variant="ghost" size="sm">
                    <Heart className="h-4 w-4" />
                  </Button>
                  <Button variant="ghost" size="sm">
                    <Share2 className="h-4 w-4" />
                  </Button>
                </div>
              </div>
            </div>
          </div>

          <Separator />

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            {/* Conteúdo Principal */}
            <div className="lg:col-span-2 space-y-6">
              {/* Descrição */}
              <div>
                <h2 className="text-xl font-semibold text-[#1E1D40] mb-3">
                  Sobre a Vaga
