interface ImageCropUploadProps {
  onImageUploaded: (url: string) => void
  onImageRemoved?: () => void
  currentImageUrl?: string
  userId: string
  className?: string
  disabled?: boolean
  aspectRatio?: number // 16/5 para capa, 1 para avatar
  cropType: 'cover' | 'avatar'
  minWidth?: number
  minHeight?: number
  title?: string
  description?: string
}

interface CropState {
  crop: Crop
  completedCrop: PixelCrop | undefined
  scale: number
  rotate: number
}

export function ImageCropUpload({
  onImageUploaded,
  onImageRemoved,
  currentImageUrl,
  userId,
  className = '',
  disabled = false,
  aspectRatio = 1,
  cropType,
  minWidth = 600,
  minHeight = 600,
  title = 'Upload de Imagem',
  description = 'Selecione uma imagem para fazer upload',
}: ImageCropUploadProps) {
  const supabase = createSupabaseClient()
  const [isUploading, setIsUploading] = useState(false)
  const [uploadError, setUploadError] = useState<string | null>(null)
  const [uploadSuccess, setUploadSuccess] = useState<string | null>(null)
  const [dragActive, setDragActive] = useState(false)
  const [showCropModal, setShowCropModal] = useState(false)
  const [selectedFile, setSelectedFile] = useState<File | null>(null)
  const [imageSrc, setImageSrc] = useState<string>('')
  const [croppedImageUrl, setCroppedImageUrl] = useState<string>('')

  const [cropState, setCropState] = useState<CropState>({
    crop: {
      unit: '%',
      width: 90,
      height: 90,
      x: 5,
      y: 5,
    },
    completedCrop: undefined,
    scale: 1,
    rotate: 0,
  })

  const fileInputRef = useRef<HTMLInputElement>(null)
  const imageRef = useRef<HTMLImageElement>(null)
  const canvasRef = useRef<HTMLCanvasElement>(null)

  // Função para validar arquivo
  const validateFile = (file: File): string | null => {
    const allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp']
    if (!allowedTypes.includes(file.type)) {
      return 'Formato nao suportado. Use JPEG, PNG ou WebP.'
    }

    if (file.size > 5 * 1024 * 1024) {
      // 5MB
      return 'Arquivo muito grande. Maximo 5MB.'
    }

    return null
  }

  // Função para validar dimensões da imagem
  const validateImageDimensions = (img: HTMLImageElement): string | null => {
    if (cropType === 'cover') {
      if (img.naturalWidth < 2000 || img.naturalHeight < 700) {
        return `Dimensao minima para capa: 2000x700px. Sua imagem: ${img.naturalWidth}x${img.naturalHeight}px`
      }
    } else if (cropType === 'avatar') {
      if (img.naturalWidth < 600 || img.naturalHeight < 600) {
        return `Dimensao minima para avatar: 600x600px. Sua imagem: ${img.naturalWidth}x${img.naturalHeight}px`
      }
    }
    return null
  }

  // Função para criar crop inicial
  const createInitialCrop = (imageWidth: number, imageHeight: number): Crop => {
    return centerCrop(
      makeAspectCrop(
        {
          unit: '%',
          width: 90,
        },
        aspectRatio,
        imageWidth,
        imageHeight
      ),
      imageWidth,
      imageHeight
    )
  }

  // Função para lidar com seleção de arquivo
  const handleFileSelect = async (file: File) => {
    if (!file || disabled) return

    const validationError = validateFile(file)
    if (validationError) {
      setUploadError(validationError)
      return
    }

    setSelectedFile(file)
    setUploadError(null)
    setUploadSuccess(null)

    // Criar URL da imagem
    const reader = new FileReader()
    reader.onload = () => {
      setImageSrc(reader.result as string)
      setShowCropModal(true)
    }
    reader.readAsDataURL(file)
  }

  // Função para lidar com carregamento da imagem no crop
  const onImageLoad = (e: React.SyntheticEvent<HTMLImageElement>) => {
    const { width, height } = e.currentTarget

    // Validar dimensões
    const dimensionError = validateImageDimensions(e.currentTarget)
    if (dimensionError) {
      setUploadError(dimensionError)
      setShowCropModal(false)
      return
    }

    // Criar crop inicial
    const initialCrop = createInitialCrop(width, height)
    setCropState(prev => ({ ...prev, crop: initialCrop }))
  }

  // Função para gerar imagem cortada
  const getCroppedImg = useCallback(async (): Promise<File | null> => {
    if (!imageRef.current || !canvasRef.current || !cropState.completedCrop) {
      return null
    }

    const image = imageRef.current
    const canvas = canvasRef.current
    const crop = cropState.completedCrop

    const scaleX = image.naturalWidth / image.width
    const scaleY = image.naturalHeight / image.height

    canvas.width = crop.width
    canvas.height = crop.height

    const ctx = canvas.getContext('2d')
    if (!ctx) return null

    // Aplicar transformações
    ctx.save()

    // Aplicar rotação se houver
    if (cropState.rotate !== 0) {
      ctx.translate(canvas.width / 2, canvas.height / 2)
      ctx.rotate((cropState.rotate * Math.PI) / 180)
      ctx.translate(-canvas.width / 2, -canvas.height / 2)
    }

    ctx.drawImage(
      image,
      crop.x * scaleX,
      crop.y * scaleY,
      crop.width * scaleX,
      crop.height * scaleY,
      0,
      0,
      crop.width,
      crop.height
    )

    ctx.restore()

    return new Promise(resolve => {
      canvas.toBlob(
        blob => {
          if (!blob || !selectedFile) {
            resolve(null)
            return
          }

          const croppedFile = new File([blob], selectedFile.name, {
            type: selectedFile.type,
            lastModified: Date.now(),
          })

          resolve(croppedFile)
        },
        selectedFile?.type || 'image/jpeg',
        0.9
      )
    })
  }, [cropState.completedCrop, cropState.rotate, selectedFile])

  // Função para fazer upload da imagem cortada
  const handleUpload = async () => {
    if (!selectedFile) return

    setIsUploading(true)
    setUploadError(null)
    setUploadSuccess(null)

    try {
      const croppedFile = await getCroppedImg()
      if (!croppedFile) {
        throw new Error('Erro ao processar a imagem')
      }

      // Obter sessão do usuário
      const {
        data: { session },
      } = await supabase.auth.getSession()
      if (!session?.access_token || !session?.user) {
        throw new Error('Usuario nao autenticado')
      }

      // Determinar tipo de usuário baseado no perfil
      let userType = 'patient' // padrão

      // Verificar se é nutricionista
      const { data: nutritionistProfile } = await supabase
        .from('nutritionist_profiles')
        .select('id')
        .eq('user_id', session.user.id)
        .single()

      if (nutritionistProfile) {
        userType = 'nutritionist'
      } else {
        // Verificar se é empresa
        const { data: companyProfile } = await supabase
          .from('company_profiles')
          .select('id')
          .eq('user_id', session.user.id)
          .single()

        if (companyProfile) {
          userType = 'company'
        }
      }

      // Preparar FormData
      const formData = new FormData()
      formData.append('file', croppedFile)
      formData.append('userId', session.user.id)
      formData.append('userType', userType)
      formData.append('imageType', cropType)
      formData.append('accessToken', session.access_token)

      // Fazer upload via API
      const response = await fetch('/api/upload-profile-image', {
        method: 'POST',
        body: formData,
      })

      const result = await response.json()

      if (!result.success) {
        throw new Error(result.error || 'Erro no upload')
      }

      // Atualizar perfil no banco de dados
      const updateField =
        cropType === 'cover' ? 'cover_image_url' : 'profile_image_url'
      const tableName =
        userType === 'nutritionist'
          ? 'nutritionist_profiles'
          : userType === 'company'
            ? 'company_profiles'
            : 'patient_profiles'

      const { error: updateError } = await supabase
        .from(tableName)
        .update({ [updateField]: result.url })
        .eq('user_id', session.user.id)

      if (updateError) {
        // Silent error handling: Error updating profile
        // Não falhar completamente, pois a imagem foi enviada com sucesso
      }

      onImageUploaded(result.url)
      setUploadSuccess('Imagem enviada com sucesso!')
      setShowCropModal(false)
      setSelectedFile(null)
      setImageSrc('')
      setCroppedImageUrl('')

      // Limpar mensagem de sucesso após 3 segundos
      setTimeout(() => setUploadSuccess(null), 3000)
    } catch (error) {
      // Silent error handling: Upload error
      setUploadError(error instanceof Error ? error.message : 'Erro no upload')
    } finally {
      setIsUploading(false)
    }
  }

  // Função para remover imagem
  const handleRemove = () => {
    if (onImageRemoved) {
      onImageRemoved()
      setUploadSuccess('Imagem removida com sucesso!')
      setTimeout(() => setUploadSuccess(null), 3000)
    }
  }

  // Handlers para drag and drop
  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true)
    } else if (e.type === 'dragleave') {
      setDragActive(false)
    }
  }

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setDragActive(false)

    if (disabled) return

    const file = e.dataTransfer.files?.[0]
    if (file && file.type.startsWith('image/')) {
      handleFileSelect(file)
    }
  }

  const openFileDialog = () => {
    if (!disabled) {
      fileInputRef.current?.click()
    }
  }

  const handleFileInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (file) {
      handleFileSelect(file)
    }
  }

  // Reset crop quando mudar a escala ou rotação
  useEffect(() => {
    if (imageRef.current) {
      const { width, height } = imageRef.current
      const newCrop = createInitialCrop(width, height)
      setCropState(prev => ({ ...prev, crop: newCrop }))
    }
  }, [cropState.scale, cropState.rotate, aspectRatio])

  return (
    <div className={`space-y-4 ${className}`}>
      {/* Preview da imagem atual */}
      {currentImageUrl && (
        <Card className="relative overflow-hidden">
          <div
            className={`relative ${cropType === 'cover' ? 'aspect-[16/5]' : 'aspect-square w-32 h-32 mx-auto'}`}
          >
            <Image
              src={currentImageUrl}
              alt={cropType === 'cover' ? 'Capa atual' : 'Avatar atual'}
              fill
              className={`object-cover ${cropType === 'avatar' ? 'rounded-full' : ''}`}
              key={currentImageUrl}
            />
          </div>
          <div className="absolute top-2 right-2 flex gap-2">
            <Button
              size="sm"
              variant="destructive"
              onClick={handleRemove}
              disabled={disabled}
            >
              <X className="h-4 w-4" />
            </Button>
          </div>
        </Card>
      )}

      {/* Área de upload */}
      <Card
        className={`relative border-2 border-dashed transition-colors cursor-pointer ${
          dragActive
            ? 'border-primary bg-primary/5'
            : 'border-gray-300 hover:border-gray-400'
        } ${disabled ? 'opacity-50 cursor-not-allowed' : ''}`}
        onDragEnter={handleDrag}
        onDragLeave={handleDrag}
        onDragOver={handleDrag}
        onDrop={handleDrop}
        onClick={openFileDialog}
      >
        <div className="p-8 text-center">
          <div className="flex flex-col items-center justify-center space-y-4">
            <div className="flex items-center justify-center w-16 h-16 bg-gray-100 rounded-full">
              <ImageIcon className="h-8 w-8 text-gray-400" />
            </div>
            <div className="space-y-2">
              <p className="text-sm font-medium">{title}</p>
              <p className="text-xs text-gray-500">{description}</p>
              <p className="text-xs text-gray-400">
                {cropType === 'cover'
                  ? 'Formatos: JPEG, PNG, WebP - Min: 2000x700px - Max: 5MB'
                  : 'Formatos: JPEG, PNG, WebP - Min: 600x600px - Max: 5MB'}
              </p>
            </div>
            <Button
              type="button"
              variant="outline"
              size="sm"
              disabled={disabled}
            >
              <Upload className="h-4 w-4 mr-2" />
              Selecionar Arquivo
            </Button>
          </div>
        </div>
      </Card>

      {/* Input de arquivo oculto */}
      <input
        ref={fileInputRef}
        type="file"
        accept="image/jpeg,image/jpg,image/png,image/webp"
        onChange={handleFileInputChange}
        className="hidden"
        disabled={disabled}
      />

      {/* Mensagens de erro e sucesso */}
      {uploadError && (
        <div className="bg-red-50 border border-red-200 rounded-lg p-4">
          <p className="text-sm text-red-600">{uploadError}</p>
        </div>
      )}

      {uploadSuccess && (
        <div className="bg-green-50 border border-green-200 rounded-lg p-4">
          <p className="text-sm text-green-600">{uploadSuccess}</p>
        </div>
      )}

      {/* Modal de crop */}
      <Dialog open={showCropModal} onOpenChange={setShowCropModal}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {cropType === 'cover'
                ? 'Editar Capa do Perfil'
                : 'Editar Foto de Perfil'}
            </DialogTitle>
          </DialogHeader>

          <div className="space-y-6">
            {/* Controles de transformação */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="space-y-2">
                <Label>Zoom: {cropState.scale.toFixed(1)}x</Label>
                <Slider
                  value={[cropState.scale]}
                  onValueChange={([value]) =>
                    setCropState(prev => ({ ...prev, scale: value }))
                  }
                  min={0.5}
                  max={3}
                  step={0.1}
                  className="w-full"
                />
              </div>

              <div className="space-y-2">
                <Label>Rotacao: {cropState.rotate} graus</Label>
                <Slider
                  value={[cropState.rotate]}
                  onValueChange={([value]) =>
                    setCropState(prev => ({ ...prev, rotate: value }))
                  }
                  min={-180}
                  max={180}
                  step={1}
                  className="w-full"
                />
              </div>

              <div className="flex items-end gap-2">
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() =>
                    setCropState(prev => ({
                      ...prev,
                      scale: 1,
                      rotate: 0,
                    }))
                  }
                >
                  <RefreshCw className="h-4 w-4 mr-2" />
                  Reset
                </Button>
              </div>
            </div>

            {/* Área de crop */}
            <div className="relative bg-gray-100 rounded-lg overflow-hidden">
              {imageSrc && (
                <ReactCrop
                  crop={cropState.crop}
                  onChange={(_, percentCrop) =>
                    setCropState(prev => ({ ...prev, crop: percentCrop }))
                  }
                  onComplete={c =>
                    setCropState(prev => ({ ...prev, completedCrop: c }))
                  }
                  aspect={aspectRatio}
                  minWidth={minWidth / 4}
                  minHeight={minHeight / 4}
                >
                  <img
                    ref={imageRef}
                    alt="Crop"
                    src={imageSrc}
                    style={{
                      transform: `scale(${cropState.scale}) rotate(${cropState.rotate}deg)`,
                      maxHeight: '400px',
                      width: 'auto',
                    }}
                    onLoad={onImageLoad}
                  />
                </ReactCrop>
              )}
            </div>

            {/* Preview do crop */}
            {cropState.completedCrop && (
              <div className="space-y-2">
                <Label>Preview:</Label>
                <div
                  className={`relative mx-auto ${
                    cropType === 'cover' ? 'w-80 h-20' : 'w-24 h-24'
                  }`}
                >
                  <canvas
                    ref={canvasRef}
                    className={`w-full h-full border border-gray-300 ${
                      cropType === 'avatar' ? 'rounded-full' : 'rounded'
                    }`}
                    style={{
                      width: cropType === 'cover' ? '320px' : '96px',
                      height: cropType === 'cover' ? '80px' : '96px',
                    }}
                  />
                </div>
              </div>
            )}
          </div>

          <DialogFooter className="flex gap-2">
            <Button
              type="button"
              variant="outline"
              onClick={() => setShowCropModal(false)}
              disabled={isUploading}
            >
              Cancelar
            </Button>
            <Button
              type="button"
              onClick={handleUpload}
              disabled={isUploading || !cropState.completedCrop}
            >
              {isUploading ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Enviando...
                </>
              ) : (
                <>
                  <Upload className="h-4 w-4 mr-2" />
                  Salvar
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

'use client'

import { useState, useCallback, useEffect } from 'react'
import Image, { ImageProps } from 'next/image'
import { User, ImageIcon, AlertCircle } from 'lucide-react'
import { cn } from '@/lib/utils'

interface ImageFallbackProps extends Omit<ImageProps, 'src' | 'alt'> {
  src: string | null | undefined
  alt: string
  fallbackSrc?: string
  fallbackType?: 'user' | 'image' | 'error' | 'custom'
  fallbackComponent?: React.ReactNode
  retryAttempts?: number
  retryDelay?: number
  onError?: (error: string) => void
  onRetry?: (attempt: number) => void
  onFallback?: () => void
  className?: string
  fallbackClassName?: string
  showErrorMessage?: boolean
  cacheKey?: string
}

const DEFAULT_FALLBACKS = {
  user: '/images/default-avatar.svg',
  image: '/images/default-image.svg',
  error: '/images/error-image.svg',
}

// Cache para URLs que falharam
const failedUrls = new Set<string>()
const retryCount = new Map<string, number>()

export function ImageFallback({
  src,
  alt,
  fallbackSrc,
  fallbackType = 'image',
  fallbackComponent,
  retryAttempts = 2,
  retryDelay = 1000,
  onError,
  onRetry,
  onFallback,
  className,
  fallbackClassName,
  showErrorMessage = false,
  cacheKey,
  ...props
}: ImageFallbackProps) {
  const [currentSrc, setCurrentSrc] = useState<string | null>(src || null)
  const [hasError, setHasError] = useState(false)
  const [isRetrying, setIsRetrying] = useState(false)
  const [attempts, setAttempts] = useState(0)

  const cacheKeyToUse = cacheKey || src || 'unknown'

  // Verificar se a URL já falhou antes
  useEffect(() => {
    if (src && failedUrls.has(src)) {
      setHasError(true)
      setCurrentSrc(null)
    } else if (src) {
      setCurrentSrc(src)
      setHasError(false)
      setAttempts(0)
    }
  }, [src])

  // Função para tentar novamente
  const retryLoad = useCallback(
    async (url: string, attempt: number) => {
      if (attempt >= retryAttempts) {
        failedUrls.add(url)
        retryCount.set(cacheKeyToUse, attempt)
        setIsRetrying(false)
        setHasError(true)
        setCurrentSrc(null)
        onFallback?.()
        return
      }

      setIsRetrying(true)
      onRetry?.(attempt + 1)

      // Aguardar antes de tentar novamente
      await new Promise(resolve => setTimeout(resolve, retryDelay))

      // Tentar carregar a imagem
      const img = new window.Image()

      img.onload = () => {
        setCurrentSrc(url)
        setHasError(false)
        setIsRetrying(false)
        setAttempts(attempt + 1)
        // Remover da lista de falhas se carregar com sucesso
        failedUrls.delete(url)
        retryCount.delete(cacheKeyToUse)
      }

      img.onerror = () => {
        setAttempts(attempt + 1)
        retryLoad(url, attempt + 1)
      }

      // Adicionar cache busting para retry
      const cacheBustUrl = `${url}${url.includes('?') ? '&' : '?'}retry=${attempt}&t=${Date.now()}`
      img.src = cacheBustUrl
    },
    [retryAttempts, retryDelay, onRetry, onFallback, cacheKeyToUse]
  )

  // Handler para erro de carregamento
  const handleError = useCallback(() => {
    const errorMessage = `Failed to load image: ${currentSrc}`
    // Silent error handling: Failed to load image
    onError?.(errorMessage)

    if (currentSrc && attempts < retryAttempts) {
      retryLoad(currentSrc, attempts)
    } else {
      setHasError(true)
      setCurrentSrc(null)
      if (currentSrc) {
        failedUrls.add(currentSrc)
      }
      onFallback?.()
    }
  }, [currentSrc, attempts, retryAttempts, retryLoad, onError, onFallback])

  // Função para limpar cache de falhas
  const clearFailureCache = useCallback(() => {
    failedUrls.clear()
    retryCount.clear()
    if (src) {
      setCurrentSrc(src)
      setHasError(false)
      setAttempts(0)
    }
  }, [src])

  // Expor função de limpeza globalmente
  useEffect(() => {
    // @ts-ignore
    window.clearImageFailureCache = clearFailureCache
  }, [clearFailureCache])

  // Determinar o fallback a ser usado
  const getFallbackSrc = useCallback(() => {
    if (fallbackSrc) return fallbackSrc
    return DEFAULT_FALLBACKS[fallbackType] || DEFAULT_FALLBACKS.image
  }, [fallbackSrc, fallbackType])

  // Renderizar componente de fallback customizado
  if (hasError && fallbackComponent) {
    return (
      <div
        className={cn('flex items-center justify-center', fallbackClassName)}
      >
        {fallbackComponent}
      </div>
    )
  }

  // Renderizar ícone de fallback
  if (hasError && !fallbackSrc && !DEFAULT_FALLBACKS[fallbackType]) {
    const IconComponent =
      fallbackType === 'user'
        ? User
        : fallbackType === 'error'
          ? AlertCircle
          : ImageIcon

    return (
      <div
        className={cn(
          'flex flex-col items-center justify-center bg-gray-100 text-gray-400 rounded',
          fallbackClassName,
          className
        )}
      >
        <IconComponent className="w-8 h-8 mb-2" />
        {showErrorMessage && (
          <span className="text-xs text-center px-2">
            Imagem não disponível
          </span>
        )}
        {isRetrying && (
          <span className="text-xs text-blue-500 mt-1">
            Tentando novamente...
          </span>
        )}
      </div>
    )
  }

  // Renderizar imagem ou fallback
  const imageSrc = currentSrc || getFallbackSrc()

  if (!imageSrc) {
    return (
      <div
        className={cn(
          'flex items-center justify-center bg-gray-100 text-gray-400 rounded',
          fallbackClassName,
          className
        )}
      >
        <ImageIcon className="w-8 h-8" />
      </div>
    )
  }

  return (
    <div className="relative">
      <Image
        {...props}
        src={imageSrc}
        alt={alt}
        className={cn(className, isRetrying && 'opacity-50')}
        onError={handleError}
        // Adicionar cache busting se estiver retrying
        key={isRetrying ? `${imageSrc}-${Date.now()}` : imageSrc}
      />

      {isRetrying && (
        <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-20 rounded">
          <div className="bg-white px-2 py-1 rounded text-xs text-gray-600">
            Carregando... ({attempts + 1}/{retryAttempts + 1})
          </div>
        </div>
      )}
    </div>
  )
}

// Hook para gerenciar cache de imagens
export function useImageCache() {
  const clearCache = useCallback(() => {
    failedUrls.clear()
    retryCount.clear()
    // @ts-ignore
    if (typeof window !== 'undefined' && window.clearImageFailureCache) {
      // @ts-ignore
      window.clearImageFailureCache()
    }
  }, [])

  const getFailedUrls = useCallback(() => {
    return Array.from(failedUrls)
  }, [])

  const getRetryCount = useCallback((url: string) => {
    return retryCount.get(url) || 0
  }, [])

  const preloadImage = useCallback((url: string): Promise<boolean> => {
    return new Promise(resolve => {
      const img = new window.Image()
      img.onload = () => resolve(true)
      img.onerror = () => {
        failedUrls.add(url)
        resolve(false)
      }
      img.src = url
    })
  }, [])

  return {
    clearCache,
    getFailedUrls,
    getRetryCount,
    preloadImage,
    failedCount: failedUrls.size,
  }
}

// Componente específico para avatar de usuário
export function UserAvatar({
  src,
  name,
  size = 40,
  className,
  ...props
}: {
  src?: string | null
  name: string
  size?: number
  className?: string
} & Omit<ImageFallbackProps, 'src' | 'alt' | 'fallbackType'>) {
  return (
    <ImageFallback
      src={src}
      alt={`Avatar de ${name}`}
      fallbackType="user"
      width={size}
      height={size}
      className={cn('rounded-full object-cover', className)}
      fallbackClassName="rounded-full"
      {...props}
    />
  )
}

// Componente específico para imagens de conteúdo
export function ContentImage({
  src,
  alt,
  className,
  ...props
}: {
  src?: string | null
  alt: string
  className?: string
} & Omit<ImageFallbackProps, 'fallbackType'>) {
  return (
    <ImageFallback
      src={src}
      alt={alt}
      fallbackType="image"
      className={cn('object-cover', className)}
      showErrorMessage={true}
      {...props}
    />
  )
}

'use client'

import React, { useState, useRef } from 'react'
import Image from 'next/image'
import { Button } from './button'
import { Card } from './card'
import { uploadBlogImage, UploadResult } from '@/lib/image-upload'
import { Loader2, Upload, X, Image as ImageIcon } from 'lucide-react'

interface ImageUploadProps {
  onImageUploaded: (url: string) => void
  onImageRemoved?: () => void
  currentImageUrl?: string
  userId: string
  className?: string
  disabled?: boolean
}

export function ImageUpload({
  onImageUploaded,
  onImageRemoved,
  currentImageUrl,
  userId,
  className = '',
  disabled = false,
}: ImageUploadProps) {
  const [isUploading, setIsUploading] = useState(false)
  const [uploadError, setUploadError] = useState<string | null>(null)
  const [dragActive, setDragActive] = useState(false)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleFileSelect = async (file: File) => {
    if (!file || disabled) return

    setIsUploading(true)
    setUploadError(null)

    try {
      const result: UploadResult = await uploadBlogImage(file, userId)

      if (result.success && result.url) {
        onImageUploaded(result.url)
      } else {
        setUploadError(result.error || 'Erro ao fazer upload da imagem')
      }
    } catch (error) {
      setUploadError('Erro inesperado ao fazer upload')
      // Silent error handling: Upload error
    } finally {
      setIsUploading(false)
    }
  }

  const handleFileInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (file) {
      handleFileSelect(file)
    }
  }

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true)
    } else if (e.type === 'dragleave') {
      setDragActive(false)
    }
  }

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setDragActive(false)

    if (disabled) return

    const file = e.dataTransfer.files?.[0]
    if (file && file.type.startsWith('image/')) {
      handleFileSelect(file)
    }
  }

  const handleRemoveImage = () => {
    if (onImageRemoved) {
      onImageRemoved()
    }
    setUploadError(null)
  }

  const openFileDialog = () => {
    if (!disabled) {
      fileInputRef.current?.click()
    }
  }

  return (
    <div className={`space-y-4 ${className}`}>
      {currentImageUrl ? (
        <Card className="relative overflow-hidden">
          <div className="aspect-video relative">
            <Image
              src={currentImageUrl}
              alt="Imagem selecionada"
              fill
              className="object-cover"
              key={currentImageUrl} // Force re-render when URL changes
              onLoad={() => {
                // Silent operation: Image loaded successfully
              }}
              onError={e => {
                // Silent error handling: Error loading image
              }}
            />
            {!disabled && (
              <Button
                type="button"
                variant="destructive"
                size="sm"
                className="absolute top-2 right-2"
                onClick={handleRemoveImage}
              >
                <X className="h-4 w-4" />
              </Button>
            )}
          </div>
          <div className="p-2 text-xs text-gray-500 text-center truncate">
            {currentImageUrl}
          </div>
        </Card>
      ) : (
        <Card
          className={`
            border-2 border-dashed p-8 text-center cursor-pointer transition-colors
            ${dragActive ? 'border-primary bg-primary/5' : 'border-gray-300'}
            ${disabled ? 'opacity-50 cursor-not-allowed' : 'hover:border-primary hover:bg-primary/5'}
          `}
          onDragEnter={handleDrag}
          onDragLeave={handleDrag}
          onDragOver={handleDrag}
          onDrop={handleDrop}
          onClick={openFileDialog}
        >
          <div className="flex flex-col items-center space-y-4">
            {isUploading ? (
              <>
                <Loader2 className="h-12 w-12 animate-spin text-primary" />
                <p className="text-sm text-gray-600">Fazendo upload...</p>
              </>
            ) : (
              <>
                <div className="flex items-center justify-center w-16 h-16 bg-gray-100 rounded-full">
                  <ImageIcon className="h-8 w-8 text-gray-400" />
                </div>
                <div className="space-y-2">
                  <p className="text-sm font-medium">
                    Clique para selecionar ou arraste uma imagem
                  </p>
                  <p className="text-xs text-gray-500">
                    PNG, JPG, WebP ou GIF até 5MB
                  </p>
                </div>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  disabled={disabled}
                >
                  <Upload className="h-4 w-4 mr-2" />
                  Selecionar Imagem
                </Button>
              </>
            )}
          </div>
        </Card>
      )}

      {uploadError && (
        <div className="p-3 bg-red-50 border border-red-200 rounded-md">
          <p className="text-sm text-red-600">{uploadError}</p>
        </div>
      )}

      <input
        ref={fileInputRef}
        type="file"
        accept="image/*"
        onChange={handleFileInputChange}
        className="hidden"
        disabled={disabled}
      />
    </div>
  )
}

'use client'

import React, { useState, useRef, useCallback } from 'react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import {
  Trash2,
  Upload,
  FileText,
  AlertCircle,
  CheckCircle,
  Plus,
  X,
} from 'lucide-react'
import { Alert, AlertDescription } from '@/components/ui/alert'

interface Certificate {
  id?: string
  title: string
  file: File | null
  fileName?: string
  fileUrl?: string
  fileSize?: number
  isUploaded?: boolean
}

interface NutritionistDocumentsUploadProps {
  // Props para CRN
  crnNumber: string
  onCrnNumberChange: (value: string) => void
  crnProofFile: File | null
  onCrnProofFileChange: (file: File | null) => void
  crnProofUrl?: string

  // Props para certificados
  certificates: Certificate[]
  onCertificatesChange: (certificates: Certificate[]) => void

  // Props gerais
  isRequired?: boolean
  disabled?: boolean
  className?: string
}

export function NutritionistDocumentsUpload({
  crnNumber,
  onCrnNumberChange,
  crnProofFile,
  onCrnProofFileChange,
  crnProofUrl,
  certificates,
  onCertificatesChange,
  isRequired = true,
  disabled = false,
  className = '',
}: NutritionistDocumentsUploadProps) {
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [dragOver, setDragOver] = useState<string | null>(null)

  const crnFileInputRef = useRef<HTMLInputElement>(null)
  const certificateFileInputRefs = useRef<
    Record<number, HTMLInputElement | null>
  >({})

  // Validação de arquivo
  const validateFile = useCallback((file: File): string | null => {
    const maxSize = 5 * 1024 * 1024 // 5MB
    const allowedTypes = [
      'application/pdf',
      'image/jpeg',
      'image/jpg',
      'image/png',
    ]

    if (!allowedTypes.includes(file.type)) {
      return 'Formato inválido. Aceitos: PDF, JPG, PNG'
    }

    if (file.size > maxSize) {
      return 'Arquivo muito grande. Máximo: 5MB'
    }

    return null
  }, [])

  // Formatação de tamanho de arquivo
  const formatFileSize = useCallback((bytes: number): string => {
    if (bytes === 0) return '0 Bytes'
    const k = 1024
    const sizes = ['Bytes', 'KB', 'MB', 'GB']
    const i = Math.floor(Math.log(bytes) / Math.log(k))
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
  }, [])

  // Handlers para CRN
  const handleCrnFileSelect = useCallback(
    (file: File) => {
      const error = validateFile(file)
      if (error) {
        setErrors(prev => ({ ...prev, crnProof: error }))
        return
      }

      setErrors(prev => ({ ...prev, crnProof: '' }))
      onCrnProofFileChange(file)
    },
    [validateFile, onCrnProofFileChange]
  )

  const handleCrnFileDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault()
      setDragOver(null)

      const files = Array.from(e.dataTransfer.files)
      if (files.length > 0) {
        handleCrnFileSelect(files[0])
      }
    },
    [handleCrnFileSelect]
  )

  const handleCrnFileInputChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files
      if (files && files.length > 0) {
        handleCrnFileSelect(files[0])
      }
    },
    [handleCrnFileSelect]
  )

  // Handlers para certificados
  const addCertificate = useCallback(() => {
    const newCertificate: Certificate = {
      title: '',
      file: null,
    }
    onCertificatesChange([...certificates, newCertificate])
  }, [certificates, onCertificatesChange])

  const removeCertificate = useCallback(
    (index: number) => {
      const newCertificates = certificates.filter((_, i) => i !== index)
      onCertificatesChange(newCertificates)

      // Limpar erros do certificado removido
      setErrors(prev => {
        const newErrors = { ...prev }
        delete newErrors[`certificate_${index}_title`]
        delete newErrors[`certificate_${index}_file`]
        return newErrors
      })
    },
    [certificates, onCertificatesChange]
  )

  const updateCertificateTitle = useCallback(
    (index: number, title: string) => {
      const newCertificates = [...certificates]
      newCertificates[index] = { ...newCertificates[index], title }
      onCertificatesChange(newCertificates)

      // Limpar erro de título se preenchido
      if (title.trim()) {
        setErrors(prev => ({ ...prev, [`certificate_${index}_title`]: '' }))
      }
    },
    [certificates, onCertificatesChange]
  )

  const updateCertificateFile = useCallback(
    (index: number, file: File) => {
      const error = validateFile(file)
      if (error) {
        setErrors(prev => ({ ...prev, [`certificate_${index}_file`]: error }))
        return
      }

      const newCertificates = [...certificates]
      newCertificates[index] = { ...newCertificates[index], file }
      onCertificatesChange(newCertificates)

      setErrors(prev => ({ ...prev, [`certificate_${index}_file`]: '' }))
    },
    [certificates, onCertificatesChange, validateFile]
  )

  const handleCertificateFileDrop = useCallback(
    (e: React.DragEvent, index: number) => {
      e.preventDefault()
      setDragOver(null)

      const files = Array.from(e.dataTransfer.files)
      if (files.length > 0) {
        updateCertificateFile(index, files[0])
      }
    },
    [updateCertificateFile]
  )

  const handleCertificateFileInputChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>, index: number) => {
      const files = e.target.files
      if (files && files.length > 0) {
        updateCertificateFile(index, files[0])
      }
    },
    [updateCertificateFile]
  )

  // Validação geral
  const isValid = useCallback(() => {
    // CRN obrigatório
    if (isRequired && (!crnNumber.trim() || !crnProofFile)) {
      return false
    }

    // Verificar erros
    const hasErrors = Object.values(errors).some(error => error.trim() !== '')
    if (hasErrors) {
      return false
    }

    // Validar certificados (se tiver título, deve ter arquivo e vice-versa)
    for (const cert of certificates) {
      if (cert.title.trim() && !cert.file) {
        return false
      }
      if (!cert.title.trim() && cert.file) {
        return false
      }
    }

    return true
  }, [isRequired, crnNumber, crnProofFile, errors, certificates])

  return (
    <div className={`space-y-6 ${className}`}>
      {/* Seção CRN */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <FileText className="h-5 w-5" />
            CRN - Conselho Regional de Nutricionistas
            {isRequired && <Badge variant="destructive">Obrigatório</Badge>}
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Número do CRN */}
          <div className="space-y-2">
            <Label htmlFor="crn-number">Número do CRN *</Label>
            <Input
              id="crn-number"
              type="text"
              placeholder="Ex: 12345"
              value={crnNumber}
              onChange={e => onCrnNumberChange(e.target.value)}
              disabled={disabled}
              className={errors.crnNumber ? 'border-red-500' : ''}
            />
            {errors.crnNumber && (
              <p className="text-sm text-red-500">{errors.crnNumber}</p>
            )}
          </div>

          {/* Upload do Comprovante */}
          <div className="space-y-2">
            <Label>Comprovante do CRN *</Label>
            <div
              className={`
                border-2 border-dashed rounded-lg p-6 text-center cursor-pointer transition-colors
                ${dragOver === 'crn' ? 'border-blue-500 bg-blue-50' : 'border-gray-300'}
                ${errors.crnProof ? 'border-red-500' : ''}
                ${disabled ? 'opacity-50 cursor-not-allowed' : 'hover:border-gray-400'}
              `}
              onDragOver={e => {
                e.preventDefault()
                if (!disabled) setDragOver('crn')
              }}
              onDragLeave={() => setDragOver(null)}
              onDrop={e => !disabled && handleCrnFileDrop(e)}
              onClick={() => !disabled && crnFileInputRef.current?.click()}
            >
              <input
                ref={crnFileInputRef}
                type="file"
                accept=".pdf,.jpg,.jpeg,.png"
                onChange={handleCrnFileInputChange}
                className="hidden"
                disabled={disabled}
              />

              {crnProofFile || crnProofUrl ? (
                <div className="flex items-center justify-center gap-2">
                  <CheckCircle className="h-5 w-5 text-green-500" />
                  <span className="text-sm font-medium">
                    {crnProofFile?.name || 'Comprovante enviado'}
                  </span>
                  {crnProofFile && (
                    <span className="text-xs text-gray-500">
                      ({formatFileSize(crnProofFile.size)})
                    </span>
                  )}
                </div>
              ) : (
                <div className="space-y-2">
                  <Upload className="h-8 w-8 mx-auto text-gray-400" />
                  <div>
                    <p className="text-sm font-medium">
                      Clique ou arraste o arquivo aqui
                    </p>
                    <p className="text-xs text-gray-500">
                      PDF, JPG, PNG - Máx: 5MB
                    </p>
                  </div>
                </div>
              )}
            </div>
            {errors.crnProof && (
              <Alert variant="destructive">
                <AlertCircle className="h-4 w-4" />
                <AlertDescription>{errors.crnProof}</AlertDescription>
              </Alert>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Seção Certificados */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <FileText className="h-5 w-5" />
              Certificados
              <Badge variant="secondary">Opcional</Badge>
            </div>
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={addCertificate}
              disabled={disabled}
            >
              <Plus className="h-4 w-4 mr-2" />
              Adicionar
            </Button>
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {certificates.length === 0 ? (
            <p className="text-sm text-gray-500 text-center py-4">
              Nenhum certificado adicionado. Clique em "Adicionar" para incluir
              certificados.
            </p>
          ) : (
            certificates.map((certificate, index) => (
              <Card key={index} className="border border-gray-200">
                <CardContent className="p-4 space-y-4">
                  <div className="flex items-center justify-between">
                    <Label>Certificado {index + 1}</Label>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={() => removeCertificate(index)}
                      disabled={disabled}
                    >
                      <X className="h-4 w-4" />
                    </Button>
                  </div>

                  {/* Título do certificado */}
                  <div className="space-y-2">
                    <Label htmlFor={`cert-title-${index}`}>Título</Label>
                    <Input
                      id={`cert-title-${index}`}
                      type="text"
                      placeholder="Ex: Especialização em Nutrição Esportiva"
                      value={certificate.title}
                      onChange={e =>
                        updateCertificateTitle(index, e.target.value)
                      }
                      disabled={disabled}
                      className={
                        errors[`certificate_${index}_title`]
                          ? 'border-red-500'
                          : ''
                      }
                    />
                    {errors[`certificate_${index}_title`] && (
                      <p className="text-sm text-red-500">
                        {errors[`certificate_${index}_title`]}
                      </p>
                    )}
                  </div>

                  {/* Upload do arquivo */}
                  <div className="space-y-2">
                    <Label>Arquivo</Label>
                    <div
                      className={`
                        border-2 border-dashed rounded-lg p-4 text-center cursor-pointer transition-colors
                        ${dragOver === `cert-${index}` ? 'border-blue-500 bg-blue-50' : 'border-gray-300'}
                        ${errors[`certificate_${index}_file`] ? 'border-red-500' : ''}
                        ${disabled ? 'opacity-50 cursor-not-allowed' : 'hover:border-gray-400'}
                      `}
                      onDragOver={e => {
                        e.preventDefault()
                        if (!disabled) setDragOver(`cert-${index}`)
                      }}
                      onDragLeave={() => setDragOver(null)}
                      onDrop={e =>
                        !disabled && handleCertificateFileDrop(e, index)
                      }
                      onClick={() =>
                        !disabled &&
                        certificateFileInputRefs.current[index]?.click()
                      }
                    >
                      <input
                        ref={el =>
                          (certificateFileInputRefs.current[index] = el)
                        }
                        type="file"
                        accept=".pdf,.jpg,.jpeg,.png"
                        onChange={e =>
                          handleCertificateFileInputChange(e, index)
                        }
                        className="hidden"
                        disabled={disabled}
                      />

                      {certificate.file || certificate.fileUrl ? (
                        <div className="flex items-center justify-center gap-2">
                          <CheckCircle className="h-4 w-4 text-green-500" />
                          <span className="text-sm font-medium">
                            {certificate.file?.name ||
                              certificate.fileName ||
                              'Arquivo enviado'}
                          </span>
                          {certificate.file && (
                            <span className="text-xs text-gray-500">
                              ({formatFileSize(certificate.file.size)})
                            </span>
                          )}
                        </div>
                      ) : (
                        <div className="space-y-1">
                          <Upload className="h-6 w-6 mx-auto text-gray-400" />
                          <div>
                            <p className="text-sm">
                              Clique ou arraste o arquivo
                            </p>
                            <p className="text-xs text-gray-500">
                              PDF, JPG, PNG - Máx: 5MB
                            </p>
                          </div>
                        </div>
                      )}
                    </div>
                    {errors[`certificate_${index}_file`] && (
                      <Alert variant="destructive">
                        <AlertCircle className="h-4 w-4" />
                        <AlertDescription>
                          {errors[`certificate_${index}_file`]}
                        </AlertDescription>
                      </Alert>
                    )}
                  </div>
                </CardContent>
              </Card>
            ))
          )}
        </CardContent>
      </Card>

      {/* Informações importantes */}
      <Alert>
        <AlertCircle className="h-4 w-4" />
        <AlertDescription>
          <strong>Importante:</strong> O número do CRN e o comprovante são
          obrigatórios para concluir o cadastro. Os certificados são opcionais e
          podem ser adicionados ou removidos posteriormente no seu painel.
        </AlertDescription>
      </Alert>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { Star } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Textarea } from '@/components/ui/textarea'
import { Label } from '@/components/ui/label'

interface RatingModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  consultationId: string
  nutritionistName: string
  onSubmit: (rating: number, comment: string) => Promise<void>
}

export function RatingModal({
  open,
  onOpenChange,
  consultationId,
  nutritionistName,
  onSubmit,
}: RatingModalProps) {
  const [rating, setRating] = useState(0)
  const [hoveredRating, setHoveredRating] = useState(0)
  const [comment, setComment] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)

  const handleSubmit = async () => {
    if (rating === 0) return

    setIsSubmitting(true)
    try {
      await onSubmit(rating, comment)
      onOpenChange(false)
      setRating(0)
      setComment('')
    } catch (error) {
      // Silent error handling: Error submitting rating
    } finally {
      setIsSubmitting(false)
    }
  }

  const getRatingText = (rating: number) => {
    switch (rating) {
      case 1:
        return 'Muito insatisfeito'
      case 2:
        return 'Insatisfeito'
      case 3:
        return 'Neutro'
      case 4:
        return 'Satisfeito'
      case 5:
        return 'Muito satisfeito'
      default:
        return 'Selecione uma avaliação'
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle>Avaliar Consulta</DialogTitle>
          <DialogDescription>
            Como foi sua experiência com {nutritionistName}?
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6 py-4">
          {/* Rating Stars */}
          <div className="space-y-2">
            <Label>Avaliação</Label>
            <div className="flex items-center space-x-1">
              {[1, 2, 3, 4, 5].map(star => (
                <button
                  key={star}
                  type="button"
                  className="p-1 hover:scale-110 transition-transform"
                  onMouseEnter={() => setHoveredRating(star)}
                  onMouseLeave={() => setHoveredRating(0)}
                  onClick={() => setRating(star)}
                >
                  <Star
                    className={`w-8 h-8 ${
                      star <= (hoveredRating || rating)
                        ? 'fill-yellow-400 text-yellow-400'
                        : 'text-gray-300'
                    }`}
                  />
                </button>
              ))}
            </div>
            <p className="text-sm text-muted-foreground">
              {getRatingText(hoveredRating || rating)}
            </p>
          </div>

          {/* Comment */}
          <div className="space-y-2">
            <Label htmlFor="comment">Comentário (opcional)</Label>
            <Textarea
              id="comment"
              placeholder="Conte-nos mais sobre sua experiência..."
              value={comment}
              onChange={e => setComment(e.target.value)}
              rows={4}
            />
          </div>
        </div>

        <DialogFooter>
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={isSubmitting}
          >
            Cancelar
          </Button>
          <Button
            onClick={handleSubmit}
            disabled={rating === 0 || isSubmitting}
          >
            {isSubmitting ? 'Enviando...' : 'Enviar Avaliação'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import React, { useCallback, useEffect } from 'react'
import { useEditor, EditorContent } from '@tiptap/react'
import StarterKit from '@tiptap/starter-kit'
import Image from '@tiptap/extension-image'
import Link from '@tiptap/extension-link'
import TextAlign from '@tiptap/extension-text-align'
import Youtube from '@tiptap/extension-youtube'
import Placeholder from '@tiptap/extension-placeholder'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Checkbox } from '@/components/ui/checkbox'
import {
  Bold,
  Italic,
  Underline,
  Strikethrough,
  List,
  ListOrdered,
  Quote,
  Link as LinkIcon,
  Image as ImageIcon,
  Youtube as YoutubeIcon,
  AlignLeft,
  AlignCenter,
  AlignRight,
  Heading1,
  Heading2,
  Heading3,
  Type,
  Undo,
  Redo,
} from 'lucide-react'
import { cn } from '@/lib/utils'

interface RichTextEditorProps {
  content: string
  onChange: (content: string) => void
  placeholder?: string
  className?: string
  imageUrl?: string
  onImageUrlChange?: (url: string) => void
  centerImage?: boolean
  onCenterImageChange?: (centered: boolean) => void
}

const MenuBar = ({ editor }: { editor: any }) => {
  const [linkUrl, setLinkUrl] = React.useState('')
  const [imageUrl, setImageUrl] = React.useState('')
  const [youtubeUrl, setYoutubeUrl] = React.useState('')
  const [showLinkInput, setShowLinkInput] = React.useState(false)
  const [showImageInput, setShowImageInput] = React.useState(false)
  const [showYoutubeInput, setShowYoutubeInput] = React.useState(false)

  if (!editor) {
    return null
  }

  const addLink = useCallback(() => {
    if (linkUrl) {
      editor
        .chain()
        .focus()
        .extendMarkRange('link')
        .setLink({ href: linkUrl })
        .run()
      setLinkUrl('')
      setShowLinkInput(false)
    }
  }, [editor, linkUrl])

  const addImage = useCallback(() => {
    if (imageUrl) {
      editor.chain().focus().setImage({ src: imageUrl }).run()
      setImageUrl('')
      setShowImageInput(false)
    }
  }, [editor, imageUrl])

  const addYoutube = useCallback(() => {
    if (youtubeUrl) {
      editor.commands.setYoutubeVideo({
        src: youtubeUrl,
        width: 640,
        height: 480,
      })
      setYoutubeUrl('')
      setShowYoutubeInput(false)
    }
  }, [editor, youtubeUrl])

  const detectAndConvertLinks = useCallback(
    (text: string) => {
      // Regex para detectar URLs de vídeo
      const youtubeRegex =
        /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/embed\/)([a-zA-Z0-9_-]{11})/
      const instagramRegex =
        /(?:https?:\/\/)?(?:www\.)?instagram\.com\/(?:p|reel)\/([a-zA-Z0-9_-]+)/
      const tiktokRegex =
        /(?:https?:\/\/)?(?:www\.)?tiktok\.com\/@[^\/]+\/video\/(\d+)/

      if (youtubeRegex.test(text)) {
        const match = text.match(youtubeRegex)
        if (match) {
          const videoId = match[1]
          const embedUrl = `https://www.youtube.com/watch?v=${videoId}`
          editor.commands.setYoutubeVideo({
            src: embedUrl,
            width: 640,
            height: 480,
          })
          return true
        }
      }

      // Para Instagram e TikTok, por enquanto mantemos como links
      if (instagramRegex.test(text) || tiktokRegex.test(text)) {
        editor.chain().focus().setLink({ href: text }).run()
        return true
      }

      return false
    },
    [editor]
  )

  return (
    <div className="border-b border-gray-200 p-2 space-y-2">
