export function RichTextEditor({
  content,
  onChange,
  placeholder = 'Comece a escrever...',
  className,
  imageUrl,
  onImageUrlChange,
  centerImage,
  onCenterImageChange,
}: RichTextEditorProps) {
  const editor = useEditor({
    extensions: [
      StarterKit.configure({
        heading: {
          levels: [1, 2, 3],
        },
      }),
      Image.configure({
        HTMLAttributes: {
          class: 'max-w-full h-auto rounded-lg',
        },
      }),
      Link.configure({
        openOnClick: false,
        HTMLAttributes: {
          class: 'text-blue-600 hover:text-blue-800 underline',
        },
      }),
      TextAlign.configure({
        types: ['heading', 'paragraph'],
      }),
      Youtube.configure({
        controls: false,
        nocookie: true,
        HTMLAttributes: {
          class: 'rounded-lg max-w-full',
        },
      }),
      Placeholder.configure({
        placeholder,
      }),
    ],
    content,
    onUpdate: ({ editor }) => {
      onChange(editor.getHTML())
    },
    editorProps: {
      attributes: {
        class: 'prose prose-lg max-w-none focus:outline-none min-h-[200px] p-4',
      },
      handlePaste: (view, event) => {
        const text = event.clipboardData?.getData('text/plain')
        if (text) {
          // Detectar e converter links de vídeo automaticamente
          const youtubeRegex =
            /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/embed\/)([a-zA-Z0-9_-]{11})/
          if (youtubeRegex.test(text)) {
            event.preventDefault()
            editor?.commands.setYoutubeVideo({
              src: text,
              width: 640,
              height: 480,
            })
            return true
          }
        }
        return false
      },
    },
  })

  useEffect(() => {
    if (editor && content !== editor.getHTML()) {
      editor.commands.setContent(content)
    }
  }, [content, editor])

  return (
    <div
      className={cn(
        'border border-gray-200 rounded-lg overflow-hidden',
        className
      )}
    >
      {/* Controles da imagem de capa */}
      {imageUrl && onImageUrlChange && onCenterImageChange && (
        <div className="p-4 bg-gray-50 border-b">
          <Label className="text-sm font-medium mb-2 block">
            Imagem de Capa
          </Label>
          <div className="space-y-3">
            <div className="relative">
              <img
                src={imageUrl}
                alt="Imagem de capa"
                className={cn(
                  'max-w-full h-auto rounded-lg border',
                  centerImage ? 'mx-auto block' : ''
                )}
                style={{ maxHeight: '200px' }}
              />
            </div>
            <div className="flex items-center space-x-2">
              <Checkbox
                id="center-image"
                checked={centerImage}
                onCheckedChange={checked => onCenterImageChange(!!checked)}
              />
              <Label htmlFor="center-image" className="text-sm">
                Centralizar imagem de capa
              </Label>
            </div>
          </div>
        </div>
      )}

      <MenuBar editor={editor} />
      <EditorContent
        editor={editor}
        className="min-h-[300px] max-h-[600px] overflow-y-auto"
      />

      {/* Dica de uso */}
      <div className="p-2 bg-gray-50 border-t text-xs text-gray-600">
        <p>
          <strong>Dica:</strong> Cole links do YouTube, Instagram ou TikTok para
          incorporar vídeos automaticamente. Use Ctrl+B para negrito, Ctrl+I
          para itálico, Ctrl+Z para desfazer.
        </p>
      </div>
    </div>
  )
}

'use client'

import React, { useState, useEffect, useCallback, useRef } from 'react'
import { Label } from '@/components/ui/label'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Button } from '@/components/ui/button'
import { Card, CardContent } from '@/components/ui/card'
import { Trash2, Plus } from 'lucide-react'

interface TimeSlot {
  start: string
  end: string
}

interface DaySchedule {
  [key: string]: TimeSlot[]
}

interface ScheduleSelectorProps {
  value?: string
  onChange: (value: string) => void
  placeholder?: string
}

const DAYS_OF_WEEK = [
  { key: 'monday', label: 'Segunda-feira' },
  { key: 'tuesday', label: 'Terça-feira' },
  { key: 'wednesday', label: 'Quarta-feira' },
  { key: 'thursday', label: 'Quinta-feira' },
  { key: 'friday', label: 'Sexta-feira' },
  { key: 'saturday', label: 'Sábado' },
  { key: 'sunday', label: 'Domingo' },
]

const HOURS = Array.from({ length: 24 }, (_, i) => {
  const hour = i.toString().padStart(2, '0')
  return { value: `${hour}:00`, label: `${hour}:00` }
})

export function ScheduleSelector({
  value,
  onChange,
  placeholder,
}: ScheduleSelectorProps) {
  const [schedule, setSchedule] = useState<DaySchedule>({})
  const isInitializing = useRef(true)

  // Parse do valor inicial apenas uma vez
  useEffect(() => {
    if (value && isInitializing.current) {
      try {
        const parsed = JSON.parse(value)
        setSchedule(parsed)
      } catch {
        // Se não conseguir fazer parse, inicializa vazio
        setSchedule({})
      }
      isInitializing.current = false
    } else if (!value && isInitializing.current) {
      setSchedule({})
      isInitializing.current = false
    }
  }, [value])

  // Função para atualizar o schedule e notificar o pai
  const updateSchedule = useCallback(
    (newSchedule: DaySchedule) => {
      setSchedule(newSchedule)
      if (!isInitializing.current) {
        onChange(JSON.stringify(newSchedule))
      }
    },
    [onChange]
  )

  const addTimeSlot = (dayKey: string) => {
    const newSchedule = {
      ...schedule,
      [dayKey]: [...(schedule[dayKey] || []), { start: '08:00', end: '17:00' }],
    }
    updateSchedule(newSchedule)
  }

  const removeTimeSlot = (dayKey: string, index: number) => {
    const newSchedule = {
      ...schedule,
      [dayKey]: schedule[dayKey]?.filter((_, i) => i !== index) || [],
    }
    updateSchedule(newSchedule)
  }

  const updateTimeSlot = (
    dayKey: string,
    index: number,
    field: 'start' | 'end',
    value: string
  ) => {
    const newSchedule = {
      ...schedule,
      [dayKey]:
        schedule[dayKey]?.map((slot, i) =>
          i === index ? { ...slot, [field]: value } : slot
        ) || [],
    }
    updateSchedule(newSchedule)
  }

  const formatScheduleDisplay = () => {
    const activeDays = Object.entries(schedule).filter(
      ([_, slots]) => Array.isArray(slots) && slots.length > 0
    )
    if (activeDays.length === 0) return 'Nenhum horário configurado'

    return activeDays
      .map(([dayKey, slots]) => {
        const dayLabel =
          DAYS_OF_WEEK.find(d => d.key === dayKey)?.label || dayKey
        const timesText = Array.isArray(slots)
          ? slots.map(slot => `${slot.start}-${slot.end}`).join(', ')
          : ''
        return `${dayLabel}: ${timesText}`
      })
      .join(' | ')
  }

  return (
    <div className="space-y-4">
      <div className="text-sm text-gray-600 p-3 bg-gray-50 rounded-md">
        <strong>Horários configurados:</strong> {formatScheduleDisplay()}
      </div>

      <div className="space-y-4">
        {DAYS_OF_WEEK.map(day => (
          <Card key={day.key} className="border border-gray-200">
            <CardContent className="p-4">
              <div className="flex items-center justify-between mb-3">
                <Label className="text-sm font-medium">{day.label}</Label>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => addTimeSlot(day.key)}
                  className="flex items-center gap-1"
                >
                  <Plus className="h-3 w-3" />
                  Adicionar Horário
                </Button>
              </div>

              <div className="space-y-2">
                {schedule[day.key]?.map((slot, index) => (
                  <div key={index} className="flex items-center gap-2">
                    <div className="flex items-center gap-2 flex-1">
                      <Select
                        value={slot.start}
                        onValueChange={value =>
                          updateTimeSlot(day.key, index, 'start', value)
                        }
                      >
                        <SelectTrigger className="w-24">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {HOURS.map(hour => (
                            <SelectItem key={hour.value} value={hour.value}>
                              {hour.label}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>

                      <span className="text-sm text-gray-500">até</span>

                      <Select
                        value={slot.end}
                        onValueChange={value =>
                          updateTimeSlot(day.key, index, 'end', value)
                        }
                      >
                        <SelectTrigger className="w-24">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {HOURS.map(hour => (
                            <SelectItem key={hour.value} value={hour.value}>
                              {hour.label}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>

                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      onClick={() => removeTimeSlot(day.key, index)}
                      className="text-red-600 hover:text-red-700 hover:bg-red-50"
                    >
                      <Trash2 className="h-3 w-3" />
                    </Button>
                  </div>
                )) || (
                  <div className="text-sm text-gray-500 italic">
                    Nenhum horário configurado para este dia
                  </div>
                )}
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { Check, ChevronDown, X } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'
import { Badge } from '@/components/ui/badge'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
} from '@/components/ui/command'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import { cn } from '@/lib/utils'

interface Specialty {
  id: string
  name: string
  description?: string
}

interface SpecialtySelectorProps {
  selectedSpecialties: string[]
  onSpecialtiesChange: (specialties: string[]) => void
  disabled?: boolean
  required?: boolean
  maxSelections?: number
  placeholder?: string
  className?: string
}

export function SpecialtySelector({
  selectedSpecialties,
  onSpecialtiesChange,
  disabled = false,
  required = false,
  maxSelections = 5,
  placeholder = 'Selecione suas especialidades...',
  className,
}: SpecialtySelectorProps) {
  const [open, setOpen] = useState(false)
  const [specialties, setSpecialties] = useState<Specialty[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Carregar especialidades do banco
  useEffect(() => {
    const loadSpecialties = async () => {
      try {
        setLoading(true)
        setError(null)

        const response = await fetch('/api/specialties')
        if (!response.ok) {
          throw new Error('Erro ao carregar especialidades')
        }

        const data = await response.json()
        setSpecialties(data.specialties || [])
      } catch (err) {
        // Silent error handling - error loading specialties
        setError('Erro ao carregar especialidades')
      } finally {
        setLoading(false)
      }
    }

    loadSpecialties()
  }, [])

  const handleSpecialtyToggle = (specialtyId: string) => {
    if (disabled) return

    const isSelected = selectedSpecialties.includes(specialtyId)

    if (isSelected) {
      // Remover especialidade
      onSpecialtiesChange(selectedSpecialties.filter(id => id !== specialtyId))
    } else {
      // Adicionar especialidade (respeitando limite máximo)
      if (selectedSpecialties.length < maxSelections) {
        onSpecialtiesChange([...selectedSpecialties, specialtyId])
      }
    }
  }

  const removeSpecialty = (specialtyId: string) => {
    if (disabled) return
    onSpecialtiesChange(selectedSpecialties.filter(id => id !== specialtyId))
  }

  const getSelectedSpecialtyNames = () => {
    return specialties
      .filter(specialty => selectedSpecialties.includes(specialty.id))
      .map(specialty => specialty.name)
  }

  const canAddMore = selectedSpecialties.length < maxSelections

  if (loading) {
    return (
      <div className={cn('space-y-2', className)}>
        <Label>Especialidades {required && '*'}</Label>
        <div className="h-11 border border-gray-200 rounded-md flex items-center px-3 bg-gray-50">
          <span className="text-gray-500 text-sm">
            Carregando especialidades...
          </span>
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className={cn('space-y-2', className)}>
        <Label>Especialidades {required && '*'}</Label>
        <div className="h-11 border border-red-200 rounded-md flex items-center px-3 bg-red-50">
          <span className="text-red-500 text-sm">{error}</span>
        </div>
      </div>
    )
  }

  return (
    <div className={cn('space-y-2', className)}>
      <Label>
        Especialidades {required && '*'}
        <span className="text-xs text-gray-500 ml-2">
          (máximo {maxSelections} especialidades)
        </span>
      </Label>

      {/* Especialidades selecionadas */}
      {selectedSpecialties.length > 0 && (
        <div className="flex flex-wrap gap-2 mb-2">
          {getSelectedSpecialtyNames().map((name, index) => (
            <Badge
              key={selectedSpecialties[index]}
              variant="secondary"
              className="bg-[#4AB0D9]/10 text-[#4AB0D9] border-[#4AB0D9]/20 hover:bg-[#4AB0D9]/20"
            >
              {name}
              {!disabled && (
                <button
                  type="button"
                  className="ml-1 hover:bg-[#4AB0D9]/30 rounded-full p-0.5"
                  onClick={() => removeSpecialty(selectedSpecialties[index])}
                >
                  <X className="h-3 w-3" />
                </button>
              )}
            </Badge>
          ))}
        </div>
      )}

      {/* Seletor de especialidades */}
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <Button
            variant="outline"
            role="combobox"
            aria-expanded={open}
            className={cn(
              'w-full h-11 justify-between',
              !canAddMore && 'opacity-50 cursor-not-allowed',
              disabled && 'opacity-50 cursor-not-allowed'
            )}
            disabled={disabled || !canAddMore}
          >
            <span className="text-left truncate">
              {selectedSpecialties.length === 0
                ? placeholder
                : `${selectedSpecialties.length} especialidade${selectedSpecialties.length > 1 ? 's' : ''} selecionada${selectedSpecialties.length > 1 ? 's' : ''}`}
            </span>
            <ChevronDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-full p-0" align="start">
          <Command>
            <CommandInput placeholder="Buscar especialidade..." />
            <CommandEmpty>Nenhuma especialidade encontrada.</CommandEmpty>
            <CommandGroup className="max-h-64 overflow-auto">
              {specialties.map(specialty => {
                const isSelected = selectedSpecialties.includes(specialty.id)
                const canSelect = canAddMore || isSelected

                return (
                  <CommandItem
                    key={specialty.id}
                    value={specialty.name}
                    onSelect={() => handleSpecialtyToggle(specialty.id)}
                    className={cn(
                      'cursor-pointer',
                      !canSelect &&
                        !isSelected &&
                        'opacity-50 cursor-not-allowed'
                    )}
                    disabled={!canSelect && !isSelected}
                  >
                    <Check
                      className={cn(
                        'mr-2 h-4 w-4',
                        isSelected ? 'opacity-100' : 'opacity-0'
                      )}
                    />
                    <div className="flex-1">
                      <div className="font-medium">{specialty.name}</div>
                      {specialty.description && (
                        <div className="text-xs text-gray-500 mt-1">
                          {specialty.description}
                        </div>
                      )}
                    </div>
                  </CommandItem>
                )
              })}
            </CommandGroup>
          </Command>
        </PopoverContent>
      </Popover>

      {/* Informações adicionais */}
      <div className="text-xs text-gray-500">
        {selectedSpecialties.length > 0 && (
          <span>
            {selectedSpecialties.length}/{maxSelections} especialidades
            selecionadas
          </span>
        )}
        {!canAddMore && (
          <span className="text-amber-600 ml-2">Limite máximo atingido</span>
        )}
      </div>
    </div>
  )
}

