import React, { useState, useEffect } from 'react'

export function useLocalStorage<T>(
  key: string,
  initialValue: T
): [T, (value: T | ((val: T) => T)) => void] {
  // Estado para armazenar nosso valor
  // Passar função de estado inicial para useState para que a lógica seja executada apenas uma vez
  const [storedValue, setStoredValue] = useState<T>(() => {
    if (typeof window === 'undefined') {
      return initialValue
    }
    try {
      // Obter do localStorage local por chave
      const item = window.localStorage.getItem(key)
      // Analisar JSON armazenado ou se nenhum retornar initialValue
      return item ? JSON.parse(item) : initialValue
    } catch (error) {
      // Se erro também retornar initialValue
      console.log(error)
      return initialValue
    }
  })

  // Retornar uma versão envolvida da função setter useState que ...
  // ... persiste o novo valor no localStorage.
  const setValue = (value: T | ((val: T) => T)) => {
    try {
      // Permitir que value seja uma função para que tenhamos a mesma API que useState
      const valueToStore =
        value instanceof Function ? value(storedValue) : value
      // Salvar estado
      setStoredValue(valueToStore)
      // Salvar no localStorage
      if (typeof window !== 'undefined') {
        window.localStorage.setItem(key, JSON.stringify(valueToStore))
      }
    } catch (error) {
      // Uma implementação mais avançada lidaria com o caso de erro
      console.log(error)
    }
  }

  return [storedValue, setValue]
}

export function useIsomorphicLayoutEffect(
  effect: React.EffectCallback,
  deps?: React.DependencyList
) {
  const useEffect =
    typeof window !== 'undefined' ? React.useLayoutEffect : React.useEffect
  return useEffect(effect, deps)
}

// Hook para verificar se estamos no cliente
export function useIsClient() {
  const [isClient, setIsClient] = useState(false)

  useEffect(() => {
    setIsClient(true)
  }, [])

  return isClient
}

import { useState, useEffect, useCallback, useRef } from 'react'
import { supabase } from '@/lib/supabase'
import { BlogViewsService, BlogPostViewStats } from '@/lib/blog-views-service'
import { RealtimeChannel } from '@supabase/supabase-js'

interface UseRealtimeBlogViewsProps {
  blogPostId: string
  initialStats?: BlogPostViewStats
}

export function useRealtimeBlogViews({
  blogPostId,
  initialStats,
}: UseRealtimeBlogViewsProps) {
  const [stats, setStats] = useState<BlogPostViewStats>(
    initialStats || {
      totalViews: 0,
      uniqueViews: 0,
      lastViewAt: null,
    }
  )
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const channelRef = useRef<RealtimeChannel | null>(null)
  const hasRecordedView = useRef(false)

  // Carregar estatísticas iniciais
  const loadInitialStats = useCallback(async () => {
    if (initialStats) return

    try {
      setIsLoading(true)
      setError(null)
      const viewStats = await BlogViewsService.getViewStats(blogPostId)
      setStats(viewStats)
    } catch (err) {
      console.error('Erro ao carregar estatísticas iniciais:', err)
      setError('Erro ao carregar estatísticas de visualização')
    } finally {
      setIsLoading(false)
    }
  }, [blogPostId, initialStats])

  // Registrar uma nova visualização
  const recordView = useCallback(
    async (viewerId?: string) => {
      if (hasRecordedView.current) return

      try {
        hasRecordedView.current = true
        const updatedStats = await BlogViewsService.recordView(
          blogPostId,
          viewerId,
          undefined, // IP será obtido no backend se necessário
          navigator.userAgent
        )
        setStats(updatedStats)
      } catch (err) {
        console.error('Erro ao registrar visualização:', err)
        hasRecordedView.current = false
      }
    },
    [blogPostId]
  )

  // Atualizar estatísticas manualmente
  const refreshStats = useCallback(async () => {
    try {
      setIsLoading(true)
      setError(null)
      const viewStats = await BlogViewsService.getViewStats(blogPostId)
      setStats(viewStats)
    } catch (err) {
      console.error('Erro ao atualizar estatísticas:', err)
      setError('Erro ao atualizar estatísticas')
    } finally {
      setIsLoading(false)
    }
  }, [blogPostId])

  // Configurar Realtime
  useEffect(() => {
    if (!blogPostId) return

    // Carregar estatísticas iniciais
    loadInitialStats()

    // Configurar canal Realtime
    const channel = supabase
      .channel(`blog_post_views:${blogPostId}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'blog_post_views',
          filter: `blog_post_id=eq.${blogPostId}`,
        },
        async payload => {
          console.log('Nova visualização recebida:', payload)

          // Atualizar estatísticas quando uma nova visualização é inserida
          try {
            const updatedStats = await BlogViewsService.getViewStats(blogPostId)
            setStats(updatedStats)
          } catch (err) {
            console.error('Erro ao atualizar estatísticas em tempo real:', err)
          }
        }
      )
      .subscribe(status => {
        console.log('Status do canal Realtime para blog views:', status)
      })

    channelRef.current = channel

    return () => {
      if (channelRef.current) {
        supabase.removeChannel(channelRef.current)
        channelRef.current = null
      }
    }
  }, [blogPostId, loadInitialStats])

  return {
    stats,
    isLoading,
    error,
    recordView,
    refreshStats,
  }
}

// Hook para múltiplos blog posts
interface UseRealtimeBlogViewsBulkProps {
