            )

            // Atualizar apenas as estatísticas do post específico
            try {
              const updatedStats = await BlogViewsService.getViewStats(
                newView.blog_post_id
              )
              setStatsMap(prev => ({
                ...prev,
                [newView.blog_post_id]: updatedStats,
              }))
            } catch (err) {
              console.error(
                'Erro ao atualizar estatísticas em tempo real:',
                err
              )
            }
          }
        }
      )
      .subscribe(status => {
        console.log('Status do canal Realtime para blog views bulk:', status)
      })

    channelRef.current = channel

    return () => {
      if (channelRef.current) {
        supabase.removeChannel(channelRef.current)
        channelRef.current = null
      }
    }
  }, [blogPostIds, loadInitialStats])

  return {
    statsMap,
    isLoading,
    error,
    refreshStats,
    getStatsForPost: (postId: string) =>
      statsMap[postId] || { totalViews: 0, uniqueViews: 0, lastViewAt: null },
  }
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { createSupabaseClient } from '@/lib/supabase'
import {
  getUserNotifications,
  markNotificationAsRead,
  markAllNotificationsAsRead,
  getUnreadNotificationsCount,
  deleteNotification as deleteNotificationService,
  type NotificationData,
} from '@/lib/notifications-service'
import { useUser } from '@/hooks/use-user'
import { RealtimeChannel } from '@supabase/supabase-js'

export interface RealtimeNotification {
  id: string
  user_id: string
  notification_type: string
  title: string
  message: string
  data?: any
  read: boolean
  created_at: string
}

export function useRealtimeNotifications() {
  const { user } = useUser()
  const [notifications, setNotifications] = useState<NotificationData[]>([])
  const [unreadCount, setUnreadCount] = useState(0)
  const [loading, setLoading] = useState(true)
  const [channel, setChannel] = useState<RealtimeChannel | null>(null)
  const supabase = createSupabaseClient()

  // Função para mapear tipos do banco para tipos da interface
  const mapNotificationType = useCallback(
    (dbType: string): 'info' | 'success' | 'warning' | 'error' => {
      switch (dbType) {
        case 'appointment':
          return 'success'
        case 'message':
          return 'info'
        case 'forum':
          return 'info'
        case 'reminder':
          return 'warning'
        case 'system':
          return 'error'
        default:
          return 'info'
      }
    },
    []
  )

  // Converter notificação do banco para o formato da interface
  const convertNotification = useCallback(
    (dbNotification: RealtimeNotification): NotificationData => ({
      id: dbNotification.id,
      title: dbNotification.title,
      message: dbNotification.message || '',
      type: mapNotificationType(dbNotification.notification_type || 'info'),
      originalType: dbNotification.notification_type as
        | 'message'
        | 'appointment'
        | 'forum'
        | 'reminder'
        | 'system',
      read: dbNotification.read,
      createdAt: dbNotification.created_at,
      userId: dbNotification.user_id,
      actionUrl: undefined,
      metadata: dbNotification.data,
    }),
    [mapNotificationType]
  )

  // Carregar notificações iniciais
  const loadNotifications = useCallback(async () => {
    if (!user?.id) return

    try {
      setLoading(true)
      const [notificationsData, unreadCountData] = await Promise.all([
        getUserNotifications(user.id, 50),
        getUnreadNotificationsCount(user.id),
      ])

      setNotifications(notificationsData)
      setUnreadCount(unreadCountData)
    } catch (error) {
      console.error('Erro ao carregar notificações:', error)
    } finally {
      setLoading(false)
    }
  }, [user?.id])

  // Marcar notificação como lida
  const markAsRead = useCallback(async (notificationId: string) => {
    try {
      const success = await markNotificationAsRead(notificationId)
      if (success) {
        setNotifications(prev =>
          prev.map(notification =>
            notification.id === notificationId
              ? { ...notification, read: true }
              : notification
          )
        )
        setUnreadCount(prev => Math.max(0, prev - 1))
      }
    } catch (error) {
      console.error('Erro ao marcar notificação como lida:', error)
    }
  }, [])

  // Marcar todas como lidas
  const markAllAsRead = useCallback(async () => {
    if (!user?.id) return

    try {
      const success = await markAllNotificationsAsRead(user.id)
      if (success) {
        setNotifications(prev =>
          prev.map(notification => ({ ...notification, read: true }))
        )
        setUnreadCount(0)
      }
    } catch (error) {
      console.error('Erro ao marcar todas as notificações como lidas:', error)
    }
  }, [user?.id])

  const deleteNotification = useCallback(async (notificationId: string) => {
    try {
      const success = await deleteNotificationService(notificationId)
      if (success) {
        setNotifications(prev =>
          prev.filter(notification => notification.id !== notificationId)
        )
      }
    } catch (error) {
      console.error('Erro ao deletar notificação:', error)
    }
  }, [])

  // Configurar realtime
  useEffect(() => {
    if (!user?.id) return

    // Carregar notificações iniciais
    loadNotifications()

    // Configurar canal realtime
    const realtimeChannel = supabase
      .channel('realtime_notifications')
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'realtime_notifications',
          filter: `user_id=eq.${user.id}`,
        },
        payload => {
          console.log('Nova notificação recebida:', payload)
          const newNotification = convertNotification(
            payload.new as RealtimeNotification
          )

          setNotifications(prev => [newNotification, ...prev])
          setUnreadCount(prev => prev + 1)

          // Mostrar notificação do navegador se permitido
          if (
            'Notification' in window &&
            Notification.permission === 'granted'
          ) {
            new Notification(newNotification.title, {
              body: newNotification.message,
              icon: '/favicon.ico',
              tag: newNotification.id,
            })
          }
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'realtime_notifications',
          filter: `user_id=eq.${user.id}`,
        },
        payload => {
          console.log('Notificação atualizada:', payload)
          const updatedNotification = convertNotification(
            payload.new as RealtimeNotification
          )

          setNotifications(prev =>
            prev.map(notification =>
              notification.id === updatedNotification.id
                ? updatedNotification
                : notification
            )
          )

          // Atualizar contador se mudou o status de lida
          if (payload.old && payload.new) {
            const oldRead = (payload.old as RealtimeNotification).read
            const newRead = (payload.new as RealtimeNotification).read

            if (!oldRead && newRead) {
              setUnreadCount(prev => Math.max(0, prev - 1))
            } else if (oldRead && !newRead) {
              setUnreadCount(prev => prev + 1)
            }
          }
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'DELETE',
          schema: 'public',
          table: 'realtime_notifications',
          filter: `user_id=eq.${user.id}`,
        },
        payload => {
          console.log('Notificação deletada:', payload)
          const deletedId = (payload.old as RealtimeNotification).id
          const wasUnread = !(payload.old as RealtimeNotification).read

          setNotifications(prev =>
            prev.filter(notification => notification.id !== deletedId)
          )

          if (wasUnread) {
            setUnreadCount(prev => Math.max(0, prev - 1))
          }
        }
      )
      .subscribe()

    setChannel(realtimeChannel)

    // Solicitar permissão para notificações do navegador
    if ('Notification' in window && Notification.permission === 'default') {
      Notification.requestPermission()
    }

    return () => {
      if (realtimeChannel) {
        supabase.removeChannel(realtimeChannel)
      }
    }
  }, [user?.id, loadNotifications, convertNotification])

  // Cleanup ao desmontar
  useEffect(() => {
    return () => {
      if (channel) {
        supabase.removeChannel(channel)
      }
    }
  }, [channel, supabase])

  return {
    notifications,
    unreadCount,
    loading,
    markAsRead,
    markAllAsRead,
    deleteNotification,
    refetch: loadNotifications,
  }
}

'use client'

import { useState, useEffect, useCallback, useRef } from 'react'
import { supabase } from '@/lib/supabase'
import { RealtimeChannel } from '@supabase/supabase-js'

export interface NutritionistProfile {
  id: string
  user_id: string
  full_name: string
  bio?: string
  location?: string
  profile_image_url?: string
  crn: string
  rating?: number
  total_reviews?: number
  experience_years?: number
  is_verified: boolean
  nutritionist_services?: any[]
  nutritionist_specialties?: any[]
}

export interface UseRealtimeNutritionistsProps {
  searchTerm?: string
  specialty?: string
  state?: string
  priceRange?: { min: number; max: number }
  onlineOnly?: boolean
  verifiedOnly?: boolean
  sortBy?: string
}

export function useRealtimeNutritionists(
  filters: UseRealtimeNutritionistsProps = {}
) {
  const [nutritionists, setNutritionists] = useState<NutritionistProfile[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const channelRef = useRef<RealtimeChannel | null>(null)

  // Função para carregar nutricionistas com filtros
  const loadNutritionists = useCallback(async () => {
    try {
      setLoading(true)
      setError(null)

      // Query simplificada sem especialidades para teste
      let query = supabase.from('nutritionist_profiles').select(`
        id,
        user_id,
        full_name,
        bio,
        location,
        profile_image_url,
        crn,
        rating,
        total_reviews,
        experience_years,
        is_verified,
        nutritionist_services (*)
      `)

      // Aplicar filtros
      if (filters.searchTerm) {
        query = query.or(
          `full_name.ilike.%${filters.searchTerm}%,bio.ilike.%${filters.searchTerm}%`
        )
      }

      if (filters.state && filters.state !== 'Todas') {
        query = query.ilike('location', `%${filters.state}%`)
      }

      if (filters.verifiedOnly) {
        query = query.eq('is_verified', true)
      }

      // Filtrar apenas nutricionistas aprovados (conforme política RLS)
      query = query.eq('verification_status', 'aprovado')

      const { data, error } = await query

      if (error) {
        console.error('Error loading nutritionists:', error)
        throw error
      }

      let filteredData: NutritionistProfile[] = data || []

      // Filtrar nutricionistas com IDs válidos
      filteredData = filteredData.filter(nutritionist => {
        if (
          !nutritionist.id ||
          nutritionist.id === 'null' ||
          nutritionist.id === 'undefined'
        ) {
          console.warn(
            'Nutricionista com ID inválido encontrado:',
            nutritionist
          )
          return false
        }
        return true
      })

      // Filtrar por especialidade (temporariamente desabilitado)
      // if (filters.specialty && filters.specialty !== "Todas") {
      //   filteredData = filteredData.filter((nutritionist) =>
      //     nutritionist.nutritionist_specialties?.some(
      //       (spec: any) => spec.specialties?.name === filters.specialty,
      //     ),
      //   )
      // }

      // Filtrar por preço
      if (filters.priceRange) {
        filteredData = filteredData.filter(nutritionist => {
          const minPrice = getMinPrice(nutritionist.nutritionist_services)
          if (minPrice === null) return false
          return (
            minPrice >= filters.priceRange!.min &&
            minPrice <= filters.priceRange!.max
          )
        })
      }

      // Filtrar por consulta online
      if (filters.onlineOnly) {
        filteredData = filteredData.filter(nutritionist =>
          nutritionist.nutritionist_services?.some(
            (service: any) => service.online_available
          )
        )
      }

      // Ordenar
      filteredData.sort((a, b) => {
        switch (filters.sortBy) {
          case 'rating':
            return (b.rating || 0) - (a.rating || 0)
          case 'price-low':
            return (
              (getMinPrice(a.nutritionist_services) || 0) -
              (getMinPrice(b.nutritionist_services) || 0)
            )
          case 'price-high':
            return (
              (getMinPrice(b.nutritionist_services) || 0) -
              (getMinPrice(a.nutritionist_services) || 0)
            )
          case 'name':
            return a.full_name.localeCompare(b.full_name)
          case 'experience':
            return (b.experience_years || 0) - (a.experience_years || 0)
          default:
            return 0
        }
      })

      setNutritionists(filteredData)
    } catch (error) {
      console.error('Error loading nutritionists:', error)
      setError('Erro ao carregar nutricionistas')
    } finally {
      setLoading(false)
    }
  }, [filters, supabase])

  // Função auxiliar para obter preço mínimo
  const getMinPrice = (services: any[]) => {
    if (!services || services.length === 0) return null
    return Math.min(...services.map(service => service.price))
  }

  // Configurar realtime para monitorar mudanças
  useEffect(() => {
    // Carregar dados iniciais
    loadNutritionists()

    // Configurar canal realtime
    const channel = supabase
      .channel('nutritionist_profiles_changes')
      .on(
        'postgres_changes',
        {
          event: '*', // Escutar INSERT, UPDATE, DELETE
          schema: 'public',
          table: 'nutritionist_profiles',
        },
        payload => {
          console.log('🔄 Mudança detectada em nutritionist_profiles:', payload)
          // Recarregar dados quando houver mudanças
          loadNutritionists()
        }
      )
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'nutritionist_services',
        },
        payload => {
          console.log('🔄 Mudança detectada em nutritionist_services:', payload)
          // Recarregar dados quando houver mudanças nos serviços
          loadNutritionists()
        }
      )
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'nutritionist_specialties',
        },
        payload => {
          console.log(
            '🔄 Mudança detectada em nutritionist_specialties:',
            payload
          )
          // Recarregar dados quando houver mudanças nas especialidades
          loadNutritionists()
        }
      )
      .subscribe(status => {
        if (status === 'SUBSCRIBED') {
          console.log(
            '✅ Inscrito em atualizações de nutricionistas em tempo real'
          )
        } else if (status === 'CHANNEL_ERROR') {
          console.error(
            '❌ Erro ao inscrever-se em atualizações de nutricionistas'
          )
        }
      })

    channelRef.current = channel

    // Cleanup
    return () => {
      if (channelRef.current) {
        supabase.removeChannel(channelRef.current)
        channelRef.current = null
        console.log('🔌 Desconectado das atualizações de nutricionistas')
      }
    }
  }, [loadNutritionists, supabase])

  // Função para atualizar manualmente
  const refreshNutritionists = useCallback(() => {
    loadNutritionists()
  }, [loadNutritionists])

  return {
    nutritionists,
    loading,
    error,
    refreshNutritionists,
  }
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { createSupabaseClient } from '@/lib/supabase'
import { profileViewsService } from '@/lib/profile-views-service'
import { RealtimeChannel } from '@supabase/supabase-js'

export interface ProfileViewStats {
  totalViews: number
  uniqueViews: number
  lastViewAt: string | null
}

export function useRealtimeProfileViews(
  nutritionistId: string,
  initialStats?: ProfileViewStats
) {
  const [viewStats, setViewStats] = useState<ProfileViewStats>(
    initialStats || {
      totalViews: 0,
      uniqueViews: 0,
      lastViewAt: null,
    }
  )
  const [loading, setLoading] = useState(true)
  const [channel, setChannel] = useState<RealtimeChannel | null>(null)
  const supabase = createSupabaseClient()

  // Carregar estatísticas iniciais
  const loadViewStats = useCallback(async () => {
    if (!nutritionistId) return

    try {
      setLoading(true)
      const stats = await profileViewsService.getViewStats(nutritionistId)
      if (stats) {
        setViewStats({
          totalViews: stats.total_views,
          uniqueViews: stats.unique_views,
          lastViewAt: stats.last_view_at,
        })
      }
    } catch (error) {
      console.error('Erro ao carregar estatísticas de visualização:', error)
    } finally {
      setLoading(false)
    }
  }, [nutritionistId])

  // Atualizar estatísticas quando uma nova visualização é registrada
  const handleNewView = useCallback(async () => {
    try {
      const stats = await profileViewsService.getViewStats(nutritionistId)
      if (stats) {
        setViewStats({
          totalViews: stats.total_views,
          uniqueViews: stats.unique_views,
          lastViewAt: stats.last_view_at,
        })
      }
    } catch (error) {
      console.error('Erro ao atualizar estatísticas de visualização:', error)
    }
  }, [nutritionistId])

  // Configurar realtime
  useEffect(() => {
    if (!nutritionistId) return

    // Carregar estatísticas iniciais
    loadViewStats()

    // Configurar canal realtime para escutar novas visualizações
    const realtimeChannel = supabase
      .channel(`profile_views_${nutritionistId}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'profile_views',
          filter: `nutritionist_id=eq.${nutritionistId}`,
        },
        payload => {
          console.log('Nova visualização registrada:', payload)
          // Atualizar estatísticas quando uma nova visualização é inserida
          handleNewView()
        }
      )
      .subscribe(status => {
        if (status === 'SUBSCRIBED') {
          console.log(
            `✅ Inscrito em atualizações de visualização para nutricionista: ${nutritionistId}`
          )
        } else if (status === 'CHANNEL_ERROR') {
          console.error(
            '❌ Erro ao inscrever-se em atualizações de visualização'
          )
        }
      })

    setChannel(realtimeChannel)

    // Cleanup
    return () => {
      if (realtimeChannel) {
        realtimeChannel.unsubscribe()
        console.log(
          `🔌 Desconectado das atualizações de visualização para nutricionista: ${nutritionistId}`
        )
      }
    }
  }, [nutritionistId, loadViewStats, handleNewView, supabase])

  // Registrar uma nova visualização
  const recordView = useCallback(async () => {
    try {
      await profileViewsService.recordView(nutritionistId)
      // As estatísticas serão atualizadas automaticamente via realtime
    } catch (error) {
      console.error('Erro ao registrar visualização:', error)
      // Em caso de erro, tentar atualizar as estatísticas manualmente
      handleNewView()
    }
  }, [nutritionistId, handleNewView])

  return {
    viewStats,
    loading,
    recordView,
    refreshStats: loadViewStats,
  }
}

'use client'

import { useState, useEffect } from 'react'
import { getCurrentUser, getUserProfile } from '@/lib/auth'
import type { User } from '@supabase/supabase-js'

interface ExtendedUser extends User {
  companyProfile?: any
  nutritionistProfile?: any
  patientProfile?: any
}

export function useUser() {
  const [user, setUser] = useState<ExtendedUser | null>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    const loadUser = async () => {
      try {
        const currentUser = await getCurrentUser()
        if (currentUser) {
          const extendedUser: ExtendedUser = currentUser

          // Carregar perfil específico baseado no tipo de usuário
          if (currentUser.user_type === 'empresa') {
            try {
              const { data: companyProfile } = await getUserProfile(
                currentUser.id,
                'empresa'
              )
              extendedUser.companyProfile = companyProfile
            } catch (error) {
              // Error loading company profile - silently handled
            }
          } else if (currentUser.user_type === 'nutricionista') {
            try {
              const { data: nutritionistProfile } = await getUserProfile(
                currentUser.id,
                'nutricionista'
              )
              extendedUser.nutritionistProfile = nutritionistProfile
            } catch (error) {
              // Error loading nutritionist profile - silently handled
            }
          } else if (currentUser.user_type === 'paciente') {
            try {
              const { data: patientProfile } = await getUserProfile(
                currentUser.id,
                'paciente'
              )
              extendedUser.patientProfile = patientProfile
            } catch (error) {
              // Error loading patient profile - silently handled
            }
          }

          setUser(extendedUser)
        } else {
          setUser(null)
        }
      } catch (error) {
        // Error loading user - silently handled
        setUser(null)
      } finally {
        setLoading(false)
      }
    }

    loadUser()
  }, [])

  return { user, loading }
}

import { nutritionistAddressService } from './nutritionist-address-service'

export interface AddressData {
  id?: string
  nutritionist_id?: string
  type: 'in_person' | 'teleconsultation'
  status: 'active' | 'inactive'
  is_main: boolean
  country: string
  state: string
  city: string
  neighborhood?: string
  zip_code?: string
  street?: string
  number?: string
  complement?: string
  latitude?: number
  longitude?: number
  service_radius_km?: number
}

/**
 * Save addresses for a nutritionist after registration
 */
export async function saveNutritionistAddresses(
  nutritionistId: string,
  addresses: AddressData[]
): Promise<void> {
  if (!addresses || addresses.length === 0) {
    return
  }

  try {
    // Save each address
    for (const address of addresses) {
      const addressData = {
        ...address,
        nutritionist_id: nutritionistId,
      }

      await nutritionistAddressService.createAddress(addressData)
    }
  } catch (error) {
    // Silent error handling: Error saving nutritionist addresses
    throw new Error('Erro ao salvar endereços do nutricionista')
  }
}

/**
 * Get addresses for display during registration
 */
export function getAddressDisplayText(address: AddressData): string {
  const parts = []

  if (address.street) {
    parts.push(address.street)
    if (address.number) {
      parts[parts.length - 1] += `, ${address.number}`
    }
  }

  if (address.neighborhood) {
    parts.push(address.neighborhood)
  }

  parts.push(`${address.city}/${address.state}`)

  if (address.zip_code) {
    parts.push(`CEP: ${address.zip_code}`)
  }

  return parts.join(' - ')
}

