      return null
    }

    // Obter usuário atual do Supabase
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser()

    if (authError) {
      // Silent error handling: Error getting user
      // Se o erro for de sessão ausente, retornar null silenciosamente
      if (
        authError.message?.includes('session') ||
        authError.message?.includes('Auth')
      ) {
        return null
      }
      return null
    }

    if (!user) {
      // Silent logging: No user logged in
      return null
    }

    // Silent logging: User found

    // Buscar dados do usuário na tabela users
    const { data: userData, error: userError } = await supabase
      .from('users')
      .select('*')
      .eq('id', user.id)
      .single()

    if (userError) {
      // Silent error handling: Error fetching user data
      // Se não encontrar na tabela users, tentar obter do user_metadata
      const userType =
        user.user_metadata?.user_type ||
        user.app_metadata?.user_type ||
        'paciente'
      // Silent logging: Using user_type from metadata
      return {
        id: user.id,
        email: user.email,
        user_type: userType as UserType,
      }
    }

    // Silent logging: User data loaded
    // Garantir que user_type sempre tenha um valor
    if (!userData.user_type) {
      userData.user_type = 'paciente'
      // Silent logging: user_type was undefined, setting as patient
    }
    return userData
  } catch (error: any) {
    // Silent error handling: General error getting current user
    // Se for erro de sessão, não logar como erro crítico
    if (
      error.message?.includes('AuthSessionMissingError') ||
      error.message?.includes('session')
    ) {
      // Silent logging: Session not found - user not logged in
      return null
    }
    return null
  }
}

export async function getUserProfile(userId: string, userType: UserType) {
  let tableName = ''

  switch (userType) {
    case 'nutricionista':
      tableName = 'nutritionist_profiles'
      break
    case 'paciente':
      tableName = 'patient_profiles'
      break
    case 'empresa':
      tableName = 'company_profiles'
      break
    default:
      return { data: null, error: 'Tipo de usuário inválido' }
  }

  const { data, error } = await supabase
    .from(tableName)
    .select('*')
    .eq('user_id', userId)
    .single()

  if (error) {
    // Silent error handling: Error fetching user profile
    throw error
  }

  // Processar dados para garantir tipos corretos, especialmente para nutricionistas
  let processedData: any = data // Usar "any" temporariamente para flexibilidade no processamento

  if (userType === 'nutricionista') {
    const nutritionistProfile = processedData as any // Cast para any para acessar propriedades dinamicamente

    // Função helper para processar campos que podem estar com escape duplo
    const processField = (field: any, fieldName?: string): string[] => {
      let result

      // Usar normalizadores específicos quando disponível
      if (fieldName === 'languages') {
        result = normalizeLanguages(field)
      } else if (fieldName === 'specialties') {
        result = normalizeSpecialties(field)
      } else {
        result = normalizeStringArray(field)
      }

      // Log eventos de normalização para telemetria
      if (result.wasCorrupted) {
        logNormalizationEvent(fieldName || 'unknown_field', result, {
          context: 'auth-service',
        })
      }

      return result.data
    }

    // Campos que podem vir como string separada por vírgulas e devem ser arrays
    nutritionistProfile.specialties = processField(
      nutritionistProfile.specialties,
      'specialties'
    )
    nutritionistProfile.languages = processField(
      nutritionistProfile.languages,
      'languages'
    )
    nutritionistProfile.certifications = processField(
      nutritionistProfile.certifications,
      'certifications'
    )
    nutritionistProfile.achievements = processField(
      nutritionistProfile.achievements,
      'achievements'
    )

    // Campos JSON removidos - agora usando campos individuais
    // Os campos services, testimonials, working_hours e social_media foram
    // convertidos para campos individuais para evitar erros de parsing JSON
    processedData = nutritionistProfile
  }

  return { data: processedData, error: null }
}

import { createSupabaseClient } from './supabase'

const supabase = createSupabaseClient()

export interface TimeSlot {
  start: string
  end: string
}

export interface DaySchedule {
  [key: string]: TimeSlot[]
}

export interface AvailabilitySlot {
  id?: string
  nutritionist_id: string
  day_of_week: number
  start_time: string
  end_time: string
  is_available: boolean
}

const DAY_MAPPING: { [key: string]: number } = {
  monday: 1,
  tuesday: 2,
  wednesday: 3,
  thursday: 4,
  friday: 5,
  saturday: 6,
  sunday: 0,
}

/**
 * Converte o objeto de horários do ScheduleSelector para slots de disponibilidade
 */
export function convertScheduleToAvailability(
  schedule: DaySchedule,
  nutritionistId: string
): AvailabilitySlot[] {
  const slots: AvailabilitySlot[] = []

  Object.entries(schedule).forEach(([dayKey, timeSlots]) => {
    const dayOfWeek = DAY_MAPPING[dayKey]
    if (dayOfWeek !== undefined && Array.isArray(timeSlots)) {
      timeSlots.forEach(slot => {
        if (slot.start && slot.end) {
          slots.push({
            nutritionist_id: nutritionistId,
            day_of_week: dayOfWeek,
            start_time: slot.start,
            end_time: slot.end,
            is_available: true,
          })
        }
      })
    }
  })

  return slots
}

/**
 * Salva os horários de disponibilidade do nutricionista
 */
export async function saveNutritionistAvailability(
  nutritionistId: string,
  schedule: DaySchedule
): Promise<void> {
  try {
    // Primeiro, remove todos os horários existentes do nutricionista
    const { error: deleteError } = await supabase
      .from('nutritionist_availability')
      .delete()
      .eq('nutritionist_id', nutritionistId)

    if (deleteError) {
      throw new Error(
        `Erro ao limpar horários existentes: ${deleteError.message}`
      )
    }

    // Converte o schedule para slots de disponibilidade
    const availabilitySlots = convertScheduleToAvailability(
      schedule,
      nutritionistId
    )

    // Se há slots para inserir, insere todos de uma vez
    if (availabilitySlots.length > 0) {
      const { error: insertError } = await supabase
        .from('nutritionist_availability')
        .insert(availabilitySlots)

      if (insertError) {
        throw new Error(`Erro ao salvar novos horários: ${insertError.message}`)
      }
    }
  } catch (error) {
    console.error('Erro ao salvar disponibilidade do nutricionista:', error)
    throw error
  }
}

/**
 * Busca os horários de disponibilidade do nutricionista
 */
export async function getNutritionistAvailability(
  nutritionistId: string
): Promise<DaySchedule> {
  try {
    const { data, error } = await supabase
      .from('nutritionist_availability')
      .select('*')
      .eq('nutritionist_id', nutritionistId)
      .eq('is_available', true)
      .order('day_of_week')
      .order('start_time')

    if (error) {
      throw new Error(`Erro ao buscar horários: ${error.message}`)
    }

    // Converte os dados do banco para o formato do ScheduleSelector
    const schedule: DaySchedule = {}
    const reverseDayMapping: { [key: number]: string } = {
      0: 'sunday',
      1: 'monday',
      2: 'tuesday',
      3: 'wednesday',
      4: 'thursday',
      5: 'friday',
      6: 'saturday',
    }

    data?.forEach(slot => {
      const dayKey = reverseDayMapping[slot.day_of_week]
      if (dayKey) {
        if (!schedule[dayKey]) {
          schedule[dayKey] = []
        }
        schedule[dayKey].push({
          start: slot.start_time,
          end: slot.end_time,
        })
      }
    })

    return schedule
  } catch (error) {
    console.error('Erro ao buscar disponibilidade do nutricionista:', error)
    return {}
  }
}

