// Função para deletar um post
export async function deleteBlogPost(
  id: string,
  authenticatedSupabase?: any
): Promise<boolean> {
  // Silent logging: Starting deleteBlogPost for ID

  try {
    // Usar o cliente autenticado se fornecido, senão usar o padrão
    const clientToUse = authenticatedSupabase || supabase

    // Verificar se o usuário está autenticado
    // Silent logging: Checking authentication
    const {
      data: { user },
      error: authError,
    } = await clientToUse.auth.getUser()

    if (authError || !user) {
      // Silent error handling: User not authenticated
      return false
    }

    // Silent logging: User authenticated

    // Primeiro, verificar se o post existe e se o usuário é o autor
    // Silent logging: Searching post to verify authorization
    const { data: post, error: fetchError } = await clientToUse
      .from('blog_posts')
      .select('author_id, title')
      .eq('id', id)
      .single()

    if (fetchError || !post) {
      // Silent error handling: Post not found
      return false
    }

    // Silent logging: Post found

    // Verificar se o usuário autenticado é o autor do post
    if (post.author_id !== user.id) {
      // Silent error handling: User not authorized to delete this post
      return false
    }

    // Silent logging: Authorization confirmed, proceeding with deletion

    // Deletar o post
    // Silent logging: Executing DELETE on Supabase
    const { data: deletedData, error } = await clientToUse
      .from('blog_posts')
      .delete()
      .eq('id', id)
      .eq('author_id', user.id) // Dupla verificação de segurança
      .select() // Retorna os dados deletados

    if (error) {
      // Silent error handling: Error deleting post
      return false
    }

    // Silent logging: DELETE response

    if (!deletedData || deletedData.length === 0) {
      // Silent error handling: No record was deleted, possible RLS or condition issue
      return false
    }

    // Silent logging: Post deleted successfully
    return true
  } catch (error) {
    // Silent error handling: Unexpected error deleting post
    return false
  }
}

import { supabase } from './supabase'

export interface BlogPostViewStats {
  totalViews: number
  uniqueViews: number
  lastViewAt: string | null
}

export class BlogViewsService {
  /**
   * Registra uma nova visualização para um blog post
   */
  static async recordView(
    blogPostId: string,
    viewerId?: string,
    viewerIp?: string,
    userAgent?: string
  ): Promise<BlogPostViewStats> {
    try {
      const { data, error } = await supabase.rpc('increment_blog_post_views', {
        post_id: blogPostId,
        viewer_user_id: viewerId || null,
        viewer_ip_address: viewerIp || null,
        viewer_user_agent: userAgent || null,
      })

      if (error) {
        // Silent error handling: Error registering blog post view
        throw error
      }

      return {
        totalViews: data.total_views || 0,
        uniqueViews: data.unique_views || 0,
        lastViewAt: data.last_view_at || null,
      }
    } catch (error) {
      // Silent error handling: Error registering blog post view
      throw error
    }
  }

  /**
   * Obtém as estatísticas de visualização de um blog post
   */
  static async getViewStats(blogPostId: string): Promise<BlogPostViewStats> {
    try {
      const { data, error } = await supabase
        .from('blog_post_views')
        .select('*')
        .eq('blog_post_id', blogPostId)

      if (error) {
        // Silent error handling: Error getting view statistics
        throw error
      }

      const totalViews = data?.length || 0
      const uniqueViews = new Set(
        data?.map(view => view.viewer_id).filter(Boolean)
      ).size
      const lastViewAt =
        data?.length > 0
          ? data.sort(
              (a, b) =>
                new Date(b.created_at).getTime() -
                new Date(a.created_at).getTime()
            )[0].created_at
          : null

      return {
        totalViews,
        uniqueViews,
        lastViewAt,
      }
    } catch (error) {
      // Silent error handling: Error getting view statistics
      return {
        totalViews: 0,
        uniqueViews: 0,
        lastViewAt: null,
      }
    }
  }

  /**
   * Obtém as estatísticas de visualização de múltiplos blog posts
   */
  static async getBulkViewStats(
    blogPostIds: string[]
  ): Promise<Record<string, BlogPostViewStats>> {
    try {
      const { data, error } = await supabase
        .from('blog_post_views')
        .select('blog_post_id, viewer_id, created_at')
        .in('blog_post_id', blogPostIds)

      if (error) {
        // Silent error handling: Error getting bulk statistics
        throw error
      }

      const stats: Record<string, BlogPostViewStats> = {}

      // Inicializar todos os posts com estatísticas zeradas
      blogPostIds.forEach(id => {
        stats[id] = {
          totalViews: 0,
          uniqueViews: 0,
          lastViewAt: null,
        }
      })

      // Processar dados de visualização
      if (data) {
        const groupedByPost = data.reduce(
          (acc, view) => {
            if (!acc[view.blog_post_id]) {
              acc[view.blog_post_id] = []
            }
            acc[view.blog_post_id].push(view)
            return acc
          },
          {} as Record<string, typeof data>
        )

        Object.entries(groupedByPost).forEach(([postId, views]) => {
          const totalViews = views.length
          const uniqueViews = new Set(
            views.map(v => v.viewer_id).filter(Boolean)
          ).size
          const lastViewAt =
            views.length > 0
              ? views.sort(
                  (a, b) =>
                    new Date(b.created_at).getTime() -
                    new Date(a.created_at).getTime()
                )[0].created_at
              : null

          stats[postId] = {
            totalViews,
            uniqueViews,
            lastViewAt,
          }
        })
      }

      return stats
    } catch (error) {
      // Silent error handling: Error getting bulk statistics
      return {}
    }
  }
}

import { revalidateTag, revalidatePath } from 'next/cache'

export const CACHE_TAGS = {
  NUTRITIONISTS: 'nutritionists',
  SPECIALTIES: 'specialties',
  APPOINTMENTS: 'appointments',
  PROFILES: 'profiles',
  DASHBOARD: 'dashboard',
  BLOG: 'blog',
  FORUM: 'forum',
  COMPANIES: 'companies',
  PATIENTS: 'patients',
  RATINGS: 'ratings',
  NOTIFICATIONS: 'notifications',
} as const

export const CACHE_PATHS = {
  HOME: '/',
  DASHBOARD: '/dashboard',
  NUTRITIONISTS: '/nutricionistas',
  BLOG: '/blog',
  FORUM: '/forum',
  COMPANIES: '/para-empresas',
  PATIENTS: '/para-pacientes',
} as const

export class CacheManager {
  private static buildId = process.env.BUILD_ID || 'development'

  /**
   * Revalida cache por tag específica
   */
  static revalidateByTag(tag: string) {
    try {
      revalidateTag(tag)
      return true
    } catch (error) {
      return false
    }
  }

  /**
   * Revalida cache por path específico
   */
  static revalidateByPath(path: string) {
    try {
      revalidatePath(path)
      return true
    } catch (error) {
      return false
    }
  }

  /**
   * Revalida múltiplas tags
   */
  static revalidateMultipleTags(tags: string[]) {
    const results = tags.map(tag => ({
      tag,
      success: this.revalidateByTag(tag),
    }))

    return results
  }

  /**
   * Revalida múltiplos paths
   */
  static revalidateMultiplePaths(paths: string[]) {
    const results = paths.map(path => ({
      path,
      success: this.revalidateByPath(path),
    }))

    return results
  }

  /**
   * Revalida cache relacionado a nutricionistas
   */
  static revalidateNutritionistData() {
    return this.revalidateMultipleTags([
      CACHE_TAGS.NUTRITIONISTS,
      CACHE_TAGS.SPECIALTIES,
      CACHE_TAGS.PROFILES,
      CACHE_TAGS.RATINGS,
    ])
  }

  /**
   * Revalida cache relacionado ao dashboard
   */
  static revalidateDashboardData() {
    return this.revalidateMultipleTags([
      CACHE_TAGS.DASHBOARD,
      CACHE_TAGS.APPOINTMENTS,
      CACHE_TAGS.PROFILES,
      CACHE_TAGS.NOTIFICATIONS,
    ])
  }

  /**
   * Revalida cache relacionado a empresas
   */
  static revalidateCompanyData() {
    return this.revalidateMultipleTags([
      CACHE_TAGS.COMPANIES,
      CACHE_TAGS.PROFILES,
      CACHE_TAGS.DASHBOARD,
    ])
  }

  /**
   * Flush completo de cache
   */
  static flushAll() {
    const allTags = Object.values(CACHE_TAGS)
    const allPaths = Object.values(CACHE_PATHS)

    const tagResults = this.revalidateMultipleTags(allTags)
    const pathResults = this.revalidateMultiplePaths(allPaths)

    return {
      tags: tagResults,
      paths: pathResults,
      buildId: this.buildId,
      timestamp: new Date().toISOString(),
    }
  }

  /**
   * Gera chave de cache com build ID
   */
  static generateCacheKey(key: string): string {
    return `${key}-${this.buildId}`
  }

  /**
   * Verifica se o cache deve ser invalidado baseado no build ID
   */
  static shouldInvalidateCache(storedBuildId?: string): boolean {
    return !storedBuildId || storedBuildId !== this.buildId
  }
}

/**
 * Hook para invalidar cache local no browser
 */
export function invalidateBrowserCache() {
  if (typeof window !== 'undefined') {
    // Limpar localStorage relacionado ao cache
    const cacheKeys = Object.keys(localStorage).filter(
      key =>
        key.startsWith('cache-') ||
        key.startsWith('build-') ||
        key.includes('cached')
    )

    cacheKeys.forEach(key => {
      localStorage.removeItem(key)
    })

    // Limpar sessionStorage relacionado ao cache
    const sessionCacheKeys = Object.keys(sessionStorage).filter(
      key =>
        key.startsWith('cache-') ||
        key.startsWith('build-') ||
        key.includes('cached')
    )

    sessionCacheKeys.forEach(key => {
      sessionStorage.removeItem(key)
    })
  }
}

/**
 * Utilitário para fetch com cache inteligente
 */
export async function fetchWithCache<T>(
  url: string,
  options: RequestInit & {
    cacheKey?: string
    cacheTags?: string[]
    revalidate?: number
  } = {}
): Promise<T> {
  const { cacheKey, cacheTags, revalidate, ...fetchOptions } = options

  const headers = {
    ...fetchOptions.headers,
    'X-Build-ID': CacheManager.buildId,
  }

  if (cacheTags) {
    headers['X-Cache-Tags'] = cacheTags.join(',')
  }

  const response = await fetch(url, {
    ...fetchOptions,
    headers,
    next: {
      tags: cacheTags,
      revalidate: revalidate || 60,
    },
  })

  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`)
  }

  return response.json()
}

