// Função para curtir um item do fórum
export async function likeForumItem(
  itemId: string,
  type: 'question' | 'reply',
  userId: string
): Promise<boolean> {
  try {
    const tableName =
      type === 'question' ? 'forum_question_likes' : 'forum_answer_likes'
    const columnName = type === 'question' ? 'question_id' : 'answer_id'

    // Verificar se já curtiu
    const { data: existingLike } = await supabase
      .from(tableName)
      .select('id')
      .eq(columnName, itemId)
      .eq('user_id', userId)
      .single()

    if (existingLike) {
      // Remover curtida
      const { error } = await supabase
        .from(tableName)
        .delete()
        .eq(columnName, itemId)
        .eq('user_id', userId)

      return !error
    } else {
      // Adicionar curtida
      const { error } = await supabase.from(tableName).insert({
        [columnName]: itemId,
        user_id: userId,
      })

      return !error
    }
  } catch (error) {
    // Silent error handling - likeForumItem failed
    return false
  }
}

