// Função para limpar dados não persistidos do fórum
export async function cleanupForumData(): Promise<{
  deletedQuestions: number
  deletedAnswers: number
  deletedLikes: number
}> {
  try {
    // Silent cleanup process start
    let deletedQuestions = 0
    let deletedAnswers = 0
    let deletedLikes = 0

    // 1. Remover perguntas órfãs (sem autor válido)
    const { data: orphanQuestions } = await supabase
      .from('forum_questions')
      .select('id, author_id')
      .not('author_id', 'is', null)

    if (orphanQuestions) {
      for (const question of orphanQuestions) {
        // Verificar se o usuário ainda existe
        const { data: user } = await supabase
          .from('users')
          .select('id')
          .eq('id', question.author_id)
          .single()

        if (!user) {
          const { error } = await supabase
            .from('forum_questions')
            .delete()
            .eq('id', question.id)

          if (!error) {
            deletedQuestions++
            // Silent orphan question removal
          }
        }
      }
    }

    // 2. Remover respostas órfãs (sem autor válido ou pergunta válida)
    const { data: orphanAnswers } = await supabase
      .from('forum_answers')
      .select('id, author_id, question_id')
      .not('author_id', 'is', null)

    if (orphanAnswers) {
      for (const answer of orphanAnswers) {
        let shouldDelete = false

        // Verificar se o usuário ainda existe
        const { data: user } = await supabase
          .from('users')
          .select('id')
          .eq('id', answer.author_id)
          .single()

        if (!user) {
          shouldDelete = true
        } else {
          // Verificar se a pergunta ainda existe
          const { data: question } = await supabase
            .from('forum_questions')
            .select('id')
            .eq('id', answer.question_id)
            .single()

          if (!question) {
            shouldDelete = true
          }
        }

        if (shouldDelete) {
          const { error } = await supabase
            .from('forum_answers')
            .delete()
            .eq('id', answer.id)

          if (!error) {
            deletedAnswers++
            // Silent orphan answer removal
          }
        }
      }
    }

    // 3. Remover likes órfãos (de perguntas ou respostas que não existem mais)
    const { data: orphanQuestionLikes } = await supabase
      .from('forum_question_likes')
      .select('id, question_id, user_id')

    if (orphanQuestionLikes) {
      for (const like of orphanQuestionLikes) {
        let shouldDelete = false

        // Verificar se a pergunta ainda existe
        const { data: question } = await supabase
          .from('forum_questions')
          .select('id')
          .eq('id', like.question_id)
          .single()

        if (!question) {
          shouldDelete = true
        } else {
          // Verificar se o usuário ainda existe
          const { data: user } = await supabase
            .from('users')
            .select('id')
            .eq('id', like.user_id)
            .single()

          if (!user) {
            shouldDelete = true
          }
        }

        if (shouldDelete) {
          const { error } = await supabase
            .from('forum_question_likes')
            .delete()
            .eq('id', like.id)

          if (!error) {
            deletedLikes++
            // Silent orphan question like removal
          }
        }
      }
    }

    const { data: orphanAnswerLikes } = await supabase
      .from('forum_answer_likes')
      .select('id, answer_id, user_id')

    if (orphanAnswerLikes) {
      for (const like of orphanAnswerLikes) {
        let shouldDelete = false

        // Verificar se a resposta ainda existe
        const { data: answer } = await supabase
          .from('forum_answers')
          .select('id')
          .eq('id', like.answer_id)
          .single()

        if (!answer) {
          shouldDelete = true
        } else {
          // Verificar se o usuário ainda existe
          const { data: user } = await supabase
            .from('users')
            .select('id')
            .eq('id', like.user_id)
            .single()

          if (!user) {
            shouldDelete = true
          }
        }

        if (shouldDelete) {
          const { error } = await supabase
            .from('forum_answer_likes')
            .delete()
            .eq('id', like.id)

          if (!error) {
            deletedLikes++
            // Silent orphan answer like removal
          }
        }
      }
    }

    // Silent cleanup completion
    return {
      deletedQuestions,
      deletedAnswers,
      deletedLikes,
    }
  } catch (error) {
    // Silent error handling - cleanup failed
    throw error
  }
}

import { createSupabaseClient } from './supabase'
import { createClient } from '@supabase/supabase-js'

export interface UploadResult {
  success: boolean
  url?: string
  error?: string
}

export interface ProfileImageUploadResult extends UploadResult {
  variants?: {
    original: string
    large?: string
    medium?: string
    small?: string
  }
}

/**
 * Faz upload de uma imagem para o bucket blog-images do Supabase Storage
 * @param file - Arquivo de imagem a ser enviado
 * @param userId - ID do usuário que está fazendo o upload
 * @returns Promise com resultado do upload
 */
export async function uploadBlogImage(
  file: File,
  userId: string
): Promise<UploadResult> {
  try {
    // Criar cliente Supabase para verificação de autenticação
    const supabase = createSupabaseClient()

    // Verificar se o usuário está autenticado
    const {
      data: { session },
      error: sessionError,
    } = await supabase.auth.getSession()

    if (sessionError) {
      // Silent error handling - error getting session
      return {
        success: false,
        error: 'Erro de autenticação. Faça login novamente.',
      }
    }

    if (!session || !session.access_token) {
      // Silent error handling - user not authenticated
      return {
        success: false,
        error: 'Usuário não autenticado. Faça login para listar imagens.',
      }
    }

    // Verificar se o userId passado corresponde ao usuário autenticado
    if (session.user.id !== userId) {
      // Silent error handling - userId mismatch
      return {
        success: false,
        error: 'Erro de autorização. O usuário não pode listar estas imagens.',
      }
    }

    // Criar cliente com service role para contornar RLS
    const serviceSupabase = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    )

    // Listar arquivos do usuário usando service role
    const { data, error } = await serviceSupabase.storage
      .from('blog-images')
      .list(userId, {
        limit: 100,
        sortBy: { column: 'created_at', order: 'desc' },
      })

    if (error) {
      // Silent error handling - error listing images
      return {
        success: false,
        error: 'Erro ao listar imagens.',
      }
    }

    // Converter para URLs públicas
    const imageUrls = data.map(file => {
      const { data: urlData } = serviceSupabase.storage
        .from('blog-images')
        .getPublicUrl(`${userId}/${file.name}`)
      return urlData.publicUrl
    })

    return {
      success: true,
      images: imageUrls,
    }
  } catch (error) {
    // Silent error handling - unexpected list error
    return {
      success: false,
      error: 'Erro inesperado ao listar imagens.',
    }
  }
}

