/**
 * Deleta uma imagem de perfil do Supabase Storage
 * @param imageUrl - URL da imagem a ser deletada
 * @param userId - ID do usuário que está deletando
 * @param userType - Tipo do usuário (nutritionist, patient, company)
 * @returns Promise com resultado da operação
 */
export async function deleteProfileImage(
  imageUrl: string,
  userId: string,
  userType: 'nutritionist' | 'patient' | 'company'
): Promise<UploadResult> {
  try {
    // Criar cliente Supabase para verificação de autenticação
    const supabase = createSupabaseClient()

    // Verificar se o usuário está autenticado
    const {
      data: { session },
      error: sessionError,
    } = await supabase.auth.getSession()

    if (sessionError) {
      // Silent error handling - error getting session
      return {
        success: false,
        error: 'Erro de autenticação. Faça login novamente.',
      }
    }

    if (!session || !session.access_token) {
      // Silent error handling - user not authenticated
      return {
        success: false,
        error: 'Usuário não autenticado. Faça login para excluir imagens.',
      }
    }

    // Verificar se o userId passado corresponde ao usuário autenticado
    if (session.user.id !== userId) {
      // Silent error handling - userId mismatch
      return {
        success: false,
        error: 'Erro de autorização. O usuário não pode excluir esta imagem.',
      }
    }

    // Criar cliente com service role para contornar RLS
    const serviceSupabase = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    )

    // Determinar o bucket baseado no tipo de usuário
    const bucketName =
      userType === 'company'
        ? 'company-assets'
        : userType === 'nutritionist'
          ? 'nutritionist-photos'
          : 'patient-photos'

    // Extrair o nome do arquivo da URL
    const urlParts = imageUrl.split('/')
    const fileName = urlParts[urlParts.length - 1]
    const folderName =
      userType === 'company'
        ? 'logos'
        : userType === 'nutritionist'
          ? 'nutritionist-profiles'
          : 'patient-profiles'
    const filePath = `${folderName}/${fileName}`

    // Excluir o arquivo do Supabase Storage usando service role
    const { error } = await serviceSupabase.storage
      .from(bucketName)
      .remove([filePath])

    if (error) {
      // Silent error handling: Image deletion error
      return {
        success: false,
        error: 'Erro ao deletar a imagem.',
      }
    }

    return {
      success: true,
    }
  } catch (error) {
    // Silent error handling: Image deletion error
    return {
      success: false,
      error: 'Erro inesperado ao deletar a imagem.',
    }
  }
}

import { createSupabaseClient } from './supabase'

const supabase = createSupabaseClient()

export interface NotificationData {
  id: string
  title: string
  message: string
  type: 'info' | 'success' | 'warning' | 'error'
  originalType?: 'message' | 'appointment' | 'forum' | 'reminder' | 'system'
  read: boolean
  createdAt: string
  userId: string
  actionUrl?: string
  metadata?: Record<string, any>
}

// Função para mapear tipos do banco para tipos da interface
function mapNotificationType(
  dbType: string
): 'info' | 'success' | 'warning' | 'error' {
  switch (dbType) {
    case 'appointment':
      return 'success'
    case 'message':
      return 'info'
    case 'forum':
      return 'info'
    case 'reminder':
      return 'warning'
    case 'system':
      return 'error'
    default:
      return 'info'
  }
}

/**
 * Buscar notificações do usuário
 */
export async function getUserNotifications(
  userId: string,
  limit = 50
): Promise<NotificationData[]> {
  try {
    const { data: notifications, error } = await supabase
      .from('realtime_notifications')
      .select('*')
      .eq('user_id', userId)
      .order('created_at', { ascending: false })
      .limit(limit)

    if (error) {
      // Silent error handling: Error fetching notifications
      return []
    }

    return notifications.map(notification => ({
      id: notification.id,
      title: notification.title || 'Notificação',
      message: notification.message || '',
      type: mapNotificationType(notification.notification_type || 'info'),
      originalType: notification.notification_type as
        | 'message'
        | 'appointment'
        | 'forum'
        | 'reminder'
        | 'system',
      read: notification.read || false,
      createdAt: notification.created_at,
      userId: notification.user_id,
      actionUrl: notification.action_url,
      metadata: notification.data,
    }))
  } catch (error) {
    // Silent error handling: Error in getUserNotifications
    return []
  }
}

