import { createSupabaseClient } from './supabase'
import { saveNutritionistAvailability } from './availability-service'
import type { DaySchedule } from './availability-service'

// Usar o cliente que mantém a autenticação
const supabase = createSupabaseClient()
import type {
  PatientProfile,
  NutritionistProfile,
  CompanyProfile,
  UserType,
} from './supabase'

export async function updateUserProfile(
  userId: string,
  userType: UserType,
  profileData: Partial<PatientProfile | NutritionistProfile | CompanyProfile>
) {
  let tableName = ''
  switch (userType) {
    case 'paciente':
      tableName = 'patient_profiles'
      break
    case 'nutricionista':
      tableName = 'nutritionist_profiles'
      break
    case 'empresa':
      tableName = 'company_profiles'
      break
    default:
      throw new Error('Tipo de usuário inválido para atualização de perfil.')
  }

  // Remover campos que não devem ser atualizados ou que são gerados automaticamente
  const dataToUpdate: any = { ...profileData }
  delete dataToUpdate.id
  delete dataToUpdate.user_id
  delete dataToUpdate.created_at
  delete dataToUpdate.updated_at
  delete dataToUpdate.email // Email é do auth, não do profile

  // Para nutricionistas, extrair e processar horários de disponibilidade separadamente
  let availabilitySchedule: DaySchedule | null = null
  if (userType === 'nutricionista' && dataToUpdate.available_times) {
    try {
      // Se available_times é uma string JSON, fazer parse
      if (typeof dataToUpdate.available_times === 'string') {
        availabilitySchedule = JSON.parse(dataToUpdate.available_times)
      } else if (typeof dataToUpdate.available_times === 'object') {
        availabilitySchedule = dataToUpdate.available_times
      }

      // Remover available_times do update do perfil, será salvo na tabela específica
      delete dataToUpdate.available_times
    } catch (error) {
      console.error('Erro ao processar horários de disponibilidade:', error)
      delete dataToUpdate.available_times
    }
  }

  // Converter arrays de string para o formato correto se necessário (ex: de string separada por vírgulas)
  if (userType === 'paciente') {
    if (
      dataToUpdate.health_conditions &&
      typeof dataToUpdate.health_conditions === 'string'
    ) {
      dataToUpdate.health_conditions = dataToUpdate.health_conditions
        .split(',')
        .map((s: string) => s.trim())
        .filter(Boolean)
    }
    if (dataToUpdate.allergies && typeof dataToUpdate.allergies === 'string') {
      dataToUpdate.allergies = dataToUpdate.allergies
        .split(',')
        .map((s: string) => s.trim())
        .filter(Boolean)
    }
    if (
      dataToUpdate.dietary_preferences &&
      typeof dataToUpdate.dietary_preferences === 'string'
    ) {
      dataToUpdate.dietary_preferences = dataToUpdate.dietary_preferences
        .split(',')
        .map((s: string) => s.trim())
        .filter(Boolean)
    }
  } else if (userType === 'nutricionista') {
    if (
      dataToUpdate.specialties &&
      typeof dataToUpdate.specialties === 'string'
    ) {
      dataToUpdate.specialties = dataToUpdate.specialties
        .split(',')
        .map((s: string) => s.trim())
        .filter(Boolean)
    }
    if (
      dataToUpdate.available_times &&
      typeof dataToUpdate.available_times === 'string'
    ) {
      dataToUpdate.available_times = dataToUpdate.available_times
        .split(',')
        .map((s: string) => s.trim())
        .filter(Boolean)
    }
    if (dataToUpdate.languages && typeof dataToUpdate.languages === 'string') {
      dataToUpdate.languages = dataToUpdate.languages
        .split(',')
        .map((s: string) => s.trim())
        .filter(Boolean)
    }
    if (
      dataToUpdate.certifications &&
      typeof dataToUpdate.certifications === 'string'
    ) {
      dataToUpdate.certifications = dataToUpdate.certifications
        .split(',')
        .map((s: string) => s.trim())
        .filter(Boolean)
    }
    if (
      dataToUpdate.achievements &&
      typeof dataToUpdate.achievements === 'string'
    ) {
      dataToUpdate.achievements = dataToUpdate.achievements
        .split(',')
        .map((s: string) => s.trim())
        .filter(Boolean)
    }
    // Campos JSON removidos - agora usando campos individuais
    // Os campos services, testimonials, working_hours e social_media foram
    // convertidos para campos individuais para evitar erros de parsing JSON
  }

  const { data, error } = await supabase
    .from(tableName)
    .update(dataToUpdate)
    .eq('user_id', userId)
    .select()
    .single()

  if (error) {
    throw new Error(`Erro ao atualizar perfil: ${error.message}`)
  }

  // Se é nutricionista e tem horários de disponibilidade, salvar na tabela específica
  if (userType === 'nutricionista' && availabilitySchedule && userId) {
    try {
      await saveNutritionistAvailability(userId, availabilitySchedule)
    } catch (availabilityError) {
      console.error(
        'Erro ao salvar horários de disponibilidade:',
        availabilityError
      )
      // Não falhar a operação inteira por causa dos horários
      // O perfil foi salvo com sucesso, apenas os horários falharam
    }
  }

  return data
}

import { supabase } from './supabase'

export interface ProfileView {
  id: string
  nutritionist_id: string
  viewer_ip?: string
  viewer_user_agent?: string
  viewed_at: string
  session_id?: string
  referrer?: string
  created_at: string
}

export interface ProfileViewStats {
  total_views: number
  unique_views: number
  last_view_at?: string
  daily_views?: { date: string; unique_views: number }[]
}

class ProfileViewsService {
  // Registrar uma nova visualização
  async recordView(nutritionistId: string, referrer?: string): Promise<void> {
    try {
      // Gerar um session_id único para esta sessão do navegador
      let sessionId = sessionStorage.getItem('profile_view_session')
      if (!sessionId) {
        sessionId = `sess_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
        sessionStorage.setItem('profile_view_session', sessionId)
      }

      // Verificar se já registrou uma visualização para este nutricionista nesta sessão
      const viewedKey = `viewed_${nutritionistId}`
      const alreadyViewed = sessionStorage.getItem(viewedKey)

      if (alreadyViewed) {
        return // Já registrou uma visualização nesta sessão
      }

      const { error } = await supabase.from('profile_views').insert({
        nutritionist_id: nutritionistId,
        viewer_user_agent: navigator.userAgent,
        session_id: sessionId,
        referrer: referrer || document.referrer || 'direct',
      })

      if (error) {
        // Silent error handling - error registering view
        return
      }

      // Marcar como visualizado nesta sessão
      sessionStorage.setItem(viewedKey, 'true')
    } catch (error) {
      // Silent error handling - error recording view
    }
  }

  // Obter estatísticas de visualizações para um nutricionista
  async getViewStats(nutritionistId: string): Promise<ProfileViewStats> {
    try {
      const { data, error } = await supabase
        .from('nutritionist_profiles')
        .select('total_views, unique_views, last_view_at')
        .eq('id', nutritionistId)
        .single()

      if (error) {
        // Silent error handling - error getting view stats
        // Retorna valores padrão em caso de erro
        return {
          total_views: 0,
          unique_views: 0,
          last_view_at: undefined,
        }
      }

      return {
        total_views: data.total_views || 0,
        unique_views: data.unique_views || 0,
        last_view_at: data.last_view_at,
      }
    } catch (error) {
      // Silent error handling - error getting view stats
      // Retorna valores padrão em caso de erro
      return {
        total_views: 0,
        unique_views: 0,
        last_view_at: undefined,
      }
    }
  }

  // Obter visualizações diárias para um nutricionista (últimos 30 dias)
  async getDailyViews(
    nutritionistId: string,
    daysBack: number = 30
  ): Promise<{ date: string; unique_views: number }[]> {
    try {
      // Usar query direta em vez de RPC para evitar problemas de sessão
      const { data, error } = await supabase
        .from('profile_views')
        .select('viewed_at')
        .eq('nutritionist_id', nutritionistId)
        .gte(
          'viewed_at',
          new Date(Date.now() - daysBack * 24 * 60 * 60 * 1000).toISOString()
        )
        .order('viewed_at', { ascending: false })

      if (error) {
        // Silent error handling - error getting daily views
        return []
      }

      // Processar dados para agrupar por dia
      const dailyViews: { [key: string]: Set<string> } = {}
      data?.forEach(view => {
        const date = new Date(view.viewed_at).toISOString().split('T')[0]
        if (!dailyViews[date]) {
          dailyViews[date] = new Set()
        }
        dailyViews[date].add(view.viewed_at) // Usar timestamp como identificador único
      })

      return Object.entries(dailyViews)
        .map(([date, views]) => ({
          date,
          unique_views: views.size,
        }))
        .sort((a, b) => a.date.localeCompare(b.date))
    } catch (error) {
      // Silent error handling - error getting daily views
      return []
    }
  }

  // Obter total de visualizações usando query direta
  async getTotalViews(nutritionistId: string): Promise<number> {
    try {
      const { count, error } = await supabase
        .from('profile_views')
        .select('*', { count: 'exact', head: true })
        .eq('nutritionist_id', nutritionistId)

      if (error) {
        // Silent error handling - error getting total views
        return 0
      }

      return count || 0
    } catch (error) {
      // Silent error handling - error getting total views
      return 0
    }
  }

  // Obter visualizações únicas usando query direta
  async getUniqueViews(nutritionistId: string): Promise<number> {
    try {
      const { data, error } = await supabase
        .from('profile_views')
        .select('session_id')
        .eq('nutritionist_id', nutritionistId)

      if (error) {
        // Silent error handling - error getting unique views
        return 0
      }

      // Contar sessões únicas
      const uniqueSessions = new Set(
        data?.map(view => view.session_id).filter(Boolean)
      )
      return uniqueSessions.size
    } catch (error) {
      // Silent error handling - error getting unique views
      return 0
    }
  }

  // Obter visualizações recentes para um nutricionista (para dashboard)
  async getRecentViews(
    nutritionistId: string,
    limit: number = 10
  ): Promise<ProfileView[]> {
    try {
      const { data, error } = await supabase
        .from('profile_views')
        .select('*')
        .eq('nutritionist_id', nutritionistId)
        .order('viewed_at', { ascending: false })
        .limit(limit)

      if (error) {
        // Silent error handling - error getting recent views
        return []
      }

      return data || []
    } catch (error) {
      // Silent error handling - error getting recent views
      return []
    }
  }
}

